export const DOCS: DocEntry[] = [{"slug":"superadmin-manual","title":"Platform Super-Admin — User Manual","category":"manual","audience":"Platform Super-Admin","blurb":"Run the whole airin platform: tenants, modules, pricing, health.","order":0,"words":2572,"minutes":13,"toc":[{"id":"table-of-contents","text":"Table of contents","level":2},{"id":"1-sign-in","text":"1. Sign in","level":2},{"id":"2-get-your-bearings--the-layout","text":"2. Get your bearings — the layout","level":2},{"id":"3-the-platform-overview","text":"3. The Platform Overview","level":2},{"id":"4-create-a-new-business-tenant","text":"4. Create a new business (tenant)","level":2},{"id":"5-open-and-manage-one-business","text":"5. Open and manage one business","level":2},{"id":"6-turn-features-on-and-off-modules","text":"6. Turn features on and off (modules)","level":2},{"id":"7-subscription-plans--pricing","text":"7. Subscription plans & pricing","level":2},{"id":"8-billing--invoices","text":"8. Billing & invoices","level":2},{"id":"9-monitoring--system-health","text":"9. Monitoring & system health","level":2},{"id":"10-ai-usage--the-ai-flow-catalog","text":"10. AI usage & the AI flow catalog","level":2},{"id":"11-support--impersonation","text":"11. Support & impersonation","level":2},{"id":"111-view-as--preview-any-tenants-world-from-the-hub","text":"11.1 \"View as\" — preview any tenant's world from the Hub","level":3},{"id":"12-announcements-config--platform-users","text":"12. Announcements, Config & Platform Users","level":2},{"id":"121-announcements--notices-to-tenants","text":"12.1 Announcements — notices to tenants","level":3},{"id":"122-platform-config--global-defaults--feature-flags","text":"12.2 Platform Config — global defaults & feature flags","level":3},{"id":"123-platform-users--other-admins","text":"12.3 Platform Users — other admins","level":3},{"id":"13-everyday-checklists","text":"13. Everyday checklists","level":2}],"html":"<h1 id=\"platform-super-admin--user-manual\">Platform Super-Admin — User Manual</h1>\n<p><strong>Who this is for:</strong> you run the <strong>airin</strong> platform itself. You don&#39;t belong to any one\nbusiness — you create the businesses (called <strong>tenants</strong>), decide what each one is allowed to use,\nset the prices the platform charges them, and keep an eye on the health of everything.</p>\n<p>Your workspace is the <strong>Platform Admin</strong> area at <code>/admin</code>. Everything in this manual happens there.</p>\n<blockquote>\n<p><strong>Important — two different worlds.</strong> The Platform Admin area (<code>/admin</code>) is <strong>only</strong> for platform\nsuper-admins (you). The businesses themselves are run by their owners from a completely separate\n<strong>Dashboard</strong> (<code>/dashboard</code>). You create the business here; the owner runs it there. If an owner\never says &quot;I can&#39;t find the Platform Admin menu&quot;, that&#39;s expected — they&#39;re not supposed to.</p>\n</blockquote>\n<hr>\n<h2 id=\"table-of-contents\">Table of contents</h2>\n<ol>\n<li><a href=\"#1-sign-in\">Sign in</a></li>\n<li><a href=\"#2-get-your-bearings--the-layout\">Get your bearings — the layout</a></li>\n<li><a href=\"#3-the-platform-overview\">The Platform Overview</a></li>\n<li><a href=\"#4-create-a-new-business-tenant\">Create a new business (tenant)</a></li>\n<li><a href=\"#5-open-and-manage-one-business\">Open and manage one business</a></li>\n<li><a href=\"#6-turn-features-on-and-off-modules\">Turn features on and off (modules)</a></li>\n<li><a href=\"#7-subscription-plans--pricing\">Subscription plans &amp; pricing</a></li>\n<li><a href=\"#8-billing--invoices\">Billing &amp; invoices</a></li>\n<li><a href=\"#9-monitoring--system-health\">Monitoring &amp; system health</a></li>\n<li><a href=\"#10-ai-usage--the-ai-flow-catalog\">AI usage &amp; the AI flow catalog</a></li>\n<li><a href=\"#11-support--impersonation\">Support, impersonation &amp; &quot;view as&quot;</a></li>\n<li><a href=\"#12-announcements-config--platform-users\">Announcements, Config &amp; Platform Users</a></li>\n<li><a href=\"#13-everyday-checklists\">Everyday checklists</a></li>\n</ol>\n<hr>\n<h2 id=\"1-sign-in\">1. Sign in</h2>\n<ol>\n<li>Open the app URL in any browser.</li>\n<li>On the sign-in screen, either <strong>click the &quot;Super Admin&quot; demo card</strong> (it fills the credentials for\nyou) or type your email and password and click <strong>Sign in</strong>.</li>\n<li>You land on the <strong>Hub</strong>. Click the <strong>Platform Admin</strong> tile to enter <code>/admin</code>.</li>\n</ol>\n<p><img src=\"/docs/images/00-login.png\" alt=\"The sign-in screen. The \"Super Admin\" quick-login card is top-left; the email/password form is below.\" loading=\"lazy\" /></p>\n<blockquote>\n<p><strong>Language:</strong> the <strong>EN / ID</strong> toggle (English / Indonesian) is on every screen, including this one.\nSwitch any time — it never affects your data.</p>\n</blockquote>\n<hr>\n<h2 id=\"2-get-your-bearings--the-layout\">2. Get your bearings — the layout</h2>\n<p>Every Platform Admin page has the same <strong>left sidebar</strong>. It&#39;s grouped so related tools sit together:</p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>Menu items</th>\n<th>What they&#39;re for</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><em>(top)</em></td>\n<td><strong>Hub</strong>, <strong>Overview</strong></td>\n<td>Return to the launcher; the platform dashboard</td>\n</tr>\n<tr>\n<td><strong>TENANTS</strong></td>\n<td><strong>Tenants</strong>, <strong>Support</strong></td>\n<td>Create/manage businesses; help a business in trouble</td>\n</tr>\n<tr>\n<td><strong>GROWTH</strong></td>\n<td><strong>Analytics</strong>, <strong>Billing</strong>, <strong>Subscription Plans</strong>, <strong>AI Usage</strong></td>\n<td>Money &amp; adoption</td>\n</tr>\n<tr>\n<td><strong>OPERATIONS</strong></td>\n<td><strong>Monitoring</strong>, <strong>System Health</strong>, <strong>Agent Flows</strong></td>\n<td>Keep the platform running</td>\n</tr>\n<tr>\n<td><strong>PLATFORM</strong></td>\n<td><strong>Platform Users</strong>, <strong>Announcements</strong>, <strong>Audit Log</strong>, <strong>Platform Config</strong></td>\n<td>Admin accounts, tenant-wide notices, the audit trail, and global settings</td>\n</tr>\n</tbody></table>\n<p>At the <strong>bottom-left</strong> you&#39;ll always find your name, the <strong>EN/ID</strong> language toggle, a <strong>Dark mode</strong>\nswitch, and <strong>Sign out</strong>.</p>\n<p><img src=\"/docs/images/admin-overview.png\" alt=\"The Platform Overview with the full admin sidebar on the left.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"3-the-platform-overview\">3. The Platform Overview</h2>\n<p><strong>Menu → Overview</strong> (<code>/admin</code>). This is your one-glance health check for the whole platform. The\ntiles across the top show:</p>\n<ul>\n<li><strong>Tenants</strong> (total) and <strong>new in 30 days</strong></li>\n<li><strong>Active / Suspended</strong> split</li>\n<li><strong>Outlets</strong> and <strong>Users</strong> across all businesses</li>\n<li><strong>Customers</strong>, <strong>Orders today</strong>, <strong>Revenue today</strong>, <strong>Revenue 30d (GMV)</strong></li>\n<li><strong>Active memberships</strong>, <strong>Estimated MRR</strong> (your recurring subscription revenue — see §8),\n<strong>AI calls (30d)</strong>, <strong>New tenants (30d)</strong></li>\n</ul>\n<p>Below the tiles are two charts (<strong>platform revenue per day</strong> and <strong>new tenants per day</strong>), a\n<strong>Recent platform activity</strong> feed (config changes, suspensions, etc.), and <strong>Quick links</strong> into the\ndeeper pages.</p>\n<blockquote>\n<p>If any tile shows a soft &quot;requires Platform Super Admin&quot; message, your account isn&#39;t a super-admin\n— sign in with a super-admin account.</p>\n</blockquote>\n<hr>\n<h2 id=\"4-create-a-new-business-tenant\">4. Create a new business (tenant)</h2>\n<p>This is the most common thing you&#39;ll do. Creating a tenant provisions the whole business and gives\nit a permanent <strong>6-character tenant code</strong> (the prefix of every membership number that business will\never issue — it never changes).</p>\n<p><strong>Step by step:</strong></p>\n<ol>\n<li><p>In the sidebar click <strong>Tenants</strong>. You&#39;ll see the list of every business, with search, a status\nfilter, and per-row <strong>Edit</strong> / <strong>Suspend</strong> actions.</p>\n<p><img src=\"/docs/images/admin-tenants.png\" alt=\"The Tenants list: every business with status, plan, outlets, users, 30-day orders and revenue.\" loading=\"lazy\" /></p>\n</li>\n<li><p>Click <strong>+ Create Tenant</strong> (top-right).</p>\n</li>\n<li><p>Fill in the business name (and any other fields the form asks for), and <strong>choose its subscription\nplan</strong> (see §7 to define plans first). Status defaults to <strong>Active</strong>.</p>\n</li>\n<li><p>Save. The business now exists and has its tenant code.</p>\n</li>\n<li><p>Hand the owner their <strong>first-login credentials</strong> so they can sign in to the <strong>Dashboard</strong> and set\nup branding, branches and staff. (What they do next is the\n<a href=\"/docs/tenant-owner-manual\">Tenant Owner manual</a>.)</p>\n</li>\n</ol>\n<blockquote>\n<p><strong>The Create Tenant wizard has four steps:</strong> <strong>Account + owner login</strong> (business name, slug, and the\nowner&#39;s name/email/password) → <strong>Modules</strong> (which features the business starts with) → <strong>Legal\nentity</strong> (optional PT) → <strong>Branch</strong> (their first outlet). At the end the business exists, has its\ntenant code, and the owner can sign in immediately.</p>\n</blockquote>\n<blockquote>\n<p><strong>Businesses can also self-register.</strong> If you send someone to <code>/register</code>, they create their own\ntenant + owner login and get a tenant code automatically — you don&#39;t have to create it by hand.\nYou&#39;ll still see them appear in the Tenants list.</p>\n</blockquote>\n<p><img src=\"/docs/images/reg-01-register.png\" alt=\"Self-registration — a prospective owner creates their own business and login at `/register`.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"5-open-and-manage-one-business\">5. Open and manage one business</h2>\n<p>A tenant&#39;s actions live on <strong>two pages</strong> — the <strong>list</strong> (<code>/admin/tenants</code>) and the <strong>detail page</strong>\n(click the business name to open <code>/admin/tenants/[slug]</code>).</p>\n<p><strong>On the Tenants list</strong> (per-row or in the create wizard):</p>\n<ul>\n<li><strong>+ Create Tenant</strong> — the 4-step wizard (see §4).</li>\n<li><strong>Edit</strong> — change the business <strong>name, slug, or subscription plan</strong>.</li>\n<li><strong>Suspend</strong> (when active) / <strong>Reactivate</strong> (when suspended).</li>\n</ul>\n<p><strong>On the tenant detail page</strong> you see its <strong>stats</strong> (orders 30d, revenue 30d, active members,\ncustomers), its <strong>branches</strong> and <strong>users</strong>, and can:</p>\n<ul>\n<li><strong>🔑 Reset owner password</strong> — set a new password and get the owner&#39;s email to hand back to them.</li>\n<li><strong>👤 Impersonate</strong> the owner to troubleshoot (see §11).</li>\n<li><strong>+ Add branch</strong> for the tenant (useful during onboarding).</li>\n<li><strong>Toggle feature modules</strong> on/off (see §6).</li>\n<li><strong>Support notes</strong> — internal notes about this business (pin the important ones). <strong>These are never\nshown to the tenant</strong> — they&#39;re your private support memory.</li>\n</ul>\n<p><strong>Suspend vs. delete:</strong> always prefer <strong>Suspend</strong>. Suspending blocks the business but keeps all its\nhistory, and you can <strong>Reactivate</strong> it later in one click. All of these actions — suspend, reactivate,\nimpersonate, password reset, module changes — are recorded in the <strong>audit log</strong> (who did it, and the\nbefore/after state).</p>\n<p><img src=\"/docs/images/admin-tenant-detail.png\" alt=\"Drilling into one tenant — stats, branches, users, modules, password reset and support notes.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"6-turn-features-on-and-off-modules\">6. Turn features on and off (modules)</h2>\n<p>Each business has a set of <strong>feature modules</strong> you can switch on or off. <strong>Everything is ON by\ndefault</strong> — you only turn a module <strong>off</strong> to hide it from that business&#39;s dashboard.</p>\n<p><strong>Core areas can never be turned off:</strong> Hub, Overview, Users &amp; Roles, Payment Gateway, and Settings\nare always available.</p>\n<p><strong>Toggleable modules:</strong>\nAnalytics &amp; Reports · Customers &amp; Bookings (CRM) · Memberships · Vouchers · Promotions ·\nCatalog &amp; Outlets · Inventory &amp; Procurement · Finance &amp; Settlement · HR &amp; Payroll ·\nAI Assistant · WhatsApp AI Agent.</p>\n<p><strong>How to change them:</strong></p>\n<ol>\n<li>Open the tenant&#39;s <strong>detail page</strong> (§5).</li>\n<li>Find the <strong>modules</strong> section and flip the toggles.</li>\n<li>The change is <strong>audited</strong> (before → after) and takes effect the <strong>next time</strong> the owner loads\ntheir dashboard.</li>\n</ol>\n<blockquote>\n<p><strong>Rule of thumb:</strong> the set of modules a business can see should match <strong>what they&#39;re paying for</strong>.\nCheck this right after onboarding.</p>\n</blockquote>\n<hr>\n<h2 id=\"7-subscription-plans--pricing\">7. Subscription plans &amp; pricing</h2>\n<p><strong>Menu → Subscription Plans</strong> (<code>/admin/plans</code>). These are the plans <strong>the platform charges the\nbusinesses</strong> — your product&#39;s pricing tiers.</p>\n<p><img src=\"/docs/images/admin-plans.png\" alt=\"Subscription Plans — the pricing tiers the platform sells to businesses.\" loading=\"lazy\" /></p>\n<p>Each plan has:</p>\n<ul>\n<li>a <strong>code</strong> and <strong>name</strong></li>\n<li>a <strong>price</strong> and <strong>billing cycle</strong> (monthly or annual)</li>\n<li>the <strong>features</strong> it includes</li>\n<li><strong>limits</strong> (e.g. number of outlets or users)</li>\n</ul>\n<p><strong>To put a business on a plan:</strong> go to <strong>Tenants → Edit</strong> and pick the plan there.</p>\n<p><strong>Deactivating</strong> a plan stops it being offered to new tenants but leaves businesses already on it\nuntouched.</p>\n<blockquote>\n<p><strong>Important — what a plan actually enforces today.</strong> A plan&#39;s <strong>price</strong> drives the MRR/billing\nestimate, and its <strong>features / limits</strong> are shown on the plan card as a description of the tier — but\nthe system does <strong>not</strong> auto-block a tenant for exceeding a plan limit. The one control that is truly\nenforced is the per-tenant <strong>Modules</strong> toggle set (§6): that&#39;s what hides features from a business.\nSo when you put a business on a plan, also <strong>set its Modules to match</strong> — the plan is the promise,\nthe modules are the switch.</p>\n</blockquote>\n<blockquote>\n<p>⚠️ <strong>Don&#39;t confuse two kinds of &quot;plan&quot;.</strong></p>\n<ul>\n<li><strong>Subscription plans</strong> (here, <code>/admin/plans</code>) = what the <em>platform</em> charges <em>businesses</em>.</li>\n<li><strong>Membership plans</strong> (<code>/dashboard/memberships</code>, owner-side) = what a <em>business</em> sells to <em>its\ncustomers</em>. You never touch those.</li>\n</ul>\n</blockquote>\n<p><strong>Menu → Config</strong> (<code>/admin/config</code>) holds platform-wide <strong>default plans</strong> and <strong>feature flags</strong>.</p>\n<hr>\n<h2 id=\"8-billing--invoices\">8. Billing &amp; invoices</h2>\n<p><strong>Menu → Billing</strong> (<code>/admin/billing</code>). Two tabs.</p>\n<p><strong>Overview tab</strong> — your recurring revenue:</p>\n<ul>\n<li><strong>Estimated MRR</strong> = (plan price) × (number of active businesses on that plan). Annual plans are\ndivided by 12 so everything is expressed as a monthly figure. The same MRR number appears on the\nOverview, and an <strong>Annual run rate</strong> tile shows MRR × 12.</li>\n<li>A <strong>By plan</strong> table breaks it down: price, tenants, active count, and MRR per plan.</li>\n<li>MRR is an <strong>estimate</strong> computed from plan price × active tenants — it&#39;s a planning figure, not a\nbilled amount.</li>\n</ul>\n<p><img src=\"/docs/images/admin-billing.png\" alt=\"Billing — MRR rolled up by subscription plan.\" loading=\"lazy\" /></p>\n<p><strong>Invoices tab</strong> — the actual per-tenant invoices:</p>\n<ul>\n<li>Tiles for <strong>Outstanding / Overdue / Paid this month</strong>.</li>\n<li>Enter a <strong>period</strong> (<code>YYYY-MM</code>) and click <strong>Generate drafts</strong> to raise an invoice per active tenant.</li>\n<li>Filter by status and, per row, move an invoice along its lifecycle: <strong>Send</strong> a draft → <strong>Mark paid</strong>\nor flag <strong>Overdue</strong> → <strong>Void</strong> if needed. These are real, persisted invoices.</li>\n</ul>\n<hr>\n<h2 id=\"9-monitoring--system-health\">9. Monitoring &amp; system health</h2>\n<ul>\n<li><p><strong>Menu → Monitoring</strong> (<code>/admin/monitoring</code>) — operational metrics (orders, revenue, customers)\nacross all businesses. You can view <strong>globally</strong> or pick a single tenant.</p>\n<p><img src=\"/docs/images/admin-monitoring.png\" alt=\"Operational monitoring across tenants.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Menu → System Health</strong> (<code>/admin/health</code>) — the technical heartbeat: database latency, whether the\nWhatsApp gateway (WAHA) is reachable, entity counts, and — when the server exposes it — a <strong>live\nlist of running containers</strong> with their state/health and a <strong>per-container log viewer</strong>.</p>\n<p><img src=\"/docs/images/admin-health.png\" alt=\"System Health — database, WhatsApp gateway, and container status.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Menu → Analytics</strong> (<code>/admin/analytics</code>) — platform-wide growth and usage charts.</p>\n<p><img src=\"/docs/images/admin-analytics.png\" alt=\"Platform analytics.\" loading=\"lazy\" /></p>\n</li>\n</ul>\n<hr>\n<h2 id=\"10-ai-usage--the-ai-flow-catalog\">10. AI usage &amp; the AI flow catalog</h2>\n<ul>\n<li><p><strong>Menu → AI Usage</strong> (<code>/admin/ai-usage</code>) — how much AI is being used: number of calls, errors,\ntokens, and the top tools, globally or per tenant.</p>\n<p><img src=\"/docs/images/admin-ai-usage.png\" alt=\"AI usage — calls, errors, tokens and top tools.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Menu → Agent Flows</strong> (<code>/admin/agent-flows</code>) — the <strong>catalog of AI flows</strong> you publish for\nbusinesses to use. You design drag-and-drop flows in the hosted <strong>n8n</strong> builder, then <strong>publish</strong>\neach one here (it gets a webhook URL and a kind — WhatsApp or automation). Businesses then simply\n<strong>select</strong> a published flow for their WhatsApp agent — they never get an n8n login. The technical\nnote is <a href=\"/docs/tech-n8n-agent-builder\">n8n-agent-builder.md</a>.</p>\n<p><img src=\"/docs/images/admin-agent-flows.png\" alt=\"The published AI flow catalog.\" loading=\"lazy\" /></p>\n</li>\n</ul>\n<hr>\n<h2 id=\"11-support--impersonation\">11. Support &amp; impersonation</h2>\n<p><strong>Menu → Support</strong> (<code>/admin/support</code>). Search for a business, see a <strong>&quot;needs attention&quot;</strong> list, and\nreactivate suspended ones quickly.</p>\n<p><img src=\"/docs/images/admin-support.png\" alt=\"Support — find a business and help it.\" loading=\"lazy\" /></p>\n<p><strong>Impersonation</strong> (from a tenant&#39;s detail page, §5) logs you into the owner&#39;s Dashboard <strong>as that\nowner</strong> so you can reproduce exactly what they see.</p>\n<ul>\n<li>Use it for <strong>support only</strong>, not routine work.</li>\n<li><strong>Every impersonation is logged</strong> (it&#39;s in the audit trail).</li>\n<li>When you&#39;re done, click <strong>Stop impersonation</strong> to return to your own admin session.</li>\n</ul>\n<p>The <strong>audit log</strong> (<code>/admin/audit</code>, and each business has its own) records these sensitive actions.</p>\n<p><img src=\"/docs/images/admin-audit.png\" alt=\"The audit log of sensitive platform actions.\" loading=\"lazy\" /></p>\n<h3 id=\"111-view-as--preview-any-tenants-world-from-the-hub\">11.1 &quot;View as&quot; — preview any tenant&#39;s world from the Hub</h3>\n<p>Beyond raw impersonation, the <strong>Hub</strong> gives super-admins a quick way to <em>preview</em> a business exactly as\nits own people see it. At the top of the Hub is a <strong>&quot;Viewing tenant&quot;</strong> picker — choose the business you\nwant to inspect, then use the preview tiles:</p>\n<ul>\n<li><strong>Owner Dashboard</strong> — opens <code>/dashboard</code> as that business&#39;s owner.</li>\n<li><strong>Employee View</strong> — pick one of the tenant&#39;s staff (or <em>&quot;pick one for me&quot;</em>) and open their\nself-service <code>/employee</code> view.</li>\n<li><strong>Customer / Member Portal</strong> — pick a customer and open their member <code>/portal</code>.</li>\n</ul>\n<p>While previewing, a floating amber banner — <strong>&quot;👁️ Viewing as … · {business}&quot;</strong> — follows you\neverywhere, with an <strong>Exit preview</strong> button to drop straight back to your own admin session. Like\nimpersonation, every &quot;view as&quot; is <strong>role-gated to super-admins and audited</strong>.</p>\n<blockquote>\n<p><strong>Impersonate vs. View as.</strong> <em>Impersonate</em> (from a tenant detail page) is the deep, full-session\nroute for reproducing a bug. <em>View as</em> (from the Hub) is the fast, switch-between route for checking\nwhat owners / staff / customers of a given tenant actually see — handy for QA and support triage.</p>\n</blockquote>\n<hr>\n<h2 id=\"12-announcements-config--platform-users\">12. Announcements, Config &amp; Platform Users</h2>\n<h3 id=\"121-announcements--notices-to-tenants\">12.1 Announcements — notices to tenants</h3>\n<p><strong>Menu → Announcements</strong> (<code>/admin/announcements</code>). Broadcast a notice to businesses — a maintenance\nwindow, a new feature, a policy change.</p>\n<p><img src=\"/docs/images/admin-announcements.png\" alt=\"Announcements — targeted notices to tenants.\" loading=\"lazy\" /></p>\n<ol>\n<li>Click <strong>+ New announcement</strong>.</li>\n<li>Enter a <strong>title</strong> and <strong>body</strong>, pick a <strong>severity</strong> (Info / Warning / Critical), and choose the\n<strong>audience</strong>: <strong>All tenants</strong>, <strong>By plan</strong> (a plan cohort), or <strong>One tenant</strong>.</li>\n<li>Save as a draft, then <strong>Publish</strong> when you&#39;re ready (you can <strong>Unpublish</strong>, <strong>Edit</strong> or <strong>Delete</strong>\nlater). Only <strong>published</strong> announcements are visible to tenants.</li>\n</ol>\n<h3 id=\"122-platform-config--global-defaults--feature-flags\">12.2 Platform Config — global defaults &amp; feature flags</h3>\n<p><strong>Menu → Platform Config</strong> (<code>/admin/config</code>). Platform-wide settings that apply across <em>all</em> tenants:</p>\n<p><img src=\"/docs/images/admin-config.png\" alt=\"Platform Config — default plans and feature flags.\" loading=\"lazy\" /></p>\n<ul>\n<li><strong>Default plans</strong> — the comma-separated list of plans offered to new tenants.</li>\n<li><strong>Subscription plans</strong> — a shortcut to manage pricing on the <strong>Subscription Plans</strong> page (§7).</li>\n<li><strong>Feature flags</strong> — global on/off switches (each a key you can toggle, add, or remove). New flags\nstart <strong>disabled</strong>.</li>\n</ul>\n<p>Click <strong>Save changes</strong> to apply.</p>\n<h3 id=\"123-platform-users--other-admins\">12.3 Platform Users — other admins</h3>\n<p><strong>Menu → Platform Users</strong> (<code>/admin/users</code>). The other people who can sign in to Platform Admin. Add or\nmanage fellow platform operators here. Keep this list tight — everyone here can see and act across\n<strong>every</strong> business.</p>\n<p><img src=\"/docs/images/admin-users.png\" alt=\"Platform Users — the other admin accounts.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"13-everyday-checklists\">13. Everyday checklists</h2>\n<p><strong>Onboard a new business</strong></p>\n<ol>\n<li><strong>Tenants → + Create Tenant</strong> (or point them at <code>/register</code>).</li>\n<li>Assign the correct <strong>subscription plan</strong>.</li>\n<li>Open the tenant detail and confirm its <strong>modules</strong> match what they paid for.</li>\n<li>Give the owner their <strong>first-login credentials</strong> and the\n<a href=\"/docs/tenant-owner-manual\">Tenant Owner manual</a>.</li>\n</ol>\n<p><strong>A business reports a problem</strong></p>\n<ol>\n<li><strong>Support</strong> → search for them.</li>\n<li>Open the tenant detail → <strong>Impersonate the owner</strong> and reproduce the issue.</li>\n<li><strong>Stop impersonation</strong> when done.</li>\n<li>If needed, check <strong>System Health</strong> and <strong>Monitoring</strong>.</li>\n</ol>\n<p><strong>Weekly platform review</strong></p>\n<ol>\n<li><strong>Overview</strong> — glance at active/suspended, new tenants, MRR.</li>\n<li><strong>Billing</strong> — confirm MRR looks right.</li>\n<li><strong>System Health</strong> — database + WhatsApp gateway green.</li>\n<li><strong>AI Usage</strong> — watch error rates.</li>\n</ol>\n<blockquote>\n<p><strong>Golden rules:</strong> prefer <strong>suspend</strong> over delete (reversible, keeps history); use <strong>impersonation</strong>\nsparingly and remember it&#39;s logged; keep each business&#39;s <strong>modules</strong> aligned with its plan.</p>\n</blockquote>\n"},{"slug":"tenant-owner-manual","title":"Tenant Owner / Manager — User Manual","category":"manual","audience":"Tenant Owner / Manager","blurb":"Configure and run one business end to end — the biggest manual.","order":1,"words":5726,"minutes":29,"toc":[{"id":"table-of-contents","text":"Table of contents","level":2},{"id":"1-sign-in--the-hub","text":"1. Sign in & the Hub","level":2},{"id":"2-find-your-way-around-the-dashboard","text":"2. Find your way around the Dashboard","level":2},{"id":"3-first-time-setup-the-guided-wizard","text":"3. First-time setup (the guided wizard)","level":2},{"id":"4-setup-in-detail--do-these-in-order","text":"4. Setup in detail — do these in order","level":2},{"id":"41-branding-settings--branding","text":"4.1 Branding (Settings → Branding)","level":3},{"id":"42-branches--your-outlets","text":"4.2 Branches — your outlets","level":3},{"id":"43-catalog--categories--brands","text":"4.3 Catalog — categories & brands","level":3},{"id":"44-services--your-sellable-menu","text":"4.4 Services — your sellable menu","level":3},{"id":"45-products-retail-items","text":"4.5 Products (retail items)","level":3},{"id":"46-payment-methods-the-pos-buttons","text":"4.6 Payment methods (the POS buttons)","level":3},{"id":"47-payment-gateway-online-payments","text":"4.7 Payment gateway (online payments)","level":3},{"id":"48-users--roles-staff-logins","text":"4.8 Users & roles (staff logins)","level":3},{"id":"49-vehicle-catalog","text":"4.9 Vehicle catalog","level":3},{"id":"410-legal-entities-optional","text":"4.10 Legal entities (optional)","level":3},{"id":"5-customers-memberships--bookings","text":"5. Customers, memberships & bookings","level":2},{"id":"51-customers--crm","text":"5.1 Customers & CRM","level":3},{"id":"52-memberships","text":"5.2 Memberships","level":3},{"id":"53-bookings","text":"5.3 Bookings","level":3},{"id":"54-whatsapp-broadcast-wa-broadcast","text":"5.4 WhatsApp broadcast (WA Broadcast)","level":3},{"id":"6-vouchers--promotions","text":"6. Vouchers & promotions","level":2},{"id":"61-vouchers","text":"6.1 Vouchers","level":3},{"id":"62-promotions","text":"6.2 Promotions","level":3},{"id":"7-inventory-recipes-cogs--finance","text":"7. Inventory, recipes, COGS & finance","level":2},{"id":"71-inventory","text":"7.1 Inventory","level":3},{"id":"72-recipes-attached-to-services","text":"7.2 Recipes (attached to services)","level":3},{"id":"73-procurement","text":"7.3 Procurement","level":3},{"id":"74-stock-opname-physical-count","text":"7.4 Stock opname (physical count)","level":3},{"id":"75-cogs--pl","text":"7.5 COGS & P&L","level":3},{"id":"76-finance","text":"7.6 Finance","level":3},{"id":"77-settlement-cross-branch","text":"7.7 Settlement (cross-branch)","level":3},{"id":"78-accounting","text":"7.8 Accounting","level":3},{"id":"79-tax-invoices--faktur-pajak--e-faktur","text":"7.9 Tax invoices — Faktur Pajak / e-Faktur","level":3},{"id":"8-reporting","text":"8. Reporting","level":2},{"id":"9-people--hr--payroll","text":"9. People — HR & payroll","level":2},{"id":"10-ai-assistant--whatsapp","text":"10. AI assistant & WhatsApp","level":2},{"id":"101-ai-assistant-your-co-pilot","text":"10.1 AI Assistant (your co-pilot)","level":3},{"id":"102-agentic-ai--whatsapp-the-customer-facing-agent","text":"10.2 Agentic AI / WhatsApp (the customer-facing agent)","level":3},{"id":"103-agent-workflow-personas--routing","text":"10.3 Agent Workflow (personas & routing)","level":3},{"id":"104-conversations","text":"10.4 Conversations","level":3},{"id":"105-monitoring","text":"10.5 Monitoring","level":3},{"id":"11-settings--configuration","text":"11. Settings & configuration","level":2},{"id":"111-barcodes-settings--barcodes","text":"11.1 Barcodes (Settings → Barcodes)","level":3},{"id":"112-feedback-setup-feedback--nps--setup","text":"11.2 Feedback setup (Feedback & NPS → Setup)","level":3},{"id":"113-audit-log-settings--audit-log","text":"11.3 Audit log (Settings → Audit log)","level":3},{"id":"12-tips--troubleshooting","text":"12. Tips & troubleshooting","level":2},{"id":"13-glossary","text":"13. Glossary","level":2}],"html":"<h1 id=\"tenant-owner--manager--user-manual\">Tenant Owner / Manager — User Manual</h1>\n<p><strong>Who this is for:</strong> you <strong>own or manage one business</strong> on airin. You control <strong>everything inside\nyour business</strong> — all your outlets (branches), staff, service menu, prices, memberships, vouchers,\npromotions, stock, finance, HR, and the AI assistant.</p>\n<p>Your workspace is the <strong>Dashboard</strong> (<code>/dashboard</code>). This manual walks you through it, in the order\nyou&#39;ll actually use it — <strong>set-up first, then day-to-day, then reporting</strong>.</p>\n<blockquote>\n<p><strong>What you&#39;ll see may differ slightly.</strong> Your sidebar only shows the <strong>modules</strong> the platform has\nswitched on for your business (the default is <em>everything on</em>). If something described here isn&#39;t\nin your sidebar, that module is off — ask your platform administrator to enable it.</p>\n</blockquote>\n<blockquote>\n<p><strong>You won&#39;t use <code>/admin</code>.</strong> That &quot;Platform Admin&quot; area belongs to the platform operator, not to\nbusinesses. You run everything from the <strong>Dashboard</strong>.</p>\n</blockquote>\n<hr>\n<h2 id=\"table-of-contents\">Table of contents</h2>\n<ol>\n<li><a href=\"#1-sign-in--the-hub\">Sign in &amp; the Hub</a></li>\n<li><a href=\"#2-find-your-way-around-the-dashboard\">Find your way around the Dashboard</a></li>\n<li><a href=\"#3-first-time-setup-the-guided-wizard\">First-time setup (the guided wizard)</a></li>\n<li><a href=\"#4-setup-in-detail--do-these-in-order\">Setup in detail — do these in order</a></li>\n<li><a href=\"#5-customers-memberships--bookings\">Customers, memberships, bookings &amp; broadcast</a></li>\n<li><a href=\"#6-vouchers--promotions\">Vouchers &amp; promotions</a></li>\n<li><a href=\"#7-inventory-recipes-cogs--finance\">Inventory, recipes, COGS, finance &amp; tax</a></li>\n<li><a href=\"#8-reporting\">Reporting</a></li>\n<li><a href=\"#9-people--hr--payroll\">People — HR, payroll &amp; commission</a></li>\n<li><a href=\"#10-ai-assistant--whatsapp\">AI assistant &amp; WhatsApp</a></li>\n<li><a href=\"#11-settings--configuration\">Settings &amp; configuration</a></li>\n<li><a href=\"#12-tips--troubleshooting\">Tips &amp; troubleshooting</a></li>\n<li><a href=\"#13-glossary\">Glossary</a></li>\n</ol>\n<hr>\n<h2 id=\"1-sign-in--the-hub\">1. Sign in &amp; the Hub</h2>\n<ol>\n<li>Open your business&#39;s app URL.</li>\n<li>Enter your email and password and click <strong>Sign in</strong> (or click the <strong>Tenant Owner</strong> demo card on a\ndemo system).</li>\n<li>You arrive at the <strong>Hub</strong> — a launcher with tiles for <strong>Dashboard</strong>, <strong>Point of Sale</strong>, and\n<strong>Self-Service Kiosk</strong>. Click <strong>Dashboard</strong>.</li>\n</ol>\n<p><img src=\"/docs/images/pos-00-hub.png\" alt=\"The Hub launcher — choose Dashboard, Point of Sale, or Self-Service Kiosk.\" loading=\"lazy\" /></p>\n<blockquote>\n<p><strong>Language:</strong> the <strong>EN / ID</strong> toggle (bottom-left of the Dashboard, and on every screen) switches\nEnglish ↔ Indonesian at any time.</p>\n</blockquote>\n<hr>\n<h2 id=\"2-find-your-way-around-the-dashboard\">2. Find your way around the Dashboard</h2>\n<p>The Dashboard has a <strong>left sidebar</strong> grouped into sections. You scroll it to reach everything. The\nmain groups are:</p>\n<table>\n<thead>\n<tr>\n<th>Group</th>\n<th>What lives there</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><em>(top)</em></td>\n<td><strong>Hub</strong>, <strong>Overview</strong></td>\n</tr>\n<tr>\n<td><strong>ANALYTICS</strong></td>\n<td>Transactions, Refunds, Invoices, Tax Invoices (e-Faktur), Reports, Sales &amp; Leads, Shifts &amp; Cash</td>\n</tr>\n<tr>\n<td><strong>CUSTOMERS</strong></td>\n<td>Customers &amp; CRM, Bookings, Memberships, Vouchers, Feedback &amp; NPS, WA Broadcast</td>\n</tr>\n<tr>\n<td><strong>CATALOG / OPERATIONS</strong></td>\n<td>Services, Catalog, Products, Inventory, Procurement, Stock Opname, COGS, Promotions</td>\n</tr>\n<tr>\n<td><strong>FINANCE</strong></td>\n<td>Finance, Settlement, Accounting, Commission</td>\n</tr>\n<tr>\n<td><strong>PEOPLE</strong></td>\n<td>Users &amp; Roles, HR, Payroll</td>\n</tr>\n<tr>\n<td><strong>AI</strong></td>\n<td>AI Assistant, Agent Workflow, Agentic AI / WhatsApp, Conversations, Monitoring</td>\n</tr>\n<tr>\n<td><strong>SETTINGS</strong></td>\n<td>Settings, Branches, Payment Methods, Payment Gateway, Barcodes, Designers, Devices, Audit log</td>\n</tr>\n</tbody></table>\n<blockquote>\n<p><strong>Only what you&#39;re paying for shows.</strong> The sidebar hides any <strong>module</strong> the platform switched off\nfor your business, so your list may be shorter than the table above. A few areas — Hub, Overview,\nUsers &amp; Roles, Payment Gateway and Settings — can <strong>never</strong> be switched off. If a whole section is\nmissing and you expected it, that&#39;s a platform setting, not a bug: ask your platform administrator.</p>\n</blockquote>\n<p>At the <strong>bottom-left</strong>: your name &amp; role, the <strong>EN/ID</strong> toggle, and <strong>Sign out</strong>. The <strong>Overview</strong>\npage is your home base:</p>\n<p><img src=\"/docs/images/owner-overview.png\" alt=\"Dashboard Overview — headline tiles (Outlets, Members served, Orders, Revenue), AI proposals, and quick links. Use the branch selector (top-right) to focus on one outlet.\" loading=\"lazy\" /></p>\n<ul>\n<li>The <strong>branch selector</strong> (top-right on most pages) lets you view <strong>all branches</strong> together or focus\non <strong>one outlet</strong>.</li>\n<li><strong>AI Action Proposals</strong> surfaces recommendations from the AI agent (if you&#39;ve enabled AI).</li>\n</ul>\n<hr>\n<h2 id=\"3-first-time-setup-the-guided-wizard\">3. First-time setup (the guided wizard)</h2>\n<p>The fastest way to get a brand-new business ready is the <strong>onboarding wizard</strong>. New owners are\nguided into it automatically the first time they sign in; you can also open it any time from\n<strong><code>/dashboard/onboarding</code></strong>. A progress bar across the top tracks the six steps and lets you jump\nback to any step you&#39;ve already passed.</p>\n<p><img src=\"/docs/images/onb-00-open.png\" alt=\"The onboarding welcome — the wizard opens here on a brand-new business.\" loading=\"lazy\" /></p>\n<p><strong>Company → Branch → Services → Staff → Finance → Done.</strong> Take them in order the first time; each\nstep&#39;s <strong>Save &amp; continue</strong> unlocks the next, and <strong>Back</strong> returns to a finished step to edit it.</p>\n<p><strong>Step 1 · Company.</strong> Your business name and identity — this seeds your branding and the read-only\n<strong>tenant code</strong> that prefixes every membership number you&#39;ll ever issue.</p>\n<p><strong>Step 2 · Branch.</strong> Your first outlet: branch <strong>name</strong>, a <strong>3-letter branch code</strong> (used on receipts\nand membership numbers — choose it carefully, it&#39;s awkward to change later), an optional <strong>legal\nentity</strong> (PT), <strong>address</strong>, a <strong>WhatsApp phone number</strong>, and your default <strong>service charge %</strong> and\n<strong>tax / PPN %</strong>.</p>\n<p><img src=\"/docs/images/onb-01.png\" alt=\"Onboarding — the Branch step, with code, address, WhatsApp number and default charges.\" loading=\"lazy\" /></p>\n<p><strong>Step 3 · Services.</strong> Add your first few sellable services so the POS and eMenu aren&#39;t empty — each\ngets a business unit (<strong>AIRE</strong> wash / <strong>LEAD</strong> detail), a category and a price. You can add the rest\nlater on the full Services page (§4.4).</p>\n<p><img src=\"/docs/images/onb-02.png\" alt=\"Onboarding — the Services step.\" loading=\"lazy\" /></p>\n<p><strong>Step 4 · Staff.</strong> Create logins for the people who&#39;ll run the counter — pick a role (Outlet Admin or\nCashier) and the branch they work at. You can add and re-assign staff any time afterwards (§4.8).</p>\n<p><img src=\"/docs/images/onb-03.png\" alt=\"Onboarding — the Staff step.\" loading=\"lazy\" /></p>\n<p><strong>Step 5 · Finance.</strong> Turn on the finance defaults — chart of accounts, PPN tax, and payroll scaffolding\n— in one step so your reports and accounting work from day one. (This is the same <strong>Finance setup</strong>\nyou can re-run later; see §11.)</p>\n<p><img src=\"/docs/images/onb-04.png\" alt=\"Onboarding — the Finance step.\" loading=\"lazy\" /></p>\n<p><strong>Step 6 · Done.</strong> A summary of what&#39;s set up and the recommended next actions.</p>\n<p><img src=\"/docs/images/onb-05.png\" alt=\"Onboarding — the Done / summary step.\" loading=\"lazy\" /></p>\n<p><img src=\"/docs/images/onb-06.png\" alt=\"Onboarding — the completed wizard, ready to start trading.\" loading=\"lazy\" /></p>\n<blockquote>\n<p><strong>The wizard is optional and nothing it sets is locked.</strong> You can skip it entirely and configure each\narea from its own page below — the wizard just does the essentials in a sensible order. Everything you\nenter here can be changed later from the matching Settings/Dashboard page.</p>\n</blockquote>\n<hr>\n<h2 id=\"4-setup-in-detail--do-these-in-order\">4. Setup in detail — do these in order</h2>\n<p>Even if you used the wizard, here&#39;s every setup area and what it does. <strong>Do them top to bottom</strong> the\nfirst time.</p>\n<h3 id=\"41-branding-settings--branding\">4.1 Branding (Settings → Branding)</h3>\n<p>Set your company name, logo, colours, fonts and dark-mode policy. This themes your <strong>whole app</strong> and\nyour <strong>public pages</strong> (eMenu, kiosk, member portal). Your read-only <strong>tenant code</strong> is shown here.\n(Full Settings walkthrough in §11.)</p>\n<h3 id=\"42-branches--your-outlets\">4.2 Branches — your outlets</h3>\n<p><strong>Sidebar → Branches</strong> (<code>/dashboard/branches</code>). Add each physical outlet.</p>\n<ol>\n<li>Click <strong>+ Add Branch</strong>.</li>\n<li>Enter the <strong>name</strong>, a <strong>3-letter code</strong>, the <strong>legal entity</strong> (if you use them), <strong>address</strong>,\n<strong>maps link</strong>, and <strong>phone</strong>.</li>\n<li>Save.</li>\n</ol>\n<blockquote>\n<p>⚠️ <strong>The branch phone matters.</strong> Portal bookings send their confirmation link to the <strong>branch\nphone over WhatsApp</strong>, and membership expiry/notification messages use it too. Set a real,\nWhatsApp-capable number.</p>\n</blockquote>\n<blockquote>\n<p><strong>Branch phone vs. per-branch AI line — two different things.</strong> The phone here is a <strong>contact\nnumber</strong> for notifications. If you want each outlet to run the <strong>WhatsApp AI agent on its own\nnumber</strong> (so customers of the Bintaro branch chat a different line than the Serpong branch), that&#39;s\na separate switch on the <strong>Agentic AI</strong> page — see §10.2. Leaving it off means every branch shares\none business-wide WhatsApp line.</p>\n</blockquote>\n<p><img src=\"/docs/images/owner-branches.png\" alt=\"Branches — one row per outlet.\" loading=\"lazy\" /></p>\n<h3 id=\"43-catalog--categories--brands\">4.3 Catalog — categories &amp; brands</h3>\n<p><strong>Sidebar → Catalog</strong> (<code>/dashboard/catalog</code>). Create the <strong>product categories</strong> and <strong>brands</strong> you&#39;ll\ntag services and products with.</p>\n<p><img src=\"/docs/images/owner-catalog.png\" alt=\"Catalog — categories and brands.\" loading=\"lazy\" /></p>\n<h3 id=\"44-services--your-sellable-menu\">4.4 Services — your sellable menu</h3>\n<p><strong>Sidebar → Services</strong> (<code>/dashboard/services</code>). This is what appears on the POS and public eMenu.</p>\n<ol>\n<li>Click <strong>+ Add Service</strong>.</li>\n<li>Give it a <strong>business unit</strong> — <strong>AIRE</strong> (car wash) or <strong>LEAD</strong> (detailing) — a <strong>category</strong>, and a\n<strong>price</strong>. Optionally scope it to specific branches.</li>\n<li>Optionally attach a <strong>Recipe</strong> (the <strong>Recipe</strong> action on each row) — see §7.</li>\n<li><strong>Active</strong> services show on the POS; inactive ones are hidden.</li>\n</ol>\n<p><img src=\"/docs/images/owner-services.png\" alt=\"Services — the sellable menu. Each row has a Recipe, Edit and Delete action; UNIT is AIRE or LEAD.\" loading=\"lazy\" /></p>\n<h3 id=\"45-products-retail-items\">4.5 Products (retail items)</h3>\n<p><strong>Sidebar → Products</strong> (<code>/dashboard/products</code>). Physical goods you resell (e.g. air fresheners).\nAdd name, category, price, and stock behaviour.</p>\n<p><img src=\"/docs/images/owner-products.png\" alt=\"Products — retail goods.\" loading=\"lazy\" /></p>\n<h3 id=\"46-payment-methods-the-pos-buttons\">4.6 Payment methods (the POS buttons)</h3>\n<p><strong>Sidebar → Payment Methods</strong> (<code>/dashboard/payment-methods</code>). Define the payment buttons cashiers see\nper branch — cash, QRIS, EDC, card, transfer — each with a colour/logo.</p>\n<p><img src=\"/docs/images/owner-payment-methods.png\" alt=\"Payment methods — the buttons shown at checkout.\" loading=\"lazy\" /></p>\n<h3 id=\"47-payment-gateway-online-payments\">4.7 Payment gateway (online payments)</h3>\n<p><strong>Sidebar → Payment Gateway</strong> (<code>/dashboard/payment-settings</code>). Choose your provider (<strong>Xendit /\nMidtrans / Stripe</strong>) and enter live keys — or switch on <strong>Sandbox</strong> to demo the full QRIS flow\nwithout a real gateway. Secrets are stored encrypted.</p>\n<p><img src=\"/docs/images/owner-payment-settings.png\" alt=\"Payment gateway — provider + sandbox/live keys.\" loading=\"lazy\" /></p>\n<h3 id=\"48-users--roles-staff-logins\">4.8 Users &amp; roles (staff logins)</h3>\n<p><strong>Sidebar → Users &amp; Roles</strong> (<code>/dashboard/users</code>). Create logins for your staff.</p>\n<ol>\n<li>Click <strong>+ Add</strong> (or <strong>Invite</strong>).</li>\n<li>Enter their details and assign a <strong>role</strong> — a base role (<strong>Outlet Admin</strong> or <strong>Cashier</strong>) or a\n<strong>custom role</strong> with specific permissions.</li>\n<li>Place them in <strong>one or more branches</strong>.</li>\n</ol>\n<p><img src=\"/docs/images/owner-users.png\" alt=\"Users & roles — staff logins, roles and branch placement.\" loading=\"lazy\" /></p>\n<h3 id=\"49-vehicle-catalog\">4.9 Vehicle catalog</h3>\n<p><strong>Sidebar → Vehicles</strong> (<code>/dashboard/vehicles</code>). The brand → type lists that power the vehicle\ndropdowns at the POS and kiosk. Comes pre-seeded for the Indonesian market; edit as needed.</p>\n<p><img src=\"/docs/images/owner-vehicles.png\" alt=\"Vehicle catalog — brand → type dropdown data.\" loading=\"lazy\" /></p>\n<h3 id=\"410-legal-entities-optional\">4.10 Legal entities (optional)</h3>\n<p><strong>Sidebar → Legal Entities</strong> (<code>/dashboard/legal-entities</code>). If you invoice under one or more\ncompanies (PT), record them here and assign each branch to one.</p>\n<p><img src=\"/docs/images/owner-legal-entities.png\" alt=\"Legal entities.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"5-customers-memberships--bookings\">5. Customers, memberships &amp; bookings</h2>\n<h3 id=\"51-customers--crm\">5.1 Customers &amp; CRM</h3>\n<p><strong>Sidebar → Customers &amp; CRM</strong> (<code>/dashboard/crm</code>). The directory of <strong>every</strong> customer — members and\nnon-members — with new-customer growth. Each row shows a <strong>membership badge</strong> (Member / grace /\nsuspended / past member, or plain Customer). You can <strong>Edit</strong> and <strong>Delete</strong> a customer here; deep\nmembership management (renew, suspend, cards, history) lives on the <strong>Memberships → Members</strong> tab.</p>\n<p><img src=\"/docs/images/owner-crm.png\" alt=\"Customers & CRM — the full customer directory with membership badges.\" loading=\"lazy\" /></p>\n<h3 id=\"52-memberships\">5.2 Memberships</h3>\n<p><strong>Sidebar → Memberships</strong> (<code>/dashboard/memberships</code>). Three tabs:</p>\n<p><img src=\"/docs/images/owner-memberships.png\" alt=\"Memberships → Plans. Tabs across the top: Plans · Members · Cards.\" loading=\"lazy\" /></p>\n<ul>\n<li><strong>Plans</strong> — create membership plans. Click <strong>+ Add Plan</strong> and set: price, duration\n(1 / 3 / 6 / 12 months), <strong>usage quota</strong> (max uses), <strong>daily limit</strong>, <strong>max plates</strong>, the\n<strong>free washes</strong> and <strong>discounted services</strong> (a % per service), a <strong>WhatsApp welcome</strong> toggle,\nwhich <strong>branches</strong> it&#39;s available at, and an optional cross-branch <strong>settlement amount</strong>.</li>\n<li><strong>Members</strong> — every membership ever sold, with a status filter and search. Click a member to open\ntheir detail: card preview, plan/period/uses, event <strong>history</strong>, and the <strong>Print card / Renew /\nSuspend / Reactivate</strong> actions.</li>\n<li><strong>Cards</strong> — design the printable card (drag fields, upload front/back background, choose\nnumber/barcode/QR, fonts and colours). Also at <code>/dashboard/membership-card</code>.</li>\n</ul>\n<p><img src=\"/docs/images/owner-membership-card.png\" alt=\"Membership card designer.\" loading=\"lazy\" /></p>\n<blockquote>\n<p><strong>How the membership lifecycle works</strong> (sale → activate → benefits → grace → revoked → renewal,\nplus the 12-digit number and cross-branch settlement) is documented in full in\n<a href=\"/docs/tech-membership-lifecycle\">06 · Membership lifecycle</a>. <strong>Short version:</strong> benefits apply\nonly while a membership is truly <strong>active</strong>; after the end date it enters a <strong>14-day grace</strong> window\n(renewable, but no benefits), then becomes <strong>revoked</strong>. Renewal always takes <strong>payment first</strong> and\nonly extends once paid.</p>\n</blockquote>\n<h3 id=\"53-bookings\">5.3 Bookings</h3>\n<p><strong>Sidebar → Bookings</strong> (<code>/dashboard/bookings</code>). Create and confirm appointments. Bookings that\ncustomers request from the member portal land here; <strong>confirm</strong> one to drop that car onto the branch\nqueue for its time slot (the customer is notified over WhatsApp).</p>\n<p><img src=\"/docs/images/owner-bookings.png\" alt=\"Bookings — appointments and portal requests.\" loading=\"lazy\" /></p>\n<h3 id=\"54-whatsapp-broadcast-wa-broadcast\">5.4 WhatsApp broadcast (WA Broadcast)</h3>\n<p><strong>Sidebar → WA Broadcast</strong> (<code>/dashboard/broadcast</code>). Send a one-off marketing message to a <strong>segment</strong>\nof your customers over WhatsApp — a promo, a re-engagement nudge, a re-opening notice.</p>\n<p><img src=\"/docs/images/owner-broadcast.png\" alt=\"WA Broadcast — campaigns, delivery stats, and the ban-risk reminder.\" loading=\"lazy\" /></p>\n<p><strong>How a campaign works:</strong></p>\n<ol>\n<li>Click <strong>+ New campaign</strong>. Give it a <strong>name</strong> and pick an <strong>audience segment</strong>: <em>All customers</em>,\n<em>Active members</em>, <em>Expired members</em>, or <em>By tag</em> (then choose the tag). A live preview shows how\nmany people match — split into <strong>opted-in</strong>, and <strong>excluded (no consent)</strong>.</li>\n<li>Write the <strong>message</strong>. Use <code>{name}</code> anywhere to drop in each customer&#39;s name.</li>\n<li>Set a <strong>throttle</strong> (messages per minute — lower is safer) and, optionally, a <strong>schedule</strong> time.</li>\n<li>Click <strong>Create draft</strong>. Nothing sends yet.</li>\n<li>In the campaign, tick <strong>&quot;I understand the WhatsApp policy &amp; ban risk&quot;</strong> to unlock <strong>Start sending</strong>.\nYou can <strong>Pause</strong>, <strong>Resume</strong>, or <strong>Cancel</strong> at any time; a live progress bar shows <strong>sent / failed /\nskipped</strong>, and you can open the recipient list to see per-person status.</li>\n</ol>\n<blockquote>\n<p>⚠️ <strong>This is the highest-risk feature in the app.</strong> Bulk-messaging non-consenting numbers is the\nfastest way to get your WhatsApp line <strong>banned by Meta</strong>. By default airin <strong>only messages customers\nwho opted in</strong>, and paces sends with the throttle. There&#39;s a checkbox to include non-opted-in\ncustomers — leave it off unless you truly know what you&#39;re doing. Keep throttle low, keep messages\nrelevant, and warm up new numbers slowly.</p>\n</blockquote>\n<hr>\n<h2 id=\"6-vouchers--promotions\">6. Vouchers &amp; promotions</h2>\n<h3 id=\"61-vouchers\">6.1 Vouchers</h3>\n<p><strong>Sidebar → Vouchers</strong> (<code>/dashboard/vouchers</code>). Define voucher-pack templates and sell/issue code\npacks (a parent code + child codes, delivered over WhatsApp). There are also shareable digital\ntickets with human-readable codes.</p>\n<p><img src=\"/docs/images/owner-vouchers.png\" alt=\"Vouchers — pack templates and issued codes.\" loading=\"lazy\" /></p>\n<h3 id=\"62-promotions\">6.2 Promotions</h3>\n<p><strong>Sidebar → Promotions</strong> (<code>/dashboard/promotions</code>). Time-boxed campaigns: a fixed or percentage\ndiscount, a free product, a free voucher, or a future-discount — with optional trigger products,\nbranch scope, and a quota.</p>\n<p><img src=\"/docs/images/owner-promotions.png\" alt=\"Promotions — time-boxed campaigns.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"7-inventory-recipes-cogs--finance\">7. Inventory, recipes, COGS &amp; finance</h2>\n<p>This chain is how airin tracks <strong>true profit</strong>, not just revenue.</p>\n<h3 id=\"71-inventory\">7.1 Inventory</h3>\n<p><strong>Sidebar → Inventory</strong> (<code>/dashboard/inventory</code>). Stock items per branch. Add items, <strong>adjust</strong>\nin/out, and set <strong>unit conversions</strong> (buy in kg, consume in grams).</p>\n<p><img src=\"/docs/images/owner-inventory.png\" alt=\"Inventory — per-branch stock with adjustments.\" loading=\"lazy\" /></p>\n<h3 id=\"72-recipes-attached-to-services\">7.2 Recipes (attached to services)</h3>\n<p>On any service (<strong>Services → Recipe</strong>), define what it <strong>consumes</strong>: the inventory items used per\nunit, plus non-physical cost lines (tax, profit, water, electricity — as a fixed amount or a % of\nprice). When that service sells, stock is deducted automatically and the unit cost is <strong>frozen onto\nthe order line</strong>, so your margins stay accurate even if you change the recipe later.</p>\n<h3 id=\"73-procurement\">7.3 Procurement</h3>\n<p><strong>Sidebar → Procurement</strong> (<code>/dashboard/procurement</code>). Suppliers and purchase orders. <strong>Receiving</strong> a\nPO auto-restocks the linked inventory items.</p>\n<p><img src=\"/docs/images/owner-procurement.png\" alt=\"Procurement — suppliers and purchase orders.\" loading=\"lazy\" /></p>\n<h3 id=\"74-stock-opname-physical-count\">7.4 Stock opname (physical count)</h3>\n<p><strong>Sidebar → Stock Opname</strong> (<code>/dashboard/opname</code>). Start a count → enter the <strong>physical counts</strong> →\n<strong>Close</strong> to reconcile the system to reality and record the variance.</p>\n<p><img src=\"/docs/images/owner-opname.png\" alt=\"Stock opname — physical count and reconciliation.\" loading=\"lazy\" /></p>\n<h3 id=\"75-cogs--pl\">7.5 COGS &amp; P&amp;L</h3>\n<p><strong>Sidebar → COGS</strong> (<code>/dashboard/cogs</code>). The true profit view: <strong>revenue − cost of goods − expenses</strong>,\nper-product margin, and inventory variance.</p>\n<p><img src=\"/docs/images/owner-cogs.png\" alt=\"COGS & P&L — true profit and per-product margin.\" loading=\"lazy\" /></p>\n<h3 id=\"76-finance\">7.6 Finance</h3>\n<p><strong>Sidebar → Finance</strong> (<code>/dashboard/finance</code>). Revenue / expense / net-profit summary with a forecast,\nand <strong>+ Record expense</strong> to log outgoing costs by category. (Note: this page is <em>revenue − expenses</em>;\n<strong>COGS</strong> is the page that also subtracts cost of goods.)</p>\n<p><img src=\"/docs/images/owner-finance.png\" alt=\"Finance — revenue, expenses, net profit, and record-expense.\" loading=\"lazy\" /></p>\n<h3 id=\"77-settlement-cross-branch\">7.7 Settlement (cross-branch)</h3>\n<p><strong>Sidebar → Settlement</strong> (<code>/dashboard/settlement</code>). When a member washes at a branch other than their\n&quot;home&quot; branch, one branch owes the other. Settle/payout a branch pair here and see the history.</p>\n<p><img src=\"/docs/images/owner-settlement.png\" alt=\"Settlement — cross-branch amounts owed.\" loading=\"lazy\" /></p>\n<h3 id=\"78-accounting\">7.8 Accounting</h3>\n<p><strong>Sidebar → Accounting</strong> (<code>/dashboard/accounting</code>). The double-entry ledger behind the numbers\n(journal entries posted automatically by sales, opname, payroll, etc.).</p>\n<p><img src=\"/docs/images/owner-accounting.png\" alt=\"Accounting — the ledger.\" loading=\"lazy\" /></p>\n<h3 id=\"79-tax-invoices--faktur-pajak--e-faktur\">7.9 Tax invoices — Faktur Pajak / e-Faktur</h3>\n<p><strong>Sidebar → Tax Invoices</strong> (<code>/dashboard/tax-invoices</code>). If your business is <strong>PKP</strong> (VAT-registered)\nyou can issue a <strong>Faktur Pajak</strong> against an order and export a file ready to import into <strong>Coretax /\ne-Faktur</strong>.</p>\n<p><img src=\"/docs/images/owner-tax-invoices.png\" alt=\"Tax Invoices — issued Faktur Pajak with a date filter, plus Export to Coretax.\" loading=\"lazy\" /></p>\n<p><strong>One-time setup — the <code>Setup</code> tab.</strong> Tick <strong>Enable tax-invoice issuance</strong>, then fill your <strong>seller\nidentity</strong>: <strong>NPWP</strong>, seller <strong>name</strong>, seller <strong>address</strong>, the <strong>transaction code</strong> (kode transaksi,\ndefault <code>04</code>) and the <strong>Faktur prefix</strong> (default <code>010</code>). Save.</p>\n<p><strong>Issuing an invoice — the <code>Invoices</code> tab:</strong></p>\n<ol>\n<li>Click <strong>Generate from order</strong> and enter the <strong>Order ID</strong>. The order must already be\n<strong>paid / confirmed / completed</strong>.</li>\n<li>Optionally enter the buyer&#39;s <strong>NPWP</strong>, <strong>name</strong> and <strong>address</strong> — leave NPWP blank to use the\ncustomer&#39;s stored tax identity (it will show <em>&quot;No NPWP&quot;</em> if they have none).</li>\n<li><strong>Generate.</strong> The Faktur appears in the table with its number, <strong>DPP</strong> (tax base), <strong>PPN</strong> (VAT,\ncalculated at <strong>11%</strong>), status and date. <strong>Print</strong> opens an A4 Faktur Pajak you can save or print.</li>\n</ol>\n<p><strong>Exporting to Coretax.</strong> Pick a <strong>From / To</strong> date range and click <strong>Export to Coretax</strong> — you get a\nCSV in Coretax import format, and the exported invoices flip to status <strong>exported</strong> so you can see\nwhat&#39;s already been filed.</p>\n<hr>\n<h2 id=\"8-reporting\">8. Reporting</h2>\n<ul>\n<li><p><strong>Overview</strong> (<code>/dashboard</code>) — headline KPIs, revenue forecast vs target, AI proposals, and quick\nlinks, with a branch filter.</p>\n</li>\n<li><p><strong>Reports</strong> (<code>/dashboard/reports</code>) — four tabs over one set of filters (date range, business unit,\nbranch):</p>\n<ul>\n<li><strong>Reports</strong> — consolidated metrics (KPIs, AIRE/LEAD split, payment methods, top services, daily\nsales, per-shift cash) with <strong>PDF/CSV export</strong>.</li>\n<li><strong>Daily operations</strong> — one row per day, laid out like the sheet an outlet keeps by hand: revenue\nsplit per payment method <strong>and business unit</strong> (QRIS/debit/card each split AIRE vs LEAD, cash and\ntransfer whole), then the day&#39;s transactions, member vs non-member, items sold by category,\nmemberships <strong>sold new and renewed by plan length</strong>, and voucher packs. Revenue is what you\ncharged — QRIS/EDC fees are not deducted.</li>\n<li><strong>Sales per agent</strong> — an item × agent matrix: new memberships and renewals (by plan length),\nvoucher packs, and each product/service, counted per salesperson. It follows the <strong>salesperson\ncredited on the order</strong>, not the cashier, and orders with nobody credited sit in a final\n&quot;Tanpa agent&quot; column so the totals still add up.</li>\n<li><strong>Report Designer</strong> — layout/branding for printed reports.</li>\n</ul>\n<p>Both operational tabs export to CSV.</p>\n<p><img src=\"/docs/images/owner-reports.png\" alt=\"Reports — consolidated metrics with export.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Transactions</strong> (<code>/dashboard/transactions</code>) — charts plus the orders table (view / edit / void),\nwith <strong>Excel + PDF export</strong>. The orders table shows the <strong>payment method</strong> and a <strong>Member</strong> badge,\nand can be filtered by either.</p>\n<p><img src=\"/docs/images/owner-transactions.png\" alt=\"Transactions — orders table with charts and export.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Sales &amp; Leads</strong> (<code>/dashboard/sales</code>) — attainment vs a monthly <strong>target you set</strong>, a run-rate\nforecast, and a simple lead pipeline (new → contacted → won).</p>\n<p><img src=\"/docs/images/owner-sales.png\" alt=\"Sales & Leads — target attainment and pipeline.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Invoices</strong> (<code>/dashboard/invoices</code>) — print/save A4 invoices for paid orders.</p>\n<p><img src=\"/docs/images/owner-invoices.png\" alt=\"Invoices — printable A4 invoices.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Shifts &amp; Cash</strong> (<code>/dashboard/shifts</code>) — every register session across all branches, so you can\nreconcile cash without standing at the counter. Three tiles (Open now, Cash sales, Net variance)\nsummarise the <strong>rows currently filtered</strong> (by branch and date), and the table shows each shift&#39;s\n<strong>operator, opening float, cash &amp; expected &amp; counted amounts, and variance</strong> (green = balanced,\namber = small gap, red = investigate). Open a shift to see its <strong>petty-cash</strong> movements, any logged\n<strong>issues</strong>, and notes. This page is <strong>read-only</strong> — cashiers open and close shifts at the POS.</p>\n<p><img src=\"/docs/images/owner-shifts.png\" alt=\"Shifts & Cash — register sessions with counted-vs-expected variance.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Refunds</strong> (<code>/dashboard/refunds</code>) — the history of money returned to customers (full and partial).\nFilter by date and <strong>export CSV</strong>; each row shows the refund number, original order, amount, method,\nreason and branch, and opening one shows the refunded line-items and the <strong>PPN reversed</strong>. Refunds\nare <em>created</em> on the order/POS screen — this page is the record of them.</p>\n<p><img src=\"/docs/images/owner-refunds.png\" alt=\"Refunds — refund history with tax reversal.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Feedback &amp; NPS</strong> (<code>/dashboard/feedback</code>) — post-service ratings and NPS collected over WhatsApp.\nThe <strong>Overview</strong> tab shows your <strong>average rating</strong>, <strong>NPS score</strong>, response count, a star-distribution\nchart and recent comments; the <strong>Setup</strong> tab is where you switch it on (see §11.x below). <strong>Export CSV</strong>.</p>\n<p><img src=\"/docs/images/owner-feedback.png\" alt=\"Feedback & NPS — ratings, NPS, and comments.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>P&amp;L</strong> (<code>/dashboard/pnl</code>) — the profit-and-loss statement built from your accounting ledger.</p>\n<p><img src=\"/docs/images/owner-pnl.png\" alt=\"P&L — profit-and-loss statement.\" loading=\"lazy\" /></p>\n</li>\n</ul>\n<hr>\n<h2 id=\"9-people--hr--payroll\">9. People — HR &amp; payroll</h2>\n<ul>\n<li><p><strong>HR</strong> (<code>/dashboard/hr</code>) — employees (link a login to an employee record), schedules, clock in/out,\nleave approvals, and holidays.</p>\n<p><img src=\"/docs/images/owner-hr.png\" alt=\"HR — employees, schedules, clock-in, leave.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Payroll</strong> (<code>/dashboard/payroll</code>) — generate a payroll run for a period (base salary + bonuses −\ndeductions − advances − loan installments − unpaid leave), review payslips, <strong>Finalize</strong> to lock,\nand <strong>export</strong> payslips as CSV.</p>\n<p><img src=\"/docs/images/owner-payroll.png\" alt=\"Payroll — runs, payslips, finalize.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Commission</strong> (<code>/dashboard/commission</code>) — reward staff per job; whatever accrues flows into the\nnext <strong>payroll run automatically as a bonus</strong>. Two tabs:</p>\n<p><img src=\"/docs/images/owner-commission.png\" alt=\"Commission — accrual report and the rules engine.\" loading=\"lazy\" /></p>\n<ul>\n<li><strong>Report</strong> — pick a month to see commission accrued <strong>per employee</strong> (orders and rupiah), with\n<strong>Export CSV</strong>.</li>\n<li><strong>Setup</strong> — switch on <strong>per-job commission accrual</strong> (and optionally <strong>tips capture</strong>), then define\nthe <strong>rules</strong>. Each rule has a <strong>scope</strong> and a <strong>mode</strong>:<ul>\n<li><strong>Scopes</strong>, most-specific first: <strong>per staff → service/product → category → global</strong>. The most\nspecific matching rule wins.</li>\n<li><strong>Modes:</strong> <em>% of sale</em> (<code>pct_of_sale</code>), <em>% of a service line</em> (<code>per_service_pct</code>), <em>fixed per unit</em>\n(<code>per_service_fixed</code>), or <em>fixed per job</em> (<code>fixed_per_job</code>, paid once per order).</li>\n<li>The <strong>Per-staff rules</strong> panel lets you apply a rate to many employees at once (a per-staff rate\n<strong>overrides</strong> the general rules for that person), and <strong>Monthly target bonuses</strong> pay a flat bonus\nwhen an employee&#39;s monthly sales cross a target you set.</li>\n</ul>\n</li>\n</ul>\n<blockquote>\n<p><strong>Tip:</strong> start with a single <strong>global</strong> rule (e.g. 5% of sale), confirm the Report looks right for a\nweek, then add per-service or per-staff overrides. Because commission posts into payroll, changing a\nrule affects only <strong>future</strong> accrual — already-run payroll is untouched.</p>\n</blockquote>\n</li>\n</ul>\n<hr>\n<h2 id=\"10-ai-assistant--whatsapp\">10. AI assistant &amp; WhatsApp</h2>\n<p>airin has <strong>two different AIs</strong>, and it&#39;s important not to confuse them:</p>\n<ul>\n<li>the <strong>AI Assistant</strong> (§10.1) is <em>your</em> private co-pilot — it can see your whole business;</li>\n<li>the <strong>WhatsApp agent</strong> (§10.2) talks to <em>customers</em> — it can only ever see the one person chatting.</li>\n</ul>\n<h3 id=\"101-ai-assistant-your-co-pilot\">10.1 AI Assistant (your co-pilot)</h3>\n<p><strong>Sidebar → AI Assistant</strong> (<code>/dashboard/assistant</code>). Chat with a co-pilot that knows your business.\nAsk things like <em>&quot;how&#39;s business today?&quot;</em>, <em>&quot;which memberships expire in 30 days?&quot;</em>, or <em>&quot;show my last\n10 orders&quot;</em> (there are suggestion chips for these).</p>\n<p><img src=\"/docs/images/owner-assistant.png\" alt=\"AI Assistant — your business co-pilot.\" loading=\"lazy\" /></p>\n<ul>\n<li><strong>What it can read:</strong> your whole-business data — orders, customers, memberships, services, queue,\ninventory &amp; low stock, finance &amp; sales summaries, HR, procurement, shifts, payroll and loans. (This\nis deliberately broader than the customer WhatsApp agent.)</li>\n<li><strong>What it can do — with your approval:</strong> create a campaign, send a retention offer, adjust stock,\nrecord an expense, create a purchase order, add an employee, and more. Each action is governed by an\n<strong>approval mode</strong> you set (Settings → automation). In <strong>approval-required</strong> mode the assistant\ndoesn&#39;t act — it files a <strong>proposal</strong> that shows up on your <strong>Overview</strong> (AI Action Proposals) for\nyou to approve or reject. In <strong>autonomous</strong> mode it acts immediately and writes an audit entry.</li>\n</ul>\n<h3 id=\"102-agentic-ai--whatsapp-the-customer-facing-agent\">10.2 Agentic AI / WhatsApp (the customer-facing agent)</h3>\n<p><strong>Sidebar → Agentic AI</strong> (<code>/dashboard/ai-agent</code>). This is where you connect WhatsApp and shape how the\nagent talks to customers.</p>\n<p><img src=\"/docs/images/owner-ai-agent.png\" alt=\"Agentic AI / WhatsApp — connect and configure the WhatsApp agent.\" loading=\"lazy\" /></p>\n<p><strong>Connect a number.</strong> In <strong>WhatsApp connection</strong>, choose a provider — <strong>WAHA</strong> (scan a QR with the\nphone that will be the agent) or <strong>Kapso.com</strong> (paste an API key) — enter the <strong>WhatsApp number</strong> and,\nfor WAHA, a <strong>session name</strong>, then <strong>Connect / Get QR</strong> and scan.</p>\n<p><strong>Simulation mode (test without a real number).</strong> Flip <strong>Simulation mode</strong> on to trial the whole flow\nwith <strong>no real WhatsApp line</strong>: outgoing messages are <em>captured</em> in the Conversations page&#39;s <strong>Mock\noutbox</strong> instead of being sent. Turn it <strong>off</strong> to go live. <em>(On the production server this must be off\nto actually message customers.)</em></p>\n<p><strong>Shape the agent:</strong></p>\n<ul>\n<li><strong>AI auto-reply</strong> — the master switch for the agent replying at all (turn off to handle chats manually).</li>\n<li><strong>AI model</strong> — turn AI on, pick the <strong>provider</strong> (OpenRouter with your API key, or self-hosted Hermes\nAI) and use <strong>Test AI connection</strong> to confirm it works. The same key powers the co-pilot and any n8n\nflow. <em>(If AI is on but no key is set, customers get plain template replies — the page warns you.)</em></li>\n<li><strong>Base prompt</strong> — the agent&#39;s persona and core instructions.</li>\n<li><strong>Product knowledge</strong> — hours, products, membership info, SOP the agent should know.</li>\n<li><strong>Agent skills</strong> — what it&#39;s allowed to do, one per line.</li>\n<li><strong>Limits &amp; escalation</strong> — a <strong>max messages per user per day</strong> cap, and an <strong>escalation number</strong>\n(a supervisor) the agent hands off to.</li>\n</ul>\n<p><strong>Per-branch WhatsApp lines.</strong> In <strong>Separate WhatsApp per branch</strong>, turn on <code>perBranchWaEnabled</code>\n(save the page first) to give <strong>each outlet its own number &amp; QR</strong>. The escalation number, AI model,\nprompt, knowledge and daily cap stay <strong>shared</strong>; only the number is per-branch. A branch with <strong>no</strong>\nnumber set is simply <em>not connected</em> — it does <strong>not</strong> fall back to the main line. (The built-in agent\nuses the branch line; n8n flows and broadcasts always use the main line.)</p>\n<h3 id=\"103-agent-workflow-personas--routing\">10.3 Agent Workflow (personas &amp; routing)</h3>\n<p><strong>Sidebar → Agent Workflow</strong> (<code>/dashboard/agents</code>). Manage AI <strong>personas</strong> — each has a <strong>role</strong>\n(personal assistant / customer service / sales / supervisor), a description, a prompt, and an\nActive toggle. The role controls which customer tools the persona may use (e.g. <em>customer service</em>\ncan&#39;t create bookings). Under <strong>Agent engine</strong>, choose <strong>routing</strong>: the built-in engine, or a\npublished <strong>n8n flow</strong> (pick the WhatsApp flow and optional automation flow, and <strong>generate a bridge\ntoken</strong> to paste into the n8n credential). n8n flows themselves are built by the platform team.</p>\n<p><img src=\"/docs/images/owner-agents.png\" alt=\"Agent Workflow — personas and routing.\" loading=\"lazy\" /></p>\n<h3 id=\"104-conversations\">10.4 Conversations</h3>\n<p><strong>Sidebar → Conversations</strong> (<code>/dashboard/conversations</code>). The live customer ↔ AI chat log. Read any\nthread, <strong>toggle AI on/off</strong> for a single conversation, <strong>reply manually</strong>, <strong>summarize</strong>, or start a\n<strong>new session</strong>. Two things worth knowing:</p>\n<ul>\n<li><strong>Booking approvals</strong> — when the agent proposes a booking and the customer confirms it on WhatsApp,\nit lands here for you to <strong>Approve / Reject</strong> (you can also reply <em>TERIMA / TOLAK</em> on the escalation\nnumber). Confirmed bookings then drop onto the branch queue.</li>\n<li><strong>Mock outbox / Simulate inbound</strong> — in Simulation mode, this page shows captured outbound messages\nand lets you fake an inbound message to test the agent end-to-end.</li>\n</ul>\n<p><img src=\"/docs/images/owner-conversations.png\" alt=\"Conversations — live customer ↔ AI threads.\" loading=\"lazy\" /></p>\n<h3 id=\"105-monitoring\">10.5 Monitoring</h3>\n<p><strong>Sidebar → Monitoring</strong> (<code>/dashboard/monitoring</code>). Real-time AI usage: <strong>invocations, errors, token\ncount, estimated cost</strong>, calls broken down by type, top tools, and recent invocations/events. Watch\nthe <strong>error rate</strong> and <strong>token cost</strong> here.</p>\n<p><img src=\"/docs/images/owner-monitoring.png\" alt=\"AI monitoring — usage, errors, tokens and cost.\" loading=\"lazy\" /></p>\n<blockquote>\n<p><strong>Data safety (the customer agent).</strong> The WhatsApp agent is bound <strong>server-side to the phone number\nthat messaged you</strong> — it can only read <strong>that one customer&#39;s</strong> own memberships, orders, queue,\nvouchers and bookings, plus strictly <strong>public</strong> info (prices, plans, promos). It <strong>cannot</strong> reveal\nother customers, your revenue, payroll or costs — regardless of what a customer types to try to\ntrick it. Your co-pilot (§10.1) is the opposite: it sees everything, because it&#39;s <em>you</em>.</p>\n</blockquote>\n<hr>\n<h2 id=\"11-settings--configuration\">11. Settings &amp; configuration</h2>\n<p><strong>Sidebar → Settings</strong> (<code>/dashboard/settings</code>). Your tenant identity (read-only <strong>tenant code</strong>),\n<strong>branding</strong>, WhatsApp/AI toggles and LLM provider/key, and device discovery. Secrets are encrypted.</p>\n<p><img src=\"/docs/images/owner-settings.png\" alt=\"Settings — identity, branding, AI/WhatsApp, devices.\" loading=\"lazy\" /></p>\n<p>Related setup pages:</p>\n<ul>\n<li><p><strong>Finance setup</strong> (<code>/dashboard/finance-setup</code>) — one-click provisioning of finance defaults,\npayroll, PPN tax and pay-day automation.</p>\n<p><img src=\"/docs/images/owner-finance-setup.png\" alt=\"Finance setup — one-click finance/payroll provisioning.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>POS Terminals</strong> (<code>/dashboard/pos-devices</code>) — register the tablets/PCs that run the POS. Each\nterminal opens its <strong>launch URL</strong> once to become an authorized register (see the\n<a href=\"/docs/employee-manual\">Employee manual §1</a>).</p>\n<p><img src=\"/docs/images/owner-pos-devices.png\" alt=\"POS Terminals — register the devices that run the POS.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Kiosks</strong> (<code>/dashboard/kiosks</code>) — register the self-service kiosk tablets the same way.</p>\n<p><img src=\"/docs/images/owner-kiosks.png\" alt=\"Kiosks — register self-service kiosk devices.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Designers</strong> — drag-and-drop editors for every printed document: the <strong>receipt</strong>, <strong>invoice</strong>,\n<strong>membership card</strong>, <strong>barcode label</strong>, and <strong>report</strong> layouts (<code>/dashboard/receipt-designer</code>,\n<code>invoice-designer</code>, <code>membership-card</code>, <code>barcode-settings?tab=designer</code>, <code>report-designer</code>). Each\nworks the same way: drag fields onto the canvas, set fonts/sizes/alignment, optionally upload a\nbackground, and use <strong>Preview</strong> to print with sample data.</p>\n<p><img src=\"/docs/images/owner-invoice-designer.png\" alt=\"The invoice designer — drag fields onto the A4 canvas.\" loading=\"lazy\" />\n<img src=\"/docs/images/owner-receipt-designer.png\" alt=\"The receipt designer.\" loading=\"lazy\" />\n<img src=\"/docs/images/owner-report-designer.png\" alt=\"The report designer.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Devices / Topology / CCTV</strong> (<code>/dashboard/devices</code>, <code>topology</code>, <code>cctv</code>) — the on-premise\n<strong>branch-bridge</strong> IoT and CCTV integration, if you use it. <strong>Devices</strong> lists the hardware the\nbridge discovered at a branch, <strong>Topology</strong> maps how they&#39;re wired, and <strong>CCTV</strong> streams live and\nrecorded footage. (Setup detail is in the <a href=\"/docs/tech-branch-bridge-protocol\">Branch-Bridge</a> and\n<a href=\"/docs/tech-device-registry-topology\">Device Registry</a> technical notes.)</p>\n<p><img src=\"/docs/images/owner-devices.png\" alt=\"Devices — hardware discovered by the branch bridge.\" loading=\"lazy\" />\n<img src=\"/docs/images/owner-topology.png\" alt=\"Topology — how branch devices are wired together.\" loading=\"lazy\" />\n<img src=\"/docs/images/owner-cctv.png\" alt=\"CCTV — live and recorded footage per branch.\" loading=\"lazy\" /></p>\n</li>\n</ul>\n<h3 id=\"111-barcodes-settings--barcodes\">11.1 Barcodes (Settings → Barcodes)</h3>\n<p><strong>Sidebar → Barcodes</strong> (<code>/dashboard/barcode-settings</code>). Turn on product barcodes to unlock\n<strong>scan-to-cart</strong> at the POS and the label designer. On the <strong>Settings</strong> tab tick <strong>Enable product\nbarcodes</strong>, then choose a <strong>symbology</strong> (CODE128 / EAN-13 / QR) and options: <strong>auto-generate</strong> a\nunique in-store barcode for new products, <strong>scan adds to cart at POS</strong>, and <strong>print label on receive</strong>.\nA <strong>Label Designer</strong> tab appears once barcodes are enabled — design the printed label there.</p>\n<p><img src=\"/docs/images/owner-barcode-settings.png\" alt=\"Barcodes — enable scanning and pick a symbology.\" loading=\"lazy\" />\n<img src=\"/docs/images/owner-barcode-designer.png\" alt=\"The barcode label designer.\" loading=\"lazy\" /></p>\n<h3 id=\"112-feedback-setup-feedback--nps--setup\">11.2 Feedback setup (Feedback &amp; NPS → Setup)</h3>\n<p><strong>Sidebar → Feedback &amp; NPS → Setup</strong> (<code>/dashboard/feedback</code>). Tick <strong>Enable customer feedback</strong>, then\noptionally <strong>send automatically when an order is paid</strong> (a WhatsApp link goes out after payment). Write\nthe <strong>WhatsApp message</strong>, set a <strong>send delay</strong> (0 = immediately) and how long the <strong>link stays valid</strong>\n(1–90 days). Turn on <strong>alerts</strong> to be warned about low ratings (≤ a threshold you pick) or <strong>NPS\ndetractors</strong> (0–6). You can also build the <strong>survey questions</strong> — the star <strong>rating</strong> question is always\ncollected; you can add extra rating/NPS/text questions and toggle them on or off. (Results live on the\n<strong>Overview</strong> tab — see §8.)</p>\n<h3 id=\"113-audit-log-settings--audit-log\">11.3 Audit log (Settings → Audit log)</h3>\n<p><strong>Sidebar → Audit log</strong> (<code>/dashboard/audit</code>). A read-only record of every security-relevant change in\nyour business — order <strong>voids</strong>, cancellations, edits, shift openings — with <strong>who, when, from which IP,\nand the before/after values</strong>. Filter by <strong>operation</strong> (e.g. <code>order.void</code>), <strong>entity</strong> (e.g. <code>order</code>)\nand date range, and open any row to see the full before → after JSON. Use it to investigate a\ndisputed void or a &quot;who changed this?&quot; question.</p>\n<p><img src=\"/docs/images/owner-audit.png\" alt=\"Audit log — who changed what, when, with before/after.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"12-tips--troubleshooting\">12. Tips &amp; troubleshooting</h2>\n<ul>\n<li><strong>A menu is missing?</strong> That module was turned off by the platform administrator — the default is\neverything on. Ask them to enable it.</li>\n<li><strong>Two business units.</strong> Tag every service correctly as <strong>AIRE</strong> (wash) or <strong>LEAD</strong> (detailing) —\nreports, payment channels and revenue split all rely on it.</li>\n<li><strong>Branch phone numbers</strong> must be set (and WhatsApp connected) for portal bookings and\nexpiry/notification messages to work.</li>\n<li><strong>WhatsApp features</strong> need a <strong>connected</strong> WAHA/Kapso session (Agentic AI page).</li>\n<li><strong>Numbers look wrong?</strong> Remember: <strong>Finance</strong> = revenue − expenses; <strong>COGS</strong> = revenue − cost of\ngoods − expenses. Use COGS for true margin.</li>\n<li><strong>Member pricing not applying at the counter?</strong> The membership may be in grace or expired — check\nthe member&#39;s detail on <strong>Memberships → Members</strong>.</li>\n<li><strong>A broadcast is skipping most people?</strong> By design it only messages <strong>opted-in</strong> customers — the\n&quot;excluded (no consent)&quot; count is normal. Don&#39;t force-include them unless you understand the ban risk.</li>\n<li><strong>The WhatsApp agent replies with generic text?</strong> AI is on but no <strong>API key</strong> is set, or AI auto-reply\nis off — check <strong>Agentic AI → AI model</strong> (§10.2).</li>\n<li><strong>Tax invoice won&#39;t generate?</strong> The order must be <strong>paid/confirmed/completed</strong>, and tax-invoice\nissuance must be <strong>enabled</strong> with your seller NPWP filled in (§7.9).</li>\n<li><strong>&quot;Who voided this order?&quot;</strong> Open <strong>Audit log</strong> (§11.3) and filter operation <code>order.void</code>.</li>\n</ul>\n<p><strong>Recommended setup order (first week):</strong>\nBranding → Branches → Catalog → Services → Payment methods → Payment gateway → Users &amp; roles →\nVehicle catalog → Membership plans → (Inventory + Recipes if you track COGS) → Finance setup →\nregister POS terminals &amp; kiosks → (optional) connect WhatsApp &amp; AI, enable Feedback, Barcodes, Tax.</p>\n<hr>\n<h2 id=\"13-glossary\">13. Glossary</h2>\n<table>\n<thead>\n<tr>\n<th>Term</th>\n<th>What it means</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Tenant / tenant code</strong></td>\n<td>Your business on the platform. Its permanent <strong>6-character code</strong> prefixes every membership number you issue and never changes.</td>\n</tr>\n<tr>\n<td><strong>Business unit — AIRE / LEAD</strong></td>\n<td>The tag on every service and order: <strong>AIRE</strong> = car wash, <strong>LEAD</strong> = detailing/coating. Reports and revenue split rely on it.</td>\n</tr>\n<tr>\n<td><strong>Branch / outlet</strong></td>\n<td>One physical location. Has a 3-letter code used on receipts and membership numbers.</td>\n</tr>\n<tr>\n<td><strong>Module</strong></td>\n<td>A whole feature area (Memberships, Finance, AI…) the platform can switch on/off for your business.</td>\n</tr>\n<tr>\n<td><strong>Grace period</strong></td>\n<td>The <strong>14 days</strong> after a membership&#39;s end date: still renewable, but <strong>no member benefits</strong> apply.</td>\n</tr>\n<tr>\n<td><strong>Recipe</strong></td>\n<td>What a service <em>consumes</em> (inventory items + cost lines). Drives COGS; the unit cost is frozen onto each order line at sale time.</td>\n</tr>\n<tr>\n<td><strong>COGS vs Finance</strong></td>\n<td><strong>Finance</strong> = revenue − expenses. <strong>COGS</strong> = revenue − cost of goods − expenses (true margin).</td>\n</tr>\n<tr>\n<td><strong>Settlement</strong></td>\n<td>Money owed between branches when a member is served away from their home branch.</td>\n</tr>\n<tr>\n<td><strong>Opname</strong></td>\n<td>A physical stock count that reconciles the system to reality and records the variance.</td>\n</tr>\n<tr>\n<td><strong>Faktur Pajak / e-Faktur / Coretax</strong></td>\n<td>Indonesian VAT invoice (§7.9) and the government import format you export for filing.</td>\n</tr>\n<tr>\n<td><strong>NPS</strong></td>\n<td>Net Promoter Score — a −100…+100 loyalty measure from the feedback survey.</td>\n</tr>\n<tr>\n<td><strong>WAHA / Kapso</strong></td>\n<td>The two ways to connect a WhatsApp line for the AI agent.</td>\n</tr>\n<tr>\n<td><strong>Simulation / mock mode</strong></td>\n<td>Testing the WhatsApp flow with no real line — outgoing messages are captured, not sent.</td>\n</tr>\n<tr>\n<td><strong>Persona</strong></td>\n<td>An AI character (role + prompt) that governs how the customer agent talks and what it may do.</td>\n</tr>\n<tr>\n<td><strong>Proposal</strong></td>\n<td>An action the AI co-pilot wants to take, waiting for your approval (Overview → AI Action Proposals).</td>\n</tr>\n<tr>\n<td><strong>Escalation number</strong></td>\n<td>The supervisor&#39;s WhatsApp the agent hands a customer off to.</td>\n</tr>\n</tbody></table>\n"},{"slug":"employee-manual","title":"Employee — User Manual (Cashier · Outlet Admin · HR)","category":"manual","audience":"Employee","blurb":"POS, arrival queue, shifts, memberships, stock and HR.","order":2,"words":2117,"minutes":11,"toc":[{"id":"table-of-contents","text":"Table of contents","level":2},{"id":"1-sign-in--open-the-pos","text":"1. Sign in & open the POS","level":2},{"id":"2-start-your-day-open-a-shift","text":"2. Start your day: open a shift","level":2},{"id":"3-the-pos-at-a-glance","text":"3. The POS at a glance","level":2},{"id":"4-take-a-sale-new-order","text":"4. Take a sale (New Order)","level":2},{"id":"5-the-arrival-queue","text":"5. The arrival queue","level":2},{"id":"6-memberships--voucher-packs-same-new-order-screen","text":"6. Memberships & voucher packs (same New Order screen)","level":2},{"id":"sell-a-membership-including-the-upsell-at-the-counter","text":"Sell a membership (including the upsell at the counter)","level":3},{"id":"renew-an-existing-member","text":"Renew an existing member","level":3},{"id":"manage-a-member-plates-cancellation","text":"Manage a member (plates, cancellation)","level":3},{"id":"sell-a-voucher-pack","text":"Sell a voucher pack","level":3},{"id":"7-orders--the-day-summary","text":"7. Orders & the day summary","level":2},{"id":"8-close-your-shift","text":"8. Close your shift","level":2},{"id":"9-inventory--stock-outlet-admin","text":"9. Inventory & stock (Outlet Admin)","level":2},{"id":"10-hr--payroll-hr-staff","text":"10. HR & payroll (HR staff)","level":2},{"id":"11-your-own-self-service-page","text":"11. Your own self-service page","level":2},{"id":"12-quick-reference","text":"12. Quick reference","level":2}],"html":"<h1 id=\"employee--user-manual-cashier--outlet-admin--hr\">Employee — User Manual (Cashier · Outlet Admin · HR)</h1>\n<p><strong>Who this is for:</strong> you work at a branch. Depending on your role you run the <strong>point of sale (POS)</strong>,\nthe <strong>arrival queue</strong>, sell memberships and vouchers, manage stock, or handle HR &amp; payroll.</p>\n<ul>\n<li><strong>Cashier</strong> — POS, queue, shifts, selling memberships/vouchers.</li>\n<li><strong>Outlet Admin</strong> — everything a cashier can do, <strong>plus</strong> edit/void orders, suspend/reactivate\nmemberships, branch inventory / procurement / opname, and branch reports.</li>\n<li><strong>HR staff</strong> — the HR and payroll pages.</li>\n</ul>\n<blockquote>\n<p><strong>Language:</strong> use the <strong>EN / ID</strong> toggle (top-right of the POS, bottom-left of the Dashboard) to\nswitch English ↔ Indonesian at any time.</p>\n</blockquote>\n<hr>\n<h2 id=\"table-of-contents\">Table of contents</h2>\n<ol>\n<li><a href=\"#1-sign-in--open-the-pos\">Sign in &amp; open the POS</a></li>\n<li><a href=\"#2-start-your-day-open-a-shift\">Start your day: open a shift</a></li>\n<li><a href=\"#3-the-pos-at-a-glance\">The POS at a glance</a></li>\n<li><a href=\"#4-take-a-sale-new-order\">Take a sale (New Order)</a></li>\n<li><a href=\"#5-the-arrival-queue\">The arrival queue</a></li>\n<li><a href=\"#6-memberships--voucher-packs-same-new-order-screen\">Memberships &amp; voucher packs (same New Order screen)</a></li>\n<li><a href=\"#7-orders--the-day-summary\">Orders &amp; the day summary</a></li>\n<li><a href=\"#8-close-your-shift\">Close your shift</a></li>\n<li><a href=\"#9-inventory--stock-outlet-admin\">Inventory &amp; stock (Outlet Admin)</a></li>\n<li><a href=\"#10-hr--payroll-hr-staff\">HR &amp; payroll (HR staff)</a></li>\n<li><a href=\"#11-your-own-self-service-page\">Your own self-service page (every employee)</a></li>\n<li><a href=\"#12-quick-reference\">Quick reference</a></li>\n</ol>\n<hr>\n<h2 id=\"1-sign-in--open-the-pos\">1. Sign in &amp; open the POS</h2>\n<p>The POS runs on a <strong>registered terminal</strong> (a specific tablet or PC). There are two one-time and\neveryday steps:</p>\n<p><strong>A. Register the terminal (once per device).</strong> The first time a device opens the POS it shows\n<em>&quot;This terminal is not registered.&quot;</em> Your owner/outlet admin gets the <strong>launch URL</strong> from\n<strong>Dashboard → POS Terminals</strong> and opens it on this device (or pastes it into the box). After that,\nthe device stays registered and remembers its branch.</p>\n<p><img src=\"/docs/images/pos-01-launch.png\" alt=\"First run on a new device — paste the launch URL from Dashboard → POS Terminals to register it.\" loading=\"lazy\" /></p>\n<p><strong>B. Sign in (every shift).</strong> On a registered terminal, sign in with <strong>your own email + password</strong>\n(cashiers can also use the <strong>Employee · Cashier</strong> demo card on a demo system). Signing in with your\nown account is what attributes orders and shifts to <strong>you</strong>.</p>\n<p>Once you&#39;re in, the POS opens on its tabs. The branch you&#39;re working at is shown at the top-left\n(e.g. <em>&quot;Branch: AIRE Bintaro&quot;</em>).</p>\n<hr>\n<h2 id=\"2-start-your-day-open-a-shift\">2. Start your day: open a shift</h2>\n<p><strong>You must have an open shift before you can take any orders.</strong> Every sale is booked into your shift,\nand the shift fixes the branch — so end-of-day cash always reconciles to the right place.</p>\n<ol>\n<li>Go to the <strong>Shift</strong> tab.</li>\n<li>In <strong>Open shift</strong>, enter the <strong>opening cash float</strong> (the cash already in the drawer).</li>\n<li>If you&#39;re not on today&#39;s schedule (or scheduled at another branch), a <strong>Reason</strong> field appears —\nit&#39;s required, and it&#39;s logged for attendance.</li>\n<li>Click <strong>Open Shift</strong>.</li>\n</ol>\n<p><img src=\"/docs/images/pos-02-shift.png\" alt=\"The Shift tab — enter the opening cash float and click Open Shift. Recent shifts are listed below.\" loading=\"lazy\" /></p>\n<p>While the shift is open, everything you sell belongs to it.</p>\n<hr>\n<h2 id=\"3-the-pos-at-a-glance\">3. The POS at a glance</h2>\n<p>Across the top of the POS are five tabs:</p>\n<p><strong>New Order · Orders · Queue · Summary · Shift</strong></p>\n<ul>\n<li><strong>New Order</strong> — ring up a sale, and sell/renew memberships and voucher packs. There is no\nseparate Sell Pack tab any more: a plan sold while a customer is paying for a wash goes on the\n<strong>same order</strong>, so it is one transaction (see §6).</li>\n<li><strong>Orders</strong> — browse/search today&#39;s orders.</li>\n<li><strong>Queue</strong> — the arrival board (cars waiting).</li>\n<li><strong>Summary</strong> — today&#39;s totals.</li>\n<li><strong>Shift</strong> — open/close the register.</li>\n</ul>\n<hr>\n<h2 id=\"4-take-a-sale-new-order\">4. Take a sale (New Order)</h2>\n<p><img src=\"/docs/images/pos-03-new-order.png\" alt=\"New Order — the service grid on the left, the order panel (member lookup, customer details, cart, payment) on the right. The banner reminds you to open a shift first.\" loading=\"lazy\" /></p>\n<ol>\n<li>Pick the <strong>business unit</strong> at the top of the service grid — <strong>AIRE · Wash</strong> or <strong>LEAD · Detail</strong>.\nThe grid filters, but both share <strong>one cart and one receipt</strong>.</li>\n<li><strong>Tap services</strong> to add them to the cart (right-hand <strong>Order</strong> panel).</li>\n<li>Enter the customer&#39;s <strong>name</strong> and <strong>phone</strong>, and the vehicle <strong>plate / brand / type</strong> (the\nbrand → type dropdowns help).</li>\n<li><strong>Find member</strong> <em>(optional)</em> — type a plate, phone, or 12-character membership number in the\n<strong>Find member</strong> box (or scan the card) and click <strong>Find</strong>:<ul>\n<li>If they&#39;re an <strong>active</strong> member, member pricing applies automatically and their card can show.</li>\n<li>If their membership is <strong>expiring soon, in grace, revoked, or suspended</strong>, you&#39;ll see an alert\nwith a <strong>&quot;Renew now&quot;</strong> button that starts the renewal right there. Grace/revoked members get\n<strong>no</strong> benefits until renewed.</li>\n</ul>\n</li>\n<li><strong>Voucher code</strong> <em>(optional)</em> — type a code and click <strong>Apply</strong>; valid ones appear as removable\nchips.</li>\n<li>Click <strong>Place Order</strong> (the button reads <strong>&quot;Open a shift first&quot;</strong> until you&#39;ve opened a shift —\nsee §2), then take payment:<ul>\n<li><strong>Cash</strong> — enter the amount received; the change to give is shown.</li>\n<li><strong>QRIS (dynamic)</strong> — a QR appears; the screen waits and <strong>confirms automatically</strong> once the\ncustomer pays.</li>\n<li><strong>EDC / card / transfer</strong> — record the method.</li>\n</ul>\n</li>\n<li>A receipt appears — start the next order.</li>\n</ol>\n<blockquote>\n<p><strong>Order from the queue.</strong> If a car is already on the arrival board, use <strong>Order from Queue</strong> (or the\nQueue tab&#39;s <strong>Proses Bayar</strong>): the order prefills the plate/vehicle and, for members, the\nname/phone — you just take payment. Think of it like picking a table in a restaurant and printing\nthe check.</p>\n</blockquote>\n<hr>\n<h2 id=\"5-the-arrival-queue\">5. The arrival queue</h2>\n<p><strong>Queue tab.</strong> The queue is your branch&#39;s operational board. Two things are tracked <strong>separately</strong>:</p>\n<ul>\n<li><strong>Service status:</strong> waiting → serving → done.</li>\n<li><strong>Payment status:</strong> paid / unpaid (a badge, derived from the order — you never set it by hand).</li>\n</ul>\n<p><img src=\"/docs/images/pos-04-queue.png\" alt=\"The Queue tab — \"Log Arrival\" on the left to record a car; \"In Queue\" on the right shows who's waiting.\" loading=\"lazy\" /></p>\n<p><strong>Typical flow:</strong></p>\n<ol>\n<li>A car arrives → in <strong>Log Arrival</strong>, pick <strong>AIRE</strong> or <strong>LEAD</strong>, enter the <strong>plate</strong> (and optional\nbrand/type), and click <strong>+ Add to queue</strong>. No order is created yet.</li>\n<li>When it&#39;s their turn, select the car and choose <strong>Proses Bayar</strong> → the New Order screen prefills →\ntake payment.</li>\n<li>When the wash is finished, mark the car <strong>Done</strong>.</li>\n</ol>\n<blockquote>\n<p>⚠️ <strong>You cannot mark a car &quot;Done&quot; until its order is paid.</strong> Collect payment first.</p>\n</blockquote>\n<p>The public <strong>Queue Board</strong> (<code>/queue-board/...</code>) is a full-screen TV display of this same queue for\nthe waiting area.</p>\n<hr>\n<h2 id=\"6-memberships--voucher-packs-same-new-order-screen\">6. Memberships &amp; voucher packs (same New Order screen)</h2>\n<p><strong>New Order → the &quot;Membership &amp; Vouchers&quot; tab</strong>, next to <strong>Services</strong>. Whatever you pick there\njoins the order you are already ringing up, so the customer pays <strong>once</strong>.</p>\n<p><img src=\"/docs/images/pos-05-sell-pack.png\" alt=\"New Order → Membership & Vouchers — pick a plan or a voucher pack; it lands in the same cart as the wash.\" loading=\"lazy\" /></p>\n<h3 id=\"sell-a-membership-including-the-upsell-at-the-counter\">Sell a membership (including the upsell at the counter)</h3>\n<ol>\n<li>Ring up the wash as usual, then open the <strong>Membership &amp; Vouchers</strong> tab and tap a <strong>plan</strong>.\nIt appears in the cart above the services.</li>\n<li>If the customer is having a wash on this same order, <strong>that wash becomes free</strong> — the cart\nshows it, and the total is just the plan price. The sale still records as an upsell, so it\nshows up in the owner&#39;s reports as a new member (not as a discount).</li>\n<li>Click <strong>Place Order</strong> → take payment as normal.</li>\n<li><strong>Register the customer&#39;s vehicle plate(s)</strong> (up to the plan&#39;s limit) → <strong>Save &amp; Activate</strong>.\nThe first plate is pre-filled from the plate you already typed on the order.</li>\n<li>The membership is now active; the member number is issued and a WhatsApp welcome may be sent.</li>\n</ol>\n<blockquote>\n<p>The free wash uses <strong>one</strong> of the member&#39;s washes for the day, so their remaining quota reflects\nthe wash they just had.</p>\n</blockquote>\n<h3 id=\"renew-an-existing-member\">Renew an existing member</h3>\n<ol>\n<li>Use <strong>Find member</strong> in the order panel — by plate, phone, or 12-character number.</li>\n<li>Pick the plan to renew on, then click <strong>Renew &amp; pay</strong> → take payment.</li>\n<li>The renewal takes effect <strong>only after</strong> the fee is paid (this is automatic). <strong>Active/grace</strong>\nmembers are <strong>extended</strong>; <strong>revoked</strong> members get a <strong>new</strong> membership.</li>\n</ol>\n<h3 id=\"manage-a-member-plates-cancellation\">Manage a member (plates, cancellation)</h3>\n<p>After <strong>Find member</strong>, click <strong>Manage member</strong> to view/edit their registered plates or cancel the\nmembership.</p>\n<h3 id=\"sell-a-voucher-pack\">Sell a voucher pack</h3>\n<ol>\n<li>On the <strong>Membership &amp; Vouchers</strong> tab, pick a <strong>voucher pack</strong> → <strong>Place Order</strong> → take payment.</li>\n<li>The codes are generated and <strong>sent to the buyer over WhatsApp</strong> automatically, and shown on\nscreen once.</li>\n</ol>\n<hr>\n<h2 id=\"7-orders--the-day-summary\">7. Orders &amp; the day summary</h2>\n<ul>\n<li><p><strong>Orders tab</strong> — browse and search today&#39;s orders by status. Outlet Admins can <strong>edit</strong> customer\ndetails or <strong>void</strong> an order (only while the shift is open).</p>\n<p><img src=\"/docs/images/pos-06-orders.png\" alt=\"Orders — today's orders, searchable by status.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Summary tab</strong> — today&#39;s totals for your branch/shift at a glance.</p>\n<p><img src=\"/docs/images/pos-07-summary.png\" alt=\"Summary — the day's totals.\" loading=\"lazy\" /></p>\n</li>\n</ul>\n<hr>\n<h2 id=\"8-close-your-shift\">8. Close your shift</h2>\n<p>At the end of your shift, go to <strong>Shift → Close shift</strong>:</p>\n<ol>\n<li>Count the cash drawer and enter the <strong>counted amount</strong>.</li>\n<li>The system shows the <strong>expected</strong> amount (opening float + cash sales + petty-in − petty-out) and\nthe <strong>variance</strong>.</li>\n<li>Log any <strong>petty cash</strong> movements or <strong>shift issues</strong> before closing.</li>\n<li>Confirm to close.</li>\n</ol>\n<blockquote>\n<p>Once a shift is closed, its orders are <strong>locked</strong> for the day — no more edits or voids.</p>\n</blockquote>\n<hr>\n<h2 id=\"9-inventory--stock-outlet-admin\">9. Inventory &amp; stock (Outlet Admin)</h2>\n<p>These live in the <strong>Dashboard</strong> (not the POS):</p>\n<ul>\n<li><strong>Inventory</strong> (<code>/dashboard/inventory</code>) — view stock, add items, <strong>adjust</strong> in/out.</li>\n<li><strong>Procurement</strong> (<code>/dashboard/procurement</code>) — create purchase orders and <strong>Receive</strong> them (which\nrestocks automatically).</li>\n<li><strong>Stock Opname</strong> (<code>/dashboard/opname</code>) — start a count → enter the physical counts → <strong>Close</strong> to\nreconcile the system to reality and record any variance.</li>\n</ul>\n<blockquote>\n<p>A sale at the POS is <strong>never blocked</strong> by low stock — you can always ring it up. But the <strong>kiosk</strong>\nand public <strong>eMenu</strong> hide out-of-stock products from customers.</p>\n</blockquote>\n<hr>\n<h2 id=\"10-hr--payroll-hr-staff\">10. HR &amp; payroll (HR staff)</h2>\n<ul>\n<li><strong>HR</strong> (<code>/dashboard/hr</code>) — manage employees, <strong>clock in/out</strong>, schedules, leave requests\n(approve/reject), and holidays. You can <strong>link</strong> an employee record to their login account.</li>\n<li><strong>Payroll</strong> (<code>/dashboard/payroll</code>) — add bonuses / deductions / advances / loans, <strong>generate</strong> a\npayroll run for the month, review payslips, <strong>Finalize</strong> to lock it, and <strong>export</strong> payslips as\nCSV.</li>\n</ul>\n<p>(Screenshots and detail are in the <a href=\"/docs/tenant-owner-manual\">Tenant Owner manual §9</a>.)</p>\n<hr>\n<h2 id=\"11-your-own-self-service-page\">11. Your own self-service page</h2>\n<p>Every employee — not just HR — has a personal self-service page at <strong><code>/employee</code></strong>. Sign in with your\nown account and open it from the Hub. It&#39;s <em>your</em> information only; you can&#39;t see anyone else&#39;s.</p>\n<p><img src=\"/docs/images/emp-self-service.png\" alt=\"The employee self-service page — your schedule, attendance, payslips, leave and loans.\" loading=\"lazy\" /></p>\n<p>Across the top are tabs:</p>\n<ul>\n<li><strong>Home</strong> — today at a glance: your <strong>shift</strong>, whether you&#39;ve <strong>clocked in/out</strong>, and hours worked.</li>\n<li><strong>Schedule</strong> — your upcoming shifts (date, times, branch).</li>\n<li><strong>Attendance</strong> — your clock-in/out history and hours per day.</li>\n<li><strong>Payslips</strong> — each finalized payslip, with the full breakdown (base salary, days worked, bonuses,\ndeductions, advances, loan repayments, unpaid-leave deduction, and <strong>net pay</strong>).</li>\n<li><strong>Leave</strong> — request time off (start/end dates, type, reason) and see whether each request is\n<strong>pending / approved / rejected</strong>, and whether it&#39;s paid.</li>\n<li><strong>Loans</strong> — any staff loan or advance you&#39;ve been given: the principal, remaining balance, monthly\ninstallment, and the repayments already taken from your pay.</li>\n<li><strong>Profile</strong> — your own details (role, branch, employment type, contact info).</li>\n</ul>\n<blockquote>\n<p><strong>Cashier vs. self-service.</strong> The <strong>POS</strong> is where you <em>work</em> (sell, queue, shifts). This\n<strong><code>/employee</code></strong> page is where you check <em>your own</em> schedule, attendance and pay. Two different\nscreens, both signed in as you.</p>\n</blockquote>\n<hr>\n<h2 id=\"12-quick-reference\">12. Quick reference</h2>\n<table>\n<thead>\n<tr>\n<th>I want to…</th>\n<th>Go to</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Open / close the register</td>\n<td>POS → <strong>Shift</strong></td>\n</tr>\n<tr>\n<td>Take a sale</td>\n<td>POS → <strong>New Order</strong></td>\n</tr>\n<tr>\n<td>Take payment for a queued car</td>\n<td>POS → <strong>Queue</strong> → <strong>Proses Bayar</strong></td>\n</tr>\n<tr>\n<td>Add a walk-in to the queue</td>\n<td>POS → <strong>Queue</strong> → <strong>Log Arrival → + Add to queue</strong></td>\n</tr>\n<tr>\n<td>Find a member&#39;s details/pricing</td>\n<td>POS → <strong>New Order</strong> → <strong>Find member</strong></td>\n</tr>\n<tr>\n<td>Sell or renew a membership</td>\n<td>POS → <strong>New Order → Membership &amp; Vouchers</strong></td>\n</tr>\n<tr>\n<td>Sell a voucher pack</td>\n<td>POS → <strong>New Order → Membership &amp; Vouchers</strong></td>\n</tr>\n<tr>\n<td>See today&#39;s totals</td>\n<td>POS → <strong>Summary</strong></td>\n</tr>\n<tr>\n<td>Edit or void an order (Outlet Admin)</td>\n<td>POS → <strong>Orders</strong></td>\n</tr>\n<tr>\n<td>Receive stock (Outlet Admin)</td>\n<td>Dashboard → <strong>Procurement</strong></td>\n</tr>\n<tr>\n<td>Count stock (Outlet Admin)</td>\n<td>Dashboard → <strong>Stock Opname</strong></td>\n</tr>\n</tbody></table>\n<blockquote>\n<p><strong>Remember the two golden rules:</strong> (1) <strong>open a shift before selling</strong>, and (2) <strong>a car can&#39;t be\n&quot;Done&quot; until its order is paid.</strong></p>\n</blockquote>\n"},{"slug":"customer-manual","title":"Customer — User Manual","category":"manual","audience":"Customer","blurb":"eMenu, kiosk, queue, member portal, bookings and WhatsApp.","order":3,"words":1122,"minutes":6,"toc":[{"id":"table-of-contents","text":"Table of contents","level":2},{"id":"1-browse-the-price-menu-no-sign-in","text":"1. Browse the price menu (no sign-in)","level":2},{"id":"2-order-at-the-self-service-kiosk","text":"2. Order at the self-service kiosk","level":2},{"id":"3-check-where-your-car-is-in-line","text":"3. Check where your car is in line","level":2},{"id":"4-your-member-portal","text":"4. Your member portal","level":2},{"id":"signing-in-whatsapp-one-time-code","text":"Signing in (WhatsApp one-time code)","level":3},{"id":"what-you-can-see-and-do","text":"What you can see and do","level":3},{"id":"5-book-an-appointment","text":"5. Book an appointment","level":2},{"id":"6-understanding-your-membership","text":"6. Understanding your membership","level":2},{"id":"7-chat-with-the-business-on-whatsapp","text":"7. Chat with the business on WhatsApp","level":2},{"id":"8-troubleshooting","text":"8. Troubleshooting","level":2}],"html":"<h1 id=\"customer--user-manual\">Customer — User Manual</h1>\n<p>Welcome! You&#39;re a customer of a car-wash / detailing business that runs on <strong>airin</strong>. You don&#39;t need\nto install an app or remember a password to use most of it — everything below opens in a normal web\nbrowser, usually from a <strong>link or QR code</strong> the business shares (on a poster, receipt, or WhatsApp).</p>\n<p>To see your <strong>membership</strong>, you sign in with a <strong>one-time code</strong> sent to your WhatsApp — no password\nto remember.</p>\n<p>Everything is branded to the business you&#39;re visiting and available in <strong>English or Indonesian</strong>\n(look for the <strong>EN / ID</strong> toggle).</p>\n<hr>\n<h2 id=\"table-of-contents\">Table of contents</h2>\n<ol>\n<li><a href=\"#1-browse-the-price-menu-no-sign-in\">Browse the price menu (no sign-in)</a></li>\n<li><a href=\"#2-order-at-the-self-service-kiosk\">Order at the self-service kiosk</a></li>\n<li><a href=\"#3-check-where-your-car-is-in-line\">Check where your car is in line</a></li>\n<li><a href=\"#4-your-member-portal\">Your member portal</a></li>\n<li><a href=\"#5-book-an-appointment\">Book an appointment</a></li>\n<li><a href=\"#6-understanding-your-membership\">Understanding your membership</a></li>\n<li><a href=\"#7-chat-with-the-business-on-whatsapp\">Chat with the business on WhatsApp</a></li>\n<li><a href=\"#8-troubleshooting\">Troubleshooting</a></li>\n</ol>\n<hr>\n<h2 id=\"1-browse-the-price-menu-no-sign-in\">1. Browse the price menu (no sign-in)</h2>\n<p>Open the business&#39;s <strong>eMenu</strong> link (it looks like <code>/menu/...</code>). You&#39;ll see all their services and\nprices, split into <strong>AIRE · Car Wash</strong> and <strong>LEAD · Detailing &amp; Coating</strong>, plus any add-ons. It&#39;s\njust a price list — nothing to sign in for.</p>\n<p><img src=\"/docs/images/cust-01-menu.png\" alt=\"The price eMenu — services and prices grouped by car wash and detailing.\" loading=\"lazy\" /></p>\n<hr>\n<h2 id=\"2-order-at-the-self-service-kiosk\">2. Order at the self-service kiosk</h2>\n<p>At the branch there may be a <strong>kiosk tablet</strong> (or a QR code that opens the ordering screen). You can\nbook your own wash without waiting for a cashier:</p>\n<p><img src=\"/docs/images/cust-02-kiosk-order.png\" alt=\"The kiosk welcome screen — identify yourself, or continue as a guest.\" loading=\"lazy\" /></p>\n<p><strong>Step by step:</strong></p>\n<ol>\n<li><strong>Identify yourself (optional).</strong> Type your <strong>plate, phone, or membership number</strong>, or tap\n<strong>Scan</strong> to scan your membership QR, then tap <strong>Find me</strong>. If you&#39;re an active member, your member\npricing is applied and your card can show. Or just tap <strong>Continue as guest →</strong>.</li>\n<li><strong>Choose your services.</strong> Out-of-stock items appear greyed out.</li>\n<li><strong>Enter your details</strong> — name, phone, plate, and vehicle.</li>\n<li><strong>Pay:</strong><ul>\n<li><strong>Pay now (QRIS)</strong> — scan the QR with your banking or e-wallet app; the screen confirms once\nyou&#39;ve paid.</li>\n<li><strong>Pay at cashier</strong> — your car is added to the queue and you settle at the counter.</li>\n</ul>\n</li>\n<li><strong>Done</strong> — your car is on the queue.</li>\n</ol>\n<hr>\n<h2 id=\"3-check-where-your-car-is-in-line\">3. Check where your car is in line</h2>\n<p>Two ways to see your position:</p>\n<ul>\n<li><p><strong>Queue status lookup</strong> — open the queue-check link (<code>/kiosk/...</code>), enter your <strong>order number</strong>,\nand tap <strong>Check</strong> to see your position and estimated wait.</p>\n<p><img src=\"/docs/images/cust-03-queue-lookup.png\" alt=\"Queue status lookup — enter your order number to see your position.\" loading=\"lazy\" /></p>\n</li>\n<li><p><strong>Queue board</strong> — the in-store TV screen shows the live queue for everyone in the waiting area.</p>\n<p><img src=\"/docs/images/cust-05-queue-board.png\" alt=\"The in-store queue board (TV display).\" loading=\"lazy\" /></p>\n</li>\n</ul>\n<hr>\n<h2 id=\"4-your-member-portal\">4. Your member portal</h2>\n<p>If you&#39;re a <strong>member</strong>, the portal is your home base. Open the portal link for the business\n(<code>/portal/...</code>).</p>\n<h3 id=\"signing-in-whatsapp-one-time-code\">Signing in (WhatsApp one-time code)</h3>\n<p><img src=\"/docs/images/cust-04-portal-login.png\" alt=\"The member portal sign-in — enter your WhatsApp number to get a code.\" loading=\"lazy\" /></p>\n<ol>\n<li>Enter the <strong>WhatsApp number</strong> registered with your membership.</li>\n<li>Tap <strong>Send code</strong>. You&#39;ll receive a <strong>6-digit code</strong> on WhatsApp (valid for 5 minutes). Enter it.</li>\n<li>You&#39;re signed in for about 2 hours. <em>(For security, wrong codes are limited and you can only\nrequest a new code after a short wait. Your WhatsApp number <strong>is</strong> your login — there&#39;s no\npassword.)</em></li>\n</ol>\n<h3 id=\"what-you-can-see-and-do\">What you can see and do</h3>\n<ul>\n<li><strong>Home</strong> — your membership status, plan, valid-until date, and usage. If your membership is in its\ngrace window or has lapsed, you&#39;ll see a prompt to <strong>renew</strong>.</li>\n<li><strong>Card</strong> — your digital membership card with your number and QR code.</li>\n<li><strong>Vouchers</strong> — vouchers you own (active / used).</li>\n<li><strong>Vehicles</strong> — the plates registered to your membership.</li>\n<li><strong>Menu</strong> — the business&#39;s services, prices, and plans.</li>\n<li><strong>History</strong> — your past visits and orders.</li>\n<li><strong>Queue</strong> — the live queue for a branch you choose; your own car is highlighted.</li>\n<li><strong>Renew</strong> — pick a plan and pay by <strong>QRIS</strong>; your membership updates automatically once paid.</li>\n<li><strong>Book</strong> — request an appointment (see §5).</li>\n</ul>\n<hr>\n<h2 id=\"5-book-an-appointment\">5. Book an appointment</h2>\n<p>From the member portal, tap <strong>Book</strong> and choose a <strong>branch, service, date/time, and your vehicle</strong>.\nThe branch confirms via WhatsApp; once confirmed, your car is placed on the queue for that time.\nYou&#39;ll get a WhatsApp message when it&#39;s <strong>confirmed</strong> (or if it&#39;s declined).</p>\n<hr>\n<h2 id=\"6-understanding-your-membership\">6. Understanding your membership</h2>\n<ul>\n<li>While your membership is <strong>active</strong>, you get your plan&#39;s free/discounted washes <strong>automatically</strong> —\njust identify yourself (plate, phone, number, or card scan) at the counter or kiosk.</li>\n<li>After your end date, there&#39;s a <strong>14-day grace period</strong>: you can still <strong>renew</strong> (which extends your\nmembership), but you <strong>don&#39;t get member benefits during grace</strong>.</li>\n<li>After the grace period, the membership closes and you&#39;d buy a <strong>new</strong> one. Your member number and\nhistory stay with you.</li>\n<li><strong>Renewing always takes payment first</strong>, and your membership is extended the moment the payment\nconfirms. Renew at the counter, or yourself in the portal with <strong>QRIS</strong>.</li>\n</ul>\n<hr>\n<h2 id=\"7-chat-with-the-business-on-whatsapp\">7. Chat with the business on WhatsApp</h2>\n<p>Many businesses let you chat with them on <strong>WhatsApp</strong>. An assistant can answer about <strong>your own</strong>\nmembership status, orders, queue position, vouchers, and bookings — plus general info like prices and\nopening hours. Just message their WhatsApp number as you normally would.</p>\n<p><strong>Things you can ask, for example:</strong></p>\n<ul>\n<li><em>&quot;Is my membership still active?&quot;</em> / <em>&quot;When does my membership expire?&quot;</em></li>\n<li><em>&quot;How much is a full detail for an SUV?&quot;</em> or <em>&quot;What plans do you have?&quot;</em></li>\n<li><em>&quot;Where is my car in the queue?&quot;</em></li>\n<li><em>&quot;Do I have any vouchers left?&quot;</em></li>\n<li><em>&quot;Can I book a wash tomorrow at 10?&quot;</em> — the assistant proposes it; a staff member confirms, and you\nget a WhatsApp message once it&#39;s confirmed.</li>\n</ul>\n<p>It only ever sees <strong>your</strong> information (never other customers&#39; details, and never the business&#39;s\nprivate financials) and will <strong>hand you over to a real person</strong> whenever you ask, or when it can&#39;t\nhelp. If you&#39;d rather talk to a human from the start, just say so.</p>\n<hr>\n<h2 id=\"8-troubleshooting\">8. Troubleshooting</h2>\n<ul>\n<li><strong>No code arrived?</strong> Make sure you entered the WhatsApp number <strong>registered with your membership</strong>,\nwait a few seconds, and check WhatsApp. If it still doesn&#39;t arrive, the business&#39;s WhatsApp may not\nbe connected — ask them at the counter.</li>\n<li><strong>Member pricing didn&#39;t apply?</strong> Your membership may be expired or in grace. Check the portal\n<strong>Home</strong> tab and renew if prompted.</li>\n<li><strong>QR payment didn&#39;t confirm?</strong> Give it a moment. If it still shows unpaid, ask a cashier — they can\ncomplete the payment at the counter.</li>\n<li><strong>Kiosk says &quot;not configured&quot;?</strong> That tablet hasn&#39;t been set up yet — ask a staff member.</li>\n</ul>\n"},{"slug":"tech-architecture","title":"01 · Architecture & Stack","category":"tech","audience":"Technical","blurb":"System overview, stack, topology, integrations.","order":4,"words":1391,"minutes":7,"toc":[{"id":"1-what-airin-is","text":"1. What airin is","level":2},{"id":"2-tech-stack-at-a-glance","text":"2. Tech stack (at a glance)","level":2},{"id":"3-monorepo-layout","text":"3. Monorepo layout","level":2},{"id":"4-service-topology-docker-compose","text":"4. Service topology (Docker Compose)","level":2},{"id":"5-request-path--routing","text":"5. Request path & routing","level":2},{"id":"6-integrations","text":"6. Integrations","level":2},{"id":"payments","text":"Payments","level":3},{"id":"whatsapp-two-distinct-paths","text":"WhatsApp (two distinct paths)","level":3},{"id":"n8n-agent-builder","text":"n8n agent builder","level":3},{"id":"object-storage-minio","text":"Object storage (MinIO)","level":3},{"id":"iot--mqtt","text":"IoT / MQTT","level":3},{"id":"7-deployment-production-vps","text":"7. Deployment (production VPS)","level":2},{"id":"key-environment-variables-see-envexample","text":"Key environment variables (see .env.example)","level":3},{"id":"8-security-posture-summary","text":"8. Security posture (summary)","level":2}],"html":"<h1 id=\"01--architecture--stack\">01 · Architecture &amp; Stack</h1>\n<h2 id=\"1-what-airin-is\">1. What airin is</h2>\n<p>airin is a <strong>multi-tenant SaaS</strong> for car-wash / automotive-service businesses. A single\ndeployment hosts many independent businesses (&quot;tenants&quot;). Each tenant operates:</p>\n<ul>\n<li>Multiple <strong>branches</strong> (outlets), each with two co-located <strong>business units</strong>: <strong>AIRE</strong>\n(car wash) and <strong>LEAD</strong> (detailing/polishing).</li>\n<li><strong>Point of sale</strong>, an <strong>arrival queue</strong>, <strong>memberships</strong>, <strong>vouchers &amp; promotions</strong>,\n<strong>inventory / COGS</strong>, <strong>procurement</strong>, <strong>finance / P&amp;L / settlement</strong>, <strong>HR &amp; payroll</strong>.</li>\n<li><strong>Customer self-service</strong>: public eMenu, self-order kiosk, WhatsApp-OTP member portal,\nqueue-status lookup, and appointment booking.</li>\n<li><strong>AI automation</strong>: an in-app operations co-pilot and a WhatsApp customer agent, with an\noptional drag-and-drop flow builder (n8n).</li>\n</ul>\n<p>All tenant data is isolated. The privilege ladder is\n<code>platform_super_admin</code> → <code>tenant_owner</code> → <code>outlet_admin</code> → <code>cashier</code>.</p>\n<h2 id=\"2-tech-stack-at-a-glance\">2. Tech stack (at a glance)</h2>\n<table>\n<thead>\n<tr>\n<th>Layer</th>\n<th>Technology</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Frontend</td>\n<td><strong>Next.js 15</strong> (App Router) · <strong>React 19</strong> · <strong>Tailwind CSS v4</strong> · lucide-react · zustand (light use) · TypeScript</td>\n</tr>\n<tr>\n<td>Backend API</td>\n<td><strong>NestJS 10 on Express</strong> (migrated off Fastify) · <strong>Socket.IO</strong> · raw <code>pg</code> Pool · TypeScript</td>\n</tr>\n<tr>\n<td>Shared code</td>\n<td><code>@aire/shared</code> workspace package — enums, constants, DTOs, and pure domain logic (cart calc, voucher/membership rules, module registry) shared by front + back</td>\n</tr>\n<tr>\n<td>Database</td>\n<td><strong>PostgreSQL 16</strong> (<code>pgcrypto</code>), Row-Level-Security policies available, plain-SQL migrations</td>\n</tr>\n<tr>\n<td>Cache / sessions</td>\n<td><strong>Redis 7</strong> (refresh-token store, password-protected)</td>\n</tr>\n<tr>\n<td>Object storage</td>\n<td><strong>MinIO</strong> (S3-compatible) — logos, membership-card backgrounds</td>\n</tr>\n<tr>\n<td>Messaging / IoT</td>\n<td><strong>Eclipse Mosquitto</strong> (MQTT) + a Node <strong>IoT gateway</strong> bridging bay sensors</td>\n</tr>\n<tr>\n<td>WhatsApp</td>\n<td><strong>WAHA</strong> (self-host, QR-scan) or <strong>Kapso</strong> (cloud) per tenant</td>\n</tr>\n<tr>\n<td>AI / LLM</td>\n<td><strong>OpenRouter</strong> (tenant key) or <strong>Ollama/Hermes</strong> (self-host), routed per tenant</td>\n</tr>\n<tr>\n<td>Agent builder</td>\n<td><strong>n8n</strong> (hosted, admin-only) + a custom <code>n8n-nodes-aire</code> node calling the AIRE bridge</td>\n</tr>\n<tr>\n<td>Reverse proxy</td>\n<td><strong>nginx</strong> (TLS, gzip, rate-limits, WebSocket upgrade)</td>\n</tr>\n<tr>\n<td>Infra</td>\n<td><strong>Docker Compose</strong></td>\n</tr>\n<tr>\n<td>Testing</td>\n<td>Vitest + Testing Library + <strong>fast-check</strong> (property-based)</td>\n</tr>\n</tbody></table>\n<h2 id=\"3-monorepo-layout\">3. Monorepo layout</h2>\n<pre><code>aire/\n├── apps/\n│   ├── backend/      # NestJS-on-Express API (port 4000) — 40 feature modules\n│   ├── frontend/     # Next.js web app (port 3000) — dashboard, POS, kiosk, portal, admin\n│   └── iot-gateway/  # MQTT → WebSocket bay-sensor bridge (port 4002)\n├── packages/\n│   └── shared/       # @aire/shared — enums, constants, DTOs, pure domain logic\n├── database/\n│   ├── migrations/   # 001…040 ordered plain-SQL migrations\n│   ├── migrate.ts    # runner (schema_migrations tracking)\n│   └── seed*.ts/mjs  # demo seed + users\n├── integrations/\n│   └── n8n-nodes-aire/  # custom n8n community node (AIRE bridge)\n├── infrastructure/   # nginx, mosquitto configs, ssl\n└── docker-compose.yml\n</code></pre>\n<blockquote>\n<p><strong>Note:</strong> the working clone keeps the app one level deep at <code>aire/aire/</code>. Earlier docs and\nthe root README mention an <code>ai-service</code> app and &quot;NestJS + Fastify&quot; — both are <strong>outdated</strong>:\nthere is no separate AI service (AI lives inside the backend <code>agent</code>/<code>whatsapp</code> modules), and\nthe backend now runs on <strong>Express</strong>, not Fastify.</p>\n</blockquote>\n<h2 id=\"4-service-topology-docker-compose\">4. Service topology (Docker Compose)</h2>\n<p>All ports bind to <code>127.0.0.1</code> (loopback only) except the frontend; everything shares the\n<code>aire-network</code> bridge. nginx is the only public entry point in production.</p>\n<pre><code>                          Internet\n                             │\n                     ┌───────▼────────┐   :80/:443\n                     │     nginx      │   TLS, gzip, rate-limit, WS upgrade\n                     └───┬───────┬────┘\n             /  , /_next │       │ /api , /socket.io , /api/iot\n                 ┌───────▼──┐ ┌──▼──────────┐\n                 │ frontend │ │   backend   │  (Express + Socket.IO)\n                 │  :3000   │ │    :4000    │\n                 └──────────┘ └──┬───┬───┬──┘\n                                 │   │   │\n     ┌──────────┬──────────┬─────┘   │   └─────────┬───────────┐\n ┌───▼───┐  ┌───▼───┐  ┌───▼────┐ ┌──▼───┐    ┌────▼───┐   ┌────▼────┐\n │postgres│ │ redis │  │ minio  │ │ waha │    │  n8n   │   │mosquitto│\n │ :5432  │ │ :6379 │  │:9000/1 │ │:3001 │    │ :5678  │   │ :1883   │\n └────────┘ └───────┘  └────────┘ └──────┘    └────────┘   └────┬────┘\n                                                                │ MQTT\n                                                          ┌─────▼──────┐\n                                                          │iot-gateway │ :4002\n                                                          └────────────┘\n</code></pre>\n<table>\n<thead>\n<tr>\n<th>Service</th>\n<th>Image</th>\n<th>Internal port</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>postgres</code></td>\n<td>postgres:16-alpine</td>\n<td>5432</td>\n<td>Primary database (vol <code>postgres_data</code>)</td>\n</tr>\n<tr>\n<td><code>redis</code></td>\n<td>redis:7-alpine</td>\n<td>6379</td>\n<td>Refresh-token / reset-token store, cache</td>\n</tr>\n<tr>\n<td><code>minio</code></td>\n<td>minio/minio</td>\n<td>9000 API / 9001 console</td>\n<td>Object storage, bucket <code>aire-storage</code></td>\n</tr>\n<tr>\n<td><code>mosquitto</code></td>\n<td>eclipse-mosquitto:2</td>\n<td>1883 / 9883</td>\n<td>MQTT broker for IoT bay controllers</td>\n</tr>\n<tr>\n<td><code>backend</code></td>\n<td>apps/backend</td>\n<td>4000</td>\n<td>REST API + Socket.IO</td>\n</tr>\n<tr>\n<td><code>frontend</code></td>\n<td>apps/frontend</td>\n<td>3000</td>\n<td>Next.js web app</td>\n</tr>\n<tr>\n<td><code>iot-gateway</code></td>\n<td>apps/iot-gateway</td>\n<td>4002</td>\n<td>MQTT↔WebSocket bay-sensor bridge</td>\n</tr>\n<tr>\n<td><code>waha</code></td>\n<td>devlikeapro/waha</td>\n<td>3000 (→3001)</td>\n<td>WhatsApp gateway (per WAHA-tenant)</td>\n</tr>\n<tr>\n<td><code>n8n</code></td>\n<td>n8nio/n8n</td>\n<td>5678</td>\n<td>Hosted agent-flow builder (admin only)</td>\n</tr>\n<tr>\n<td><code>nginx</code></td>\n<td>nginx:alpine</td>\n<td>80 (→8090 dev)</td>\n<td>Reverse proxy</td>\n</tr>\n</tbody></table>\n<h2 id=\"5-request-path--routing\">5. Request path &amp; routing</h2>\n<ul>\n<li>Browser → <strong>nginx</strong> → <code>frontend</code> (<code>/</code>, <code>/_next/static</code>) or <code>backend</code> (<code>/api/*</code>,\n<code>/socket.io/*</code>, <code>/api/iot/*</code>).</li>\n<li>The frontend calls the API at <code>NEXT_PUBLIC_API_URL</code> (default <code>/api</code>, rewritten to the backend).</li>\n<li>nginx applies rate limits: <code>api</code> zone 30 r/s, <code>auth</code> zone 5 r/s (stricter on <code>/api/auth/</code>),\n<code>client_max_body_size 50m</code>, and WebSocket upgrade with 7-day timeouts for <code>/socket.io/</code>.</li>\n<li><strong>Real-time:</strong> two Socket.IO namespaces — root <code>/</code> (order/bay/queue/payment/notification\nevents, rooms <code>outlet:&lt;id&gt;</code> and <code>queue-board:&lt;id&gt;</code>) and <code>/agent</code> (AI proposal events,\nroom <code>tenant:&lt;id&gt;</code>).</li>\n</ul>\n<h2 id=\"6-integrations\">6. Integrations</h2>\n<h3 id=\"payments\">Payments</h3>\n<p>A single gateway abstraction (<code>PaymentProvider</code>) with <strong>Xendit / Midtrans / Stripe / Sandbox</strong>\nimplementations. Config is <strong>per tenant</strong> (<code>tenants.settings.payment</code>) with an env fallback.\nA <strong>sandbox key <code>&quot;mock&quot;</code></strong> runs the full dynamic-QRIS flow against the real DB but auto-confirms\nthe charge after a short delay — no real gateway needed for demos. Webhooks are signature-verified\nper provider and funnel into one <code>confirmPaymentByReference</code> path that flips an order\n<code>ordered → paid</code>. See <a href=\"/docs/tech-backend#payment\">02 · Backend §Payment</a>.</p>\n<h3 id=\"whatsapp-two-distinct-paths\">WhatsApp (two distinct paths)</h3>\n<ol>\n<li><strong>Conversational agent</strong> — <code>WhatsappService</code> talks to <strong>WAHA</strong> (self-host, connect by QR)\nor <strong>Kapso</strong> (cloud) using the tenant&#39;s <code>agent_configs</code>. Inbound webhook →\n<code>handleInbound</code> → built-in runtime <strong>or</strong> n8n flow (see below) → reply.</li>\n<li><strong>Business-API notifications</strong> — <code>NotificationService</code> sends templated messages\n(membership welcome, voucher delivery, expiry reminders, queue completion) via the WhatsApp\nBusiness API, with tenant creds and a global fallback.</li>\n</ol>\n<h3 id=\"n8n-agent-builder\">n8n agent builder</h3>\n<p>The <strong>platform super-admin</strong> builds drag-and-drop flows in a hosted n8n and publishes them to\nthe <code>agent_flows</code> catalog. A <strong>tenant</strong> selects a flow, flips <code>routing_mode</code> to <code>n8n</code>, and mints\na <strong>bridge token</strong>. On an inbound WhatsApp message the backend posts to the flow&#39;s webhook; the\nflow calls back into the <strong>AIRE bridge</strong> (<code>/api/bridge/{context,llm,tool,whatsapp/send}</code>), which\nre-applies every server-side guardrail — so a visual flow can never widen data scope. Any n8n\nfailure falls back to the built-in runtime. See <a href=\"/docs/tech-n8n-agent-builder\">n8n-agent-builder.md</a>.</p>\n<h3 id=\"object-storage-minio\">Object storage (MinIO)</h3>\n<p>Branding logos and membership-card backgrounds are stored as S3 objects (keys\n<code>tenants/&lt;id&gt;/logo</code>, <code>tenants/&lt;id&gt;/card-bg</code>). Only a short content-hash version is kept in\nsettings; images are served through versioned, cache-immutable public streaming endpoints.</p>\n<h3 id=\"iot--mqtt\">IoT / MQTT</h3>\n<p>The <code>iot-gateway</code> subscribes to bay-sensor topics\n<code>aire/{tenant}/{outlet}/bay/{bay}/sensor</code>, validates readings (vehicle present, water flow,\nfoam level, machine status), and is designed to forward <code>bay:status-changed</code> events to the\nbackend Socket.IO. Bay gate/wash commands are published back on <code>.../command</code>. The sensor→UI\nbroadcast and gate MQTT publish are currently scaffolded stubs pending hardware.</p>\n<h2 id=\"7-deployment-production-vps\">7. Deployment (production VPS)</h2>\n<ul>\n<li>Single dedicated VPS, Docker Compose, project name <code>aire</code>, served at\n<strong><code>app.useairin.id</code></strong> by nginx (80→443 redirect, Let&#39;s Encrypt TLS). n8n is exposed under\n<code>…/flows/</code> via an nginx subpath.</li>\n<li>The deploy overlays three compose files: <code>docker-compose.yml</code> +\n<code>docker-compose.prod.yml</code> (127.0.0.1 bindings + cert mounts) + <code>docker-compose.n8n.yml</code>\n(n8n override). All non-nginx ports are loopback-bound.</li>\n<li>Migrations are applied with <code>database/migrate.ts</code> (or <code>psql</code> for out-of-band files) and\ntracked in <code>schema_migrations</code>. There are <strong>no down-migrations</strong> — rollback is a git reset +\nrebuild.</li>\n</ul>\n<h3 id=\"key-environment-variables-see-envexample\">Key environment variables (see <code>.env.example</code>)</h3>\n<p><code>JWT_SECRET</code>, <code>POSTGRES_PASSWORD</code>, <code>REDIS_PASSWORD</code>, <code>MINIO_ROOT_*</code>, <code>SETTINGS_ENCRYPTION_KEY</code>\n(32-byte hex, encrypts tenant secrets), <code>PAYMENT_PROVIDER</code> + gateway keys, <code>WAHA_URL</code> /\n<code>WAHA_API_KEY</code>, <code>KAPSO_URL</code>, <code>N8N_ENCRYPTION_KEY</code>, <code>BRIDGE_CALLBACK_BASE</code>,\n<code>NEXT_PUBLIC_API_URL</code>, <code>NEXT_PUBLIC_N8N_URL</code>.</p>\n<h2 id=\"8-security-posture-summary\">8. Security posture (summary)</h2>\n<ul>\n<li><strong>Tenant isolation</strong> is enforced primarily by explicit <code>WHERE tenant_id = $</code> predicates in\nevery query; RLS policies (migration 003) exist and are used by the settings module via\n<code>RlsContextGuard</code>, but most modules rely on query-level scoping. See\n<a href=\"/docs/tech-backend#2-authentication-roles--multi-tenancy\">02 · Backend §Auth</a>.</li>\n<li><strong>Secrets</strong> (LLM key, WhatsApp token) are encrypted at rest; gateway secrets are never\nreturned to the client (masked).</li>\n<li><strong>Customer AI data isolation:</strong> the WhatsApp agent resolves the customer server-side from the\ninbound phone number and can only ever read that customer&#39;s own data + public info — never\nother customers or financials, even under prompt injection.</li>\n<li><strong>Passwords</strong> are bcrypt (cost 10). Access tokens live 15 min; refresh tokens 7 days with\nrotation in Redis.</content></li>\n</ul>\n"},{"slug":"tech-backend","title":"02 · Backend — Stack & Flows","category":"tech","audience":"Technical","blurb":"NestJS modules, auth, multi-tenancy, core flows.","order":5,"words":2832,"minutes":14,"toc":[{"id":"1-module-map","text":"1. Module map","level":2},{"id":"2-authentication-roles--multi-tenancy","text":"2. Authentication, roles & multi-tenancy","level":2},{"id":"roles--hierarchy","text":"Roles & hierarchy","level":3},{"id":"jwt","text":"JWT","level":3},{"id":"guards","text":"Guards","level":3},{"id":"multi-tenancy-enforcement","text":"Multi-tenancy enforcement","level":3},{"id":"login--register--reset","text":"Login / register / reset","level":3},{"id":"3-pos--order-flows","text":"3. POS & order flows","level":2},{"id":"order-creation--orderservicecreateorder","text":"Order creation — OrderService.createOrder()","level":3},{"id":"payment--orderservicepayorder-and-gateway-path","text":"Payment — OrderService.payOrder() and gateway path","level":3},{"id":"shifts--shift-module","text":"Shifts — shift module","level":3},{"id":"vehicle-queue--the-operational-board","text":"Vehicle queue — the operational board","level":3},{"id":"interface-aware-out-of-stock-block","text":"Interface-aware out-of-stock block","level":3},{"id":"4-membership-vouchers-portal--kiosk","text":"4. Membership, vouchers, portal & kiosk","level":2},{"id":"5-inventory-cogs--finance","text":"5. Inventory, COGS & finance","level":2},{"id":"cogs-engine","text":"COGS engine","level":3},{"id":"stock-opname-physical-count","text":"Stock opname (physical count)","level":3},{"id":"reports--finance","text":"Reports & finance","level":3},{"id":"procurement","text":"Procurement","level":3},{"id":"hr--payroll","text":"HR & payroll","level":3},{"id":"6-ai-stack","text":"6. AI stack","level":2},{"id":"in-app-operations-co-pilot-agent-module","text":"In-app operations co-pilot (agent module)","level":3},{"id":"whatsapp-customer-agent-whatsapp-module","text":"WhatsApp customer agent (whatsapp module)","level":3},{"id":"n8n-bridge-agent-bridge-module","text":"n8n bridge (agent-bridge module)","level":3},{"id":"7-platform-config--supporting-modules","text":"7. Platform, config & supporting modules","level":2}],"html":"<h1 id=\"02--backend--stack--flows\">02 · Backend — Stack &amp; Flows</h1>\n<p>The backend is a <strong>NestJS 10 application running on Express</strong> (migrated off Fastify). It is a\nmodular monolith: ~40 feature modules under <code>apps/backend/src/modules</code>, each a NestJS module\nwith its own controller(s) + service(s). All database access is raw SQL through a single <code>pg</code>\n<code>Pool</code> injected as <code>DATABASE_POOL</code>. Framework entry: <code>apps/backend/src/main.ts</code> (ExpressAdapter,\n<code>useBodyParser(&#39;json&#39;, { limit: &#39;10mb&#39; })</code> — branding/card images travel as base64 JSON).</p>\n<ul>\n<li>Base path for all HTTP routes: <strong><code>/api</code></strong>.</li>\n<li>Real-time via <strong>Socket.IO</strong> (namespaces <code>/</code> and <code>/agent</code>).</li>\n<li>Shared types/enums/constants from <code>@aire/shared</code>.</li>\n</ul>\n<hr>\n<h2 id=\"1-module-map\">1. Module map</h2>\n<table>\n<thead>\n<tr>\n<th>Domain</th>\n<th>Modules</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Identity &amp; access</strong></td>\n<td><code>auth</code>, <code>access</code> (RBAC users/roles/permissions), <code>tenant</code>, <code>outlet</code></td>\n</tr>\n<tr>\n<td><strong>POS &amp; commerce</strong></td>\n<td><code>order</code>, <code>payment</code>, <code>payment-method</code>, <code>service</code>, <code>catalog</code>, <code>shift</code>, <code>vehicle-queue</code>, <code>vehicle-catalog</code>, <code>receipt</code> (invoices)</td>\n</tr>\n<tr>\n<td><strong>Membership &amp; customers</strong></td>\n<td><code>membership</code>, <code>membership-card</code>, <code>customer</code>, <code>voucher</code>, <code>voucher-ticket</code>, <code>promotion</code>, <code>booking</code>, <code>settlement</code>, <code>sales</code></td>\n</tr>\n<tr>\n<td><strong>Self-service</strong></td>\n<td><code>kiosk</code>, <code>portal</code></td>\n</tr>\n<tr>\n<td><strong>Inventory / COGS / finance</strong></td>\n<td><code>inventory</code>, <code>recipe</code> (COGS/opname/reports), <code>procurement</code>, <code>finance</code></td>\n</tr>\n<tr>\n<td><strong>People</strong></td>\n<td><code>hr</code>, <code>payroll</code> (in the hr module tree)</td>\n</tr>\n<tr>\n<td><strong>Reporting</strong></td>\n<td><code>report</code>, <code>monitoring</code>, <code>audit</code></td>\n</tr>\n<tr>\n<td><strong>AI</strong></td>\n<td><code>agent</code> (co-pilot), <code>whatsapp</code>, <code>agent-bridge</code> (n8n), <code>agent-config</code>, <code>agent-registry</code>, <code>ai</code> (legacy stub)</td>\n</tr>\n<tr>\n<td><strong>Platform / config</strong></td>\n<td><code>admin</code>, <code>branding</code>, <code>settings</code>, <code>tenant-modules</code>, <code>storage</code></td>\n</tr>\n<tr>\n<td><strong>IoT / hardware</strong></td>\n<td><code>bay</code>, <code>cctv</code>, <code>discovery</code>, <code>realtime</code>, <code>notification</code></td>\n</tr>\n</tbody></table>\n<hr>\n<h2 id=\"2-authentication-roles--multi-tenancy\">2. Authentication, roles &amp; multi-tenancy</h2>\n<h3 id=\"roles--hierarchy\">Roles &amp; hierarchy</h3>\n<p>Four base roles, privilege-ordered (<code>packages/shared/src/enums.ts</code>, <code>constants.ts</code>):</p>\n<table>\n<thead>\n<tr>\n<th>Role</th>\n<th>Level</th>\n<th>Scope</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>platform_super_admin</code></td>\n<td>4</td>\n<td>The whole platform, all tenants (<code>outlet_id</code> null)</td>\n</tr>\n<tr>\n<td><code>tenant_owner</code></td>\n<td>3</td>\n<td>One tenant, all its branches (<code>outlet_id</code> null)</td>\n</tr>\n<tr>\n<td><code>outlet_admin</code></td>\n<td>2</td>\n<td>Branch(es) they&#39;re placed in</td>\n</tr>\n<tr>\n<td><code>cashier</code></td>\n<td>1</td>\n<td>Branch(es) they&#39;re placed in</td>\n</tr>\n</tbody></table>\n<p><code>@Roles(X)</code> on a route means <strong>&quot;role X or higher.&quot;</strong> So <code>@Roles(OutletAdmin)</code> also admits owner\nand super-admin. <code>OUTLET_SCOPED_ROLES = [outlet_admin, cashier]</code> carry a mandatory <code>outlet_id</code>;\nhigher roles are tenant-wide. Tenants also define <strong>custom roles</strong> (<code>roles</code> table) each mapped to\na base role + a permission set (RBAC via the <code>access</code> module).</p>\n<h3 id=\"jwt\">JWT</h3>\n<ul>\n<li><strong>Access token</strong> (15 min): claims <code>sub</code> (user id), <code>tenant_id</code>, <code>outlet_id</code> (or null),\n<code>role</code>, <code>iat</code>, <code>exp</code>. Claim names are snake_case; there is <strong>no <code>typ</code></strong> on staff tokens.</li>\n<li><strong>Refresh token</strong> (7 days): <code>{ sub, tid, type:&#39;refresh&#39; }</code>, backed by a Redis key\n<code>refresh:&lt;userId&gt;:&lt;tid&gt;</code>; <strong>rotated</strong> (old key deleted) on each use.</li>\n<li><strong>Customer portal token</strong> (2 h): <code>{ sub: customerId, tenant_id, typ:&#39;customer&#39; }</code> — a separate\nnamespace; <code>PortalGuard</code> requires <code>typ===&#39;customer&#39;</code>, so staff and customer tokens can never\ncross surfaces.</li>\n<li><strong>Kiosk</strong> uses no JWT — an opaque per-device token (<code>kiosk_devices.token</code>) via header\n<code>x-kiosk-token</code> or <code>?kioskToken=</code>.</li>\n<li><strong>Bridge (n8n)</strong> uses a per-tenant <code>bridge_token</code> via header <code>X-Aire-Bridge-Token</code>.</li>\n</ul>\n<h3 id=\"guards\">Guards</h3>\n<ul>\n<li><code>JwtAuthGuard</code> — validates the Bearer access token, attaches <code>request.user</code>.</li>\n<li><code>RolesGuard</code> — reads <code>@Roles()</code>; <strong>no decorator ⇒ allow any authenticated user</strong>. Enforces the\nhierarchy and, for outlet-scoped roles, blocks a request whose target <code>outletId</code> differs from\nthe user&#39;s own outlet.</li>\n<li><code>RlsContextGuard</code> — opens a dedicated connection, <code>SET LOCAL app.tenant_id/outlet_id/role</code>,\nattaches it as <code>request.dbClient</code> (used by the <code>settings</code> and <code>discovery</code> modules).</li>\n<li><code>PortalGuard</code>, <code>KioskTokenGuard</code>, <code>BridgeTokenGuard</code> — the three non-JWT auth guards above.</li>\n</ul>\n<h3 id=\"multi-tenancy-enforcement\">Multi-tenancy enforcement</h3>\n<p>Two mechanisms coexist:</p>\n<ol>\n<li><strong>Explicit predicates (dominant):</strong> every service query includes <code>AND tenant_id = $</code>. This is\nthe primary isolation mechanism for POS, orders, shifts, inventory, memberships, etc.</li>\n<li><strong>Branch scoping via <code>ScopeService.resolveOutletIds(user, requestedOutletId)</code>:</strong> owners/super\nsee all branches (or a requested one); outlet-scoped roles are intersected with their assigned\noutlets (home outlet ∪ scheduled branches ∪ JWT outlet). Contract: <code>null</code> = all, <code>[]</code> = none,\n<code>[ids]</code> = restricted. Used by finance, inventory, report, customer list, bookings.</li>\n</ol>\n<blockquote>\n<p><strong>Hardening applied (2026-07-11):</strong> three isolation gaps found during the documentation trace are\nnow fixed. (1) <code>GET /api/orders</code> now always applies a <code>tenant_id</code> predicate — <code>OrderQueryParams</code>\ncarries a required <code>tenantId</code> and <code>OrderListService.buildWhereClause</code> emits <code>o.tenant_id = $1</code>\nbefore any other filter, so an owner/super-admin with no <code>outletId</code> filter can no longer list\nacross tenants. (2) <code>RlsContextGuard</code> now sets the RLS session GUCs with <strong>bound parameters</strong>\n(<code>SELECT set_config(&#39;app.tenant_id&#39;, $1, true)</code>) instead of interpolating JWT values into a\n<code>SET LOCAL &#39;…&#39;</code> string, closing the injection vector. (3) The <code>customer</code> controller&#39;s\nsearch / profile / analytics routes previously carried a <code>@Roles()</code> decorator with <strong>no guard\nattached</strong> (making it inert — the routes were effectively unauthenticated) and their service\nqueries had <strong>no <code>tenant_id</code> predicate</strong> — together a cross-tenant customer-PII leak. The\ncontroller now has a class-level <code>@UseGuards(JwtAuthGuard, RolesGuard)</code> (<code>@Roles(OutletAdmin)</code>\nper route) and <code>getProfile</code> / <code>getAnalytics</code> / <code>searchCustomers</code> are tenant-scoped.</p>\n</blockquote>\n<h3 id=\"login--register--reset\">Login / register / reset</h3>\n<ul>\n<li><strong>Login</strong> (<code>POST /api/auth/login</code>): email normalized (trim+lowercase), inactive users rejected,\nbcrypt compare, returns <code>{ accessToken, refreshToken, user }</code>. Generic error (no enumeration).</li>\n<li><strong>Register</strong> (<code>POST /api/auth/register</code>): self-service tenant signup — creates <code>tenants</code> +\na <code>tenant_owner</code> user in one transaction, seeds default automation settings, assigns a global\n<strong>tenant code</strong> (6-char base-36) after commit, and auto-logs-in.</li>\n<li><strong>Reset</strong>: <code>forgot-password</code> stores a UUID token in Redis (30-min TTL, returned in the response\n— no email channel wired); <code>reset-password</code> consumes it and bcrypt-hashes the new password.</li>\n<li><strong>Impersonation</strong>: a super-admin can mint a token acting as a tenant&#39;s earliest owner\n(audited); used by the admin panel &quot;impersonate&quot; button.</li>\n</ul>\n<hr>\n<h2 id=\"3-pos--order-flows\">3. POS &amp; order flows</h2>\n<h3 id=\"order-creation--orderservicecreateorder\">Order creation — <code>OrderService.createOrder()</code></h3>\n<p>Runs a single transaction. Steps:</p>\n<ol>\n<li>Look up services (price, <code>is_main_service</code>, business unit). One receipt may mix AIRE + LEAD\nlines; the order&#39;s <code>business_unit</code> records the payment channel.</li>\n<li>Validate via shared <code>validateOrder</code> (injects membership plates when <code>membershipId</code> is set).</li>\n<li><strong>Membership pricing</strong> — only when <code>getMembershipBenefits</code> finds a membership that is\n<code>status=&#39;active&#39; AND end_date &gt;= CURRENT_DATE</code>. Date-expired-but-stale rows grant nothing.\nCaptures <code>homeOutletId</code> + <code>settlementAmount</code> for cross-branch settlement.</li>\n<li><strong>Shift attachment (branch inheritance)</strong> — uses the caller&#39;s provided shift (kiosk/branch)\nor the cashier&#39;s own open shift. <strong>No open shift → 400 &quot;Open a shift before taking orders.&quot;</strong>\nThe order&#39;s operating outlet comes from the shift, so finance always matches where cash lands.</li>\n<li>Resolve <strong>vouchers</strong> (pack child codes + shareable digital tickets) and <strong>promotions</strong>\n(active, within date, under quota) read-only.</li>\n<li>Read outlet config (<code>service_charge_pct</code>, <code>tax_pct</code>); compute cart summary (subtotal, service\ncharge, tax, total) via shared logic.</li>\n<li>Generate <code>order_number</code> (<code>ORD-YYYYMMDD-NNN</code> per outlet/day).</li>\n<li>Insert <code>orders</code> (<code>status=&#39;ordered&#39;</code>, <code>channel</code> = pos/kiosk/customer, <code>shift_id</code>), <code>order_items</code>\n(flag member-priced lines), and an initial <code>order_status_logs</code> row.</li>\n<li><strong>Atomic redemption</strong> — single-use <code>UPDATE voucher_codes … WHERE status=&#39;active&#39;</code> (rollback if\nconcurrently consumed); promotion grants + quota decrement; membership usage + cross-branch\n<code>settlement_entries</code>.</li>\n<li><strong>COGS deduction</strong> (<code>applyRecipeCogs</code>) — runs inside the same transaction (see §5).</li>\n<li><strong>Queue link</strong> — if <code>queueEntryId</code> is passed, back-link <code>vehicle_queue.order_id</code>.</li>\n<li>COMMIT, then emit <code>OrderCreated</code>, assign customer tags (best-effort).</li>\n</ol>\n<h3 id=\"payment--orderservicepayorder-and-gateway-path\">Payment — <code>OrderService.payOrder()</code> and gateway path</h3>\n<ul>\n<li><strong>Counter payment</strong> (<code>POST /api/orders/:id/pay</code>): only from <code>status=&#39;ordered&#39;</code>. Cash requires\n<code>amountReceived ≥ total</code> and computes change. <strong>Shift re-stamp:</strong> the paying cashier&#39;s open\nshift is re-resolved and stamped onto the order (<code>shift_id = COALESCE(payShift, shift_id)</code>), so\na kiosk-created order collected at the counter is booked into the right drawer. Sets\n<code>status=&#39;paid&#39;, paid_at=NOW()</code>, emits <code>OrderPaid</code>.</li>\n<li><strong>Dynamic QRIS</strong> (<code>POST /api/payments/charge/:orderId</code>): leaves the order <code>ordered</code>, stores a\n<code>payment_reference</code>, returns a QR string. A gateway webhook — or, for a sandbox <code>&quot;mock&quot;</code> key, a\ntimed auto-confirm — calls <code>confirmPaymentByReference</code>, flipping <code>ordered → paid</code>. (The gateway\npath does not re-stamp the shift.)</li>\n<li><strong>Webhooks</strong>: <code>/api/payments/webhook/{xendit,midtrans,stripe}</code> (public, signature-verified) →\n<code>confirmPaymentByReference</code>.</li>\n<li><strong>Void/cancel</strong> (<code>DELETE /api/orders/:id</code>, OutletAdmin+): blocked when the order&#39;s shift is\nclosed (day-lock); <strong>restocks</strong> recipe inventory idempotently (see §5); audited.</li>\n</ul>\n<h3 id=\"shifts--shift-module\">Shifts — <code>shift</code> module</h3>\n<ul>\n<li><strong>Open</strong> (<code>POST /api/shifts/open</code>): one open shift per operator. An <strong>attendance gate</strong> checks\ntoday&#39;s <code>employee_schedules</code>; opening off-schedule (or with no schedule) requires a reason once,\nand is audit-logged. Records <code>opening_float</code>.</li>\n<li><strong>Close</strong> (<code>POST /api/shifts/:id/close</code>): <code>expected = openingFloat + cashSales + pettyIn − pettyOut</code>; <code>variance = counted − expected</code>. A closed shift <strong>day-locks</strong> its orders (no\nedit/cancel). Also <code>petty-cash</code> and <code>issues</code> sub-endpoints.</li>\n<li><code>resolveBranchShift(tenant, outlet)</code> is the single seam kiosk/branch orders use to attach to the\nbranch&#39;s earliest open shift (multi-cashier ready).</li>\n</ul>\n<h3 id=\"vehicle-queue--the-operational-board\">Vehicle queue — the operational board</h3>\n<p>Two orthogonal dimensions on <code>vehicle_queue</code>:</p>\n<ul>\n<li><strong>Service status</strong> — <code>waiting → serving → done</code> (or <code>cancelled</code>), set on the board.</li>\n<li><strong>Payment status</strong> — <strong>derived</strong> from the linked order (no duplicated field): no order or unpaid\norder = <code>unpaid</code>; order in <code>paid/confirmed/completed</code> = <code>paid</code>.</li>\n</ul>\n<p>Flow: a car arrives (<code>POST /api/vehicle-queue</code>, position = max+1) with plate/brand/model, no order\nneeded. The cashier picks it in POS (&quot;Proses Bayar&quot;) → the order is created with <code>queueEntryId</code> →\n<code>vehicle_queue.order_id</code> is back-linked. Marking a car <strong><code>done</code> requires the linked order to be\npaid</strong> (guarded: <em>&quot;Collect payment before marking this car done.&quot;</em>). Kiosk self-orders instead\ninsert a fresh queue row already carrying the order id.</p>\n<h3 id=\"interface-aware-out-of-stock-block\">Interface-aware out-of-stock block</h3>\n<p>Customer-facing channels block products whose <strong>recipe can&#39;t be fulfilled from current stock</strong>;\nthe <strong>POS is intentionally not gated</strong> (a cashier can always ring up a sale — stock may go\nnegative, allow-and-alert). <code>KioskService.getOutOfStockServiceIds</code> computes, per service, whether\nany recipe component (unit-converted) exceeds the item&#39;s current quantity; the kiosk order create\nrejects blocked lines and the public eMenu greys them out.</p>\n<hr>\n<h2 id=\"4-membership-vouchers-portal--kiosk\">4. Membership, vouchers, portal &amp; kiosk</h2>\n<p>Membership is documented end-to-end in <a href=\"/docs/tech-membership-lifecycle\">06 · Membership</a>. Key backend\nfacts:</p>\n<ul>\n<li><strong>Statuses:</strong> <code>pending → active → grace (H+1..H+14) → revoked (H+15+)</code>, plus manual <code>suspended</code>\nand terminal <code>cancelled</code>. Canonical status comes from <code>MembershipLifecycleService.derive()</code> on\nevery read; a job (<code>runTransitions</code>, boot + every 6 h, no <code>@nestjs/schedule</code>) writes the same\nvalues and appends <code>membership_events</code>.</li>\n<li><strong>Benefits guard:</strong> granted only for <code>status=&#39;active&#39; AND end_date &gt;= CURRENT_DATE</code>.</li>\n<li><strong>Identity:</strong> a 12-char base-36 membership number = tenant(6) + branch(2) + customer(4),\nallocated lazily at activation and reused across renewals.</li>\n<li><strong>Renewal:</strong> <code>renew</code> creates a fee order + a <strong>pending <code>membership_renewals</code></strong> row; the\nmembership is extended/created only by <code>apply-renewal</code> <strong>after</strong> the order is paid (idempotent).\nActive/grace of the same plan → extend from current expiry; revoked or different plan → new.</li>\n<li><strong>Settlement:</strong> a cross-branch membership wash writes a <code>settlement_entries</code> row (home branch\nowes serving branch); the <code>settlement</code> module nets and pays these out.</li>\n</ul>\n<p><strong>Vouchers:</strong> sellable <strong>packs</strong> (<code>voucher_packs</code> parent + hashed child <code>voucher_codes</code>, WhatsApp\ndelivered) and shareable <strong>digital tickets</strong> (<code>voucher_tickets</code>, human codes <code>BRANCH-MMYYYY-NNNNNN</code>\nfrom <code>voucher_counters</code>). Both are validated read-only in POS and redeemed atomically inside the\norder transaction. <strong>Promotions</strong> apply fixed/percentage discounts or grant free product/voucher/\nfuture-discount under an optional quota.</p>\n<p><strong>Customer portal</strong> (<code>portal</code> module): WhatsApp-OTP login (6-digit, sha256-hashed, 5-min expiry,\n30-s resend cooldown, 5-attempt cap, no phone-enumeration leak) → 2 h customer JWT. Endpoints:\n<code>me</code> (full account), <code>orders</code>, <code>branches</code>, <code>queue</code> (sanitized, flags the customer&#39;s own plates),\n<code>plans</code>, <code>renew</code> + <code>renew/status</code> (online QRIS renewal reusing the staff renewal machinery via a\nsynthesized system operator), and <code>bookings</code>. A portal booking sends the <strong>branch cashier</strong> a\none-tap WhatsApp confirm/reject link (<code>/confirm-booking/&lt;token&gt;</code>, public, unguessable token);\nconfirming creates a <code>vehicle_queue</code> entry and notifies the customer.</p>\n<p><strong>Kiosk</strong> (<code>kiosk</code> module): device-token auth; public eMenu (<code>/api/kiosk/menu</code>, annotates\n<code>available</code> per stock) + queue-status lookup; and token-guarded <code>identify</code>\n(plate → phone → number → UUID), self-order (<code>channel=&#39;kiosk&#39;</code>, reuses <code>OrderService.createOrder</code>\nvia a synthesized login-disabled Kiosk operator, requires an open branch shift), pay-now QRIS, or\npay-at-cashier.</p>\n<hr>\n<h2 id=\"5-inventory-cogs--finance\">5. Inventory, COGS &amp; finance</h2>\n<h3 id=\"cogs-engine\">COGS engine</h3>\n<p>A &quot;product&quot; is a <code>services</code> row (there is no products table). Its cost is:</p>\n<ul>\n<li><strong>Physical recipe / BOM</strong> (<code>service_recipe_components</code>): inventory items consumed per one unit,\nin a stated unit.</li>\n<li><strong>Non-physical cost components</strong> (<code>service_cost_components</code> → <code>cost_component_types</code>): <code>fixed</code>\namount or <code>percentage</code> of price (tax, profit, water, electricity…).</li>\n<li><strong>UOM conversions</strong> (<code>uom_conversions</code>): buy/stock in one unit, consume in another\n(e.g. kg ↔ g).</li>\n</ul>\n<p>On sale, <code>applyRecipeCogs</code> (inside the <code>createOrder</code> transaction) explodes each line&#39;s BOM,\nunit-converts to the item&#39;s stock unit, <strong>deducts inventory</strong> + writes a <code>sale</code> movement, adds\nnon-physical overhead, and <strong>freezes <code>order_items.cost_snapshot</code></strong> so margin reports don&#39;t drift\nwhen a recipe later changes. On cancel, <code>deleteOrder</code> restocks by reversing the <code>sale</code> movements\ninto <code>sale_return</code> movements — guarded by status so repeated cancels never double-restock.</p>\n<h3 id=\"stock-opname-physical-count\">Stock opname (physical count)</h3>\n<p><code>create</code> snapshots current book stock as <code>expected_qty</code>; staff enter <code>counted_qty</code>; <code>close</code>\ncomputes <code>variance = counted − expected</code> and <code>variance_value</code>, reconciles\n<code>inventory_items.quantity = counted</code>, and writes <code>adjustment</code> movements. Uncounted lines are\nskipped.</p>\n<h3 id=\"reports--finance\">Reports &amp; finance</h3>\n<ul>\n<li><strong>COGS P&amp;L</strong> (<code>/api/cogs/pnl</code>): revenue − COGS (from <code>cost_snapshot</code>) − expenses ⇒ gross profit,\ngross margin %, net profit. Plus per-product margin and inventory variance (from a closed\nopname).</li>\n<li><strong>Simple finance summary</strong> (<code>/api/finance/summary</code>): revenue − expenses only (<strong>no COGS</strong>), by\ncategory, with branch scoping.</li>\n<li><strong>Sales summary/forecast</strong> (<code>/api/sales/summary</code>): month actual vs <code>sales_targets</code>; run-rate\nprojection <code>projected = actual / dayOfMonth * daysInMonth</code>; attainment % + projected attainment\n%; lead funnel.</li>\n<li><strong>Report module</strong> (<code>/api/reports/*</code>): KPIs, revenue/customer series, daily sales, per-shift cash\nreconciliation, and CSV / branded-PDF export.</li>\n</ul>\n<h3 id=\"procurement\">Procurement</h3>\n<p>Suppliers + purchase orders (<code>PO-YYYYMMDD-####</code>). <code>receivePurchaseOrder</code> marks the PO received and\n<strong>auto-restocks</strong> each linked item via the shared <code>InventoryService.adjustStock</code> <code>in</code> primitive\n(so movements + low-stock alerts fire). Idempotent via the already-received guard.</p>\n<h3 id=\"hr--payroll\">HR &amp; payroll</h3>\n<p>Employees (optionally linked 1:1 to a login account), schedules, attendance (clock in/out with\nhours), leave (paid/unpaid), holidays. <strong>Payroll</strong> generation is transactional and idempotent per\nperiod (a draft run is reversed and regenerated; a finalized run is locked): base salary + pending\nbonuses − deductions − advances − loan installments − unpaid-leave deduction ⇒ one payslip per\nemployee. Export is <strong>CSV only</strong> (PDF lives in the report module).</p>\n<hr>\n<h2 id=\"6-ai-stack\">6. AI stack</h2>\n<p>Two AI surfaces share strict, server-side data isolation.</p>\n<h3 id=\"in-app-operations-co-pilot-agent-module\">In-app operations co-pilot (<code>agent</code> module)</h3>\n<ul>\n<li>A <strong>tool registry</strong> of read tools (business summary, list orders/customers/memberships/services,\nqueue status, events, plus module read summaries) and <strong>gated action tools</strong> (create campaign,\nretention offer, queue-priority, anomaly flag, pricing suggestion, membership recommendation,\nand module actions like adjust-stock / record-expense / create-lead / create-PO / add-employee).</li>\n<li><strong>Execution gate</strong> (<code>AgentService.executeTool</code>): tool exists → tenant/outlet present → AJV input\nvalidation → read-only tools bypass gating → the relevant <strong>automation toggle</strong> must be enabled →\napproval mode: <code>autonomous</code> executes (+audit) or <code>approval_required</code> creates an\n<code>action_proposals</code> row for owner sign-off. Retries with backoff; every call recorded to\n<code>agent_invocations</code>.</li>\n<li><strong>Chat assistant</strong> (<code>/api/agent/chat</code>): a max-5-iteration tool-calling loop where the LLM emits\nJSON actions routed through the same gate.</li>\n<li><strong>Scheduled analysis</strong>: an in-memory scheduler runs enabled-toggle analyses, gathers a live data\nsnapshot, asks the LLM for insights, and executes or proposes each.</li>\n<li><strong>LLM routing</strong> (<code>LLMRouterService</code>): per-tenant <strong>OpenRouter</strong> (encrypted key, default\n<code>gpt-4o-mini</code>) or <strong>Hermes/Ollama</strong>; 30-s timeout; structured error types.</li>\n</ul>\n<h3 id=\"whatsapp-customer-agent-whatsapp-module\">WhatsApp customer agent (<code>whatsapp</code> module)</h3>\n<p><code>handleInbound</code>: resolve tenant → upsert conversation + store message → gate on\n<code>ai_reply_enabled</code> + per-conversation <code>ai_enabled</code> + a per-user daily cap → <strong>route</strong>:</p>\n<ul>\n<li><code>routing_mode=&#39;n8n&#39;</code> → POST the message to the selected flow&#39;s webhook (with bridge token +\ncallback base); n8n calls back via the bridge. Any failure <strong>falls back</strong> to the built-in\nruntime.</li>\n<li>Built-in <code>AgentRuntimeService</code>: detect intent (human/status/membership/price/booking/voucher/\nhours/greeting/unknown), pick a persona from the <code>agents</code> registry, then <strong>Fluid</strong> (LLM with a\nheavily guard-railed system prompt) or <strong>Rigid</strong> (deterministic Indonesian templates); fluid\nerrors fall back to rigid. <code>human</code> intent always escalates to the human <code>escalation_number</code>.</li>\n<li><strong>Data isolation:</strong> <code>CustomerContextService</code> resolves the customer from the inbound phone\nserver-side and exposes only that customer&#39;s memberships/orders/queue/vouchers/bookings + public\ninfo. No method returns other customers, financials, payroll, or cross-tenant data.</li>\n</ul>\n<h3 id=\"n8n-bridge-agent-bridge-module\">n8n bridge (<code>agent-bridge</code> module)</h3>\n<p>Machine-auth (<code>BridgeTokenGuard</code>) endpoints <code>/api/bridge/{context, llm, tool, whatsapp/send}</code> —\nall tenant-scoped so guardrails stay server-side. The <code>agent-flow</code> service owns the super-admin\nflow catalog (<code>agent_flows</code>) and each tenant&#39;s selection + bridge-token rotation.</p>\n<blockquote>\n<p><strong>Legacy note:</strong> the <code>ai</code> module (<code>/api/ai/query</code>, <code>/api/ai/chatbot/webhook</code>) and its\n<code>callLLM</code>/chatbot are older <strong>stubs</strong>; the production AI path is <code>agent</code> + <code>whatsapp</code> +\n<code>agent-bridge</code> + <code>LLMRouterService</code>. <code>agent_invocations</code> is the real telemetry.</p>\n</blockquote>\n<hr>\n<h2 id=\"7-platform-config--supporting-modules\">7. Platform, config &amp; supporting modules</h2>\n<ul>\n<li><strong><code>admin</code></strong> — platform control plane (platform-super-admin): tenant CRUD (assigns tenant code),\nsuspend/reactivate, per-tenant module toggles, impersonation; <strong>subscription plans</strong>\n(<code>PlatformPlanService</code>, <code>platform_plans</code> table → priced MRR, monthly-equivalent for annual);\nplatform config (default plans, feature flags); metrics (overview, enriched tenants, tenant\ndetail, activity, timeseries, AI usage, ops monitoring); and health — DB latency + live WAHA\nreachability plus a <strong>Docker</strong> panel (<code>DockerService</code> reads container status/logs over a\nread-only <code>/var/run/docker.sock</code> mount; degrades gracefully when absent). Tenant <code>:id</code> route\nparams accept a <strong>slug or UUID</strong> (<code>resolveTenantId</code>). (A second, plainer tenant CRUD lives in the\n<code>tenant</code> module — note it does <strong>not</strong> assign a tenant code.)</li>\n<li><strong><code>branding</code></strong> — per-tenant company name, logo (MinIO object + versioned public stream), colors,\nfonts, dark-mode policy. <code>GET /api/public/branding</code> is unauthenticated and returns a default for\nunknown tenants (never 404).</li>\n<li><strong><code>settings</code></strong> — per-tenant automation settings (AI enable, LLM provider + encrypted key,\nautomation toggles, approval modes, WhatsApp creds), JSON-Schema-validated, secrets encrypted,\naudited.</li>\n<li><strong><code>tenant-modules</code></strong> — <code>GET /api/modules/me</code> returns the enabled-module map (default-on).</li>\n<li><strong><code>storage</code></strong> — S3/MinIO client + image upload/stream utilities.</li>\n<li><strong><code>audit</code></strong> — <code>audit_logs</code> writer + <code>GET /api/audit-logs</code>; covers login, role change, void,\nplate ops, config change, PIN usage, membership/voucher events, impersonation, device confirms.</li>\n<li><strong><code>notification</code></strong> — WhatsApp Business-API templated messages (tenant creds + global fallback);\nin-memory retry queue (BullMQ intended in production).</li>\n<li><strong><code>realtime</code></strong> — Socket.IO root namespace emitters (order/bay/queue/payment/notification).</li>\n<li><strong><code>bay</code> / <code>discovery</code> / <code>cctv</code></strong> — wash-bay status/assignment/gate, network device discovery\n(ONVIF/MQTT/SSDP), and CCTV stream/record. Hardware-facing parts are stubs pending\ninfrastructure.</li>\n</ul>\n<p>See the complete endpoint list in <a href=\"/docs/tech-api-reference\">05 · API Reference</a>.\n</content></p>\n"},{"slug":"tech-frontend","title":"03 · Frontend — Stack & Flows","category":"tech","audience":"Technical","blurb":"Next.js routing, state, API client, i18n and theming.","order":6,"words":1985,"minutes":10,"toc":[{"id":"1-tech-stack","text":"1. Tech stack","level":2},{"id":"structure-src","text":"Structure (src/)","level":3},{"id":"2-api-client-auth--session","text":"2. API client, auth & session","level":2},{"id":"contexts","text":"Contexts","level":3},{"id":"module--role-gating","text":"Module & role gating","level":3},{"id":"3-route-map","text":"3. Route map","level":2},{"id":"public--unauthenticated","text":"Public / unauthenticated","level":3},{"id":"authenticated","text":"Authenticated","level":3},{"id":"dashboard-pages-module-gated","text":"/dashboard/* pages (module-gated)","level":3},{"id":"admin-pages-platform-super-admin-only","text":"/admin/* pages (platform-super-admin only)","level":3},{"id":"4-key-ui-flows","text":"4. Key UI flows","level":2},{"id":"pos-new-order-posoutletagentidnew-order","text":"POS new order (/pos/[outletAgentId]/new-order)","level":3},{"id":"packs-on-the-new-order-screen-the-retired-sell-pack-route","text":"Packs on the New Order screen (the retired /sell-pack route)","level":3},{"id":"reports-dashboardreports","text":"Reports (/dashboard/reports)","level":3},{"id":"theme","text":"Theme","level":3},{"id":"kiosk-self-order-kiosktenantidorder","text":"Kiosk self-order (/kiosk/[tenantId]/order)","level":3},{"id":"customer-portal-portaltenantid","text":"Customer portal (/portal/[tenantId])","level":3},{"id":"dashboard-login--hub--nav","text":"Dashboard login → hub → nav","level":3},{"id":"5-role--module-gating-summary","text":"5. Role × module gating (summary)","level":2}],"html":"<h1 id=\"03--frontend--stack--flows\">03 · Frontend — Stack &amp; Flows</h1>\n<p>The frontend is a <strong>Next.js 15 (App Router)</strong> app in <code>apps/frontend</code>, React 19, Tailwind CSS v4.\nIt is the single web client for every surface: the management <strong>dashboard</strong>, the <strong>POS</strong>, the\n<strong>platform admin</strong> panel, and the public <strong>kiosk / portal / eMenu / queue board</strong>.</p>\n<hr>\n<h2 id=\"1-tech-stack\">1. Tech stack</h2>\n<ul>\n<li><strong>Next.js <code>^15.5</code> (App Router)</strong> + <strong>React 19</strong>.</li>\n<li><strong>Tailwind CSS v4</strong> via <code>@tailwindcss/postcss</code>. Styling = utility classes + a set of semantic\ncomponent classes (<code>.card</code>, <code>.btn-primary</code>, <code>.input-field</code>, <code>.badge</code>, …) and CSS\ncustom-property design tokens (<code>bg-surface</code>, <code>text-text-primary</code>, <code>border-border</code>,\n<code>bg-primary-500</code>, …) driven by branding variables in <code>globals.css</code>. <strong>No shadcn/ui / Radix</strong> —\nUI is hand-rolled; icons via <strong>lucide-react</strong>; <code>clsx</code> + <code>tailwind-merge</code> for class composition.</li>\n<li><strong>State:</strong> mostly local <code>useState</code>/<code>useEffect</code> + React Context; <code>zustand</code> is a dependency used\nsparingly. Cross-cutting state is Context-based (branding, theme, language).</li>\n<li><strong>Extra libs:</strong> <code>html5-qrcode</code> (camera scan), <code>jsbarcode</code> + <code>qrcode</code> (membership-card codes).</li>\n<li><code>@aire/shared</code> provides the same cart/voucher/membership calculations the backend uses, so POS\ntotals match server totals.</li>\n<li><strong>Testing:</strong> Vitest + Testing Library + fast-check; test files colocated (<code>*.test.tsx</code>).</li>\n</ul>\n<h3 id=\"structure-src\">Structure (<code>src/</code>)</h3>\n<ul>\n<li><code>app/</code> — App Router route groups (see §3). Root <code>layout.tsx</code> loads fonts and wraps everything in\n<code>LanguageProvider</code>.</li>\n<li><code>components/</code> — feature-grouped: <code>pos/</code>, <code>dashboard/</code>, <code>branding/</code>, <code>admin/</code>, <code>shared/</code>, plus\n<code>QrScanButton.tsx</code>.</li>\n<li><code>lib/</code> — <code>api.ts</code> (authed client), <code>portalApi.ts</code>, <code>auth.ts</code> (session), <code>useModules.ts</code>,\n<code>i18n.tsx</code> + <code>locales/{en,id}.ts</code>, <code>publicBranding.ts</code>, <code>color-utils.ts</code>, <code>google-fonts.ts</code>,\n<code>cardCodes.ts</code>, <code>theme.ts</code>, <code>contrast.ts</code>, <code>utils.ts</code>.</li>\n<li><code>contexts/</code> — <code>BrandingContext.tsx</code>, <code>ThemeContext.tsx</code>.</li>\n</ul>\n<hr>\n<h2 id=\"2-api-client-auth--session\">2. API client, auth &amp; session</h2>\n<ul>\n<li><strong>Base URL:</strong> <code>NEXT_PUBLIC_API_URL || &#39;/api&#39;</code>.</li>\n<li><strong><code>lib/api.ts</code></strong> — <code>apiFetch</code> prepends the base, sets JSON content-type (skipped for FormData so\nthe browser sets the multipart boundary), attaches <code>Authorization: Bearer &lt;accessToken&gt;</code>. On\n<strong>401</strong> it calls <code>POST /auth/refresh</code> with the stored refresh token, re-stores the session, and\nretries once; on failure it clears the session and redirects to <code>/</code>. Exposes\n<code>api.get/post/put/patch/delete/upload</code>; throws a typed <code>ApiError</code>.</li>\n<li><strong><code>lib/auth.ts</code></strong> — session in <code>localStorage</code> (<code>aire_access_token</code>, <code>aire_refresh_token</code>,\n<code>aire_user</code>). <code>AuthUser.role</code> ∈ the four roles + <code>tenantId</code>/<code>outletId</code>. Includes\n<strong>impersonation</strong> helpers (backs up the admin session, swaps in a tenant token).</li>\n<li><strong>Guarding:</strong> there is <strong>no server middleware</strong> — each protected page/layout calls\n<code>isAuthenticated()</code> in an effect and hard-redirects to <code>/</code> if missing. Deeper enforcement is\nserver-side (role guards + query scoping). Login routes <strong>cashiers → POS</strong>, everyone else →\n<strong><code>/hub</code></strong>.</li>\n</ul>\n<h3 id=\"contexts\">Contexts</h3>\n<ul>\n<li><strong><code>BrandingContext</code></strong> (authed dashboard) — fetches <code>GET /branding/me</code>, applies brand colors,\nexposes <code>companyName</code>, <code>logoUrl</code>, <code>tenantCode</code>, <code>refreshBranding</code>. Public surfaces use\n<code>usePublicBranding(tenantId)</code> → <code>GET /public/branding?tenantId=</code> (no auth) applying colors +\nGoogle fonts.</li>\n<li><strong><code>ThemeContext</code></strong> — light/dark with a tenant policy (<code>dark_mode_enabled</code>, <code>forced_theme</code>,\n<code>default_theme</code>); persists <code>aire-theme</code>.</li>\n<li><strong><code>LanguageProvider</code></strong> (<code>lib/i18n.tsx</code>) — <code>useI18n()</code> + <code>t(key, fallback)</code>, locales <code>en</code>/<code>id</code>\n(flat dicts, EN → inline fallback), persisted in <code>aire_lang</code>. A <code>&lt;LanguageToggle/&gt;</code> sits in the\ndashboard, POS, portal, kiosk, and confirm-booking headers. The whole app is bilingual EN/ID.</li>\n</ul>\n<h3 id=\"module--role-gating\">Module &amp; role gating</h3>\n<ul>\n<li><strong><code>lib/useModules.ts</code></strong> — <code>useTenantModules()</code> fetches <code>GET /modules/me</code>. <strong>Default-on:</strong> a\nmodule is hidden only if its flag is explicitly <code>false</code>, so a backend hiccup never hides tools.\nKeys (from <code>@aire/shared</code>): <code>analytics, crm, memberships, vouchers, promotions, catalog, inventory, finance, hr, ai_assistant, whatsapp</code>. Core areas (Hub, Overview, Users, Settings,\nPayment Gateway) are always shown.</li>\n<li><strong>Dashboard nav</strong> is filtered by <strong>module flags</strong> (not by role). <strong>Role gating</strong> is concentrated\nin the <strong>admin</strong> area and a couple of spots (see §5).</li>\n</ul>\n<hr>\n<h2 id=\"3-route-map\">3. Route map</h2>\n<h3 id=\"public--unauthenticated\">Public / unauthenticated</h3>\n<table>\n<thead>\n<tr>\n<th>Route</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>/</code></td>\n<td>Login (email/password + one-click demo accounts + public links)</td>\n</tr>\n<tr>\n<td><code>/register</code></td>\n<td>Business/owner self-signup → <code>/hub</code></td>\n</tr>\n<tr>\n<td><code>/reset-password</code></td>\n<td>Request reset token, then set new password</td>\n</tr>\n<tr>\n<td><code>/menu/[tenantId]</code></td>\n<td>Public eMenu (services + plans), no login</td>\n</tr>\n<tr>\n<td><code>/kiosk/[tenantId]</code></td>\n<td>Public queue-status lookup by order number</td>\n</tr>\n<tr>\n<td><code>/kiosk/[tenantId]/order</code></td>\n<td>Self-service ordering (device-token authorized)</td>\n</tr>\n<tr>\n<td><code>/portal/[tenantId]</code></td>\n<td>Customer member portal (WhatsApp-OTP)</td>\n</tr>\n<tr>\n<td><code>/confirm-booking/[token]</code></td>\n<td>Cashier confirms/rejects a portal booking (unguessable token)</td>\n</tr>\n</tbody></table>\n<h3 id=\"authenticated\">Authenticated</h3>\n<table>\n<thead>\n<tr>\n<th>Route group</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>/hub</code></td>\n<td>Post-login launcher (Dashboard / POS / Kiosk tiles + Platform-Admin tile for super/owner)</td>\n</tr>\n<tr>\n<td><code>/dashboard/*</code></td>\n<td>Management (see table below)</td>\n</tr>\n<tr>\n<td><code>/pos/[outletAgentId]/*</code></td>\n<td>Point of sale (tabs: New Order, Orders, Queue, Summary, Shift)</td>\n</tr>\n<tr>\n<td><code>/queue-board/[outletId]</code></td>\n<td>Full-screen TV queue display</td>\n</tr>\n<tr>\n<td><code>/admin/*</code></td>\n<td>Platform admin (platform-super-admin only)</td>\n</tr>\n</tbody></table>\n<h3 id=\"dashboard-pages-module-gated\"><code>/dashboard/*</code> pages (module-gated)</h3>\n<table>\n<thead>\n<tr>\n<th>Page</th>\n<th>What the user does</th>\n<th>Module</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Overview (<code>/dashboard</code>)</td>\n<td>KPIs, month revenue forecast vs target, AI proposals, quick links</td>\n<td>core</td>\n</tr>\n<tr>\n<td><code>transactions</code></td>\n<td>Charts + orders table (view/edit/void) + Excel/PDF export</td>\n<td>analytics</td>\n</tr>\n<tr>\n<td><code>invoices</code></td>\n<td>List paid orders; print A4 invoice PDF</td>\n<td>analytics</td>\n</tr>\n<tr>\n<td><code>reports</code></td>\n<td>Consolidated metrics + PDF/CSV export</td>\n<td>analytics</td>\n</tr>\n<tr>\n<td><code>sales</code></td>\n<td>Attainment vs target, set target, manage leads</td>\n<td>analytics</td>\n</tr>\n<tr>\n<td><code>crm</code></td>\n<td>All customers (members + non-members) with growth chart; per-row member badge; Edit/Delete. Member management moved to <code>memberships</code> → Members</td>\n<td>crm</td>\n</tr>\n<tr>\n<td><code>bookings</code></td>\n<td>Create/edit appointments, confirm/done</td>\n<td>crm</td>\n</tr>\n<tr>\n<td><code>memberships</code></td>\n<td>Tabbed: <strong>Plans</strong> (CRUD), <strong>Members</strong> (list → detail: card, history, renew/suspend), <strong>Cards</strong> (card designer)</td>\n<td>memberships</td>\n</tr>\n<tr>\n<td><code>membership-card</code></td>\n<td>Standalone card designer (same component as the Memberships → Cards tab; no longer in the nav)</td>\n<td>memberships</td>\n</tr>\n<tr>\n<td><code>vouchers</code></td>\n<td>Voucher-pack templates; sell/issue code packs</td>\n<td>vouchers</td>\n</tr>\n<tr>\n<td><code>promotions</code></td>\n<td>CRUD promotions (reward, quota, dates, scope)</td>\n<td>promotions</td>\n</tr>\n<tr>\n<td><code>branches</code></td>\n<td>CRUD outlets</td>\n<td>catalog</td>\n</tr>\n<tr>\n<td><code>services</code></td>\n<td>Service/product menu + per-product recipe/BOM &amp; cost components</td>\n<td>catalog</td>\n</tr>\n<tr>\n<td><code>catalog</code></td>\n<td>Product categories &amp; brands</td>\n<td>catalog</td>\n</tr>\n<tr>\n<td><code>payment-methods</code></td>\n<td>Per-branch POS payment buttons</td>\n<td>catalog</td>\n</tr>\n<tr>\n<td><code>kiosks</code></td>\n<td>Provision kiosk device tokens, copy launch URL, enable/disable</td>\n<td>catalog</td>\n</tr>\n<tr>\n<td><code>vehicles</code></td>\n<td>Vehicle brand/type catalog for POS dropdowns</td>\n<td>catalog</td>\n</tr>\n<tr>\n<td><code>inventory</code></td>\n<td>Stock items, adjust in/out, unit conversions</td>\n<td>inventory</td>\n</tr>\n<tr>\n<td><code>procurement</code></td>\n<td>Suppliers, POs, receive</td>\n<td>inventory</td>\n</tr>\n<tr>\n<td><code>opname</code></td>\n<td>Stock counts → close → reconcile &amp; record variance</td>\n<td>inventory</td>\n</tr>\n<tr>\n<td><code>finance</code></td>\n<td>Revenue/expense/net + forecast, record expenses</td>\n<td>finance</td>\n</tr>\n<tr>\n<td><code>cogs</code></td>\n<td>P&amp;L (revenue − COGS − expenses), product margin, variance</td>\n<td>finance</td>\n</tr>\n<tr>\n<td><code>settlement</code></td>\n<td>Inter-branch owed amounts; settle/payout</td>\n<td>finance</td>\n</tr>\n<tr>\n<td><code>hr</code></td>\n<td>Employees, schedules, leave, holidays, clock in/out</td>\n<td>hr</td>\n</tr>\n<tr>\n<td><code>payroll</code></td>\n<td>Generate/finalize runs, adjustments, loans, CSV payslips</td>\n<td>hr</td>\n</tr>\n<tr>\n<td><code>assistant</code></td>\n<td>Chat with the tenant LLM co-pilot (tool access)</td>\n<td>ai_assistant</td>\n</tr>\n<tr>\n<td><code>agents</code></td>\n<td>AI agent personas + flow routing (built-in vs n8n)</td>\n<td>ai_assistant</td>\n</tr>\n<tr>\n<td><code>ai-agent</code></td>\n<td>Configure the WhatsApp AI agent (connect WAHA/Kapso, prompt, knowledge)</td>\n<td>whatsapp</td>\n</tr>\n<tr>\n<td><code>conversations</code></td>\n<td>Live customer↔AI WhatsApp log (toggle AI, manual reply)</td>\n<td>whatsapp</td>\n</tr>\n<tr>\n<td><code>monitoring</code></td>\n<td>Real-time AI usage (invocations/errors/tokens)</td>\n<td>whatsapp</td>\n</tr>\n<tr>\n<td><code>users</code></td>\n<td>Users (base + custom role, multi-branch), custom roles</td>\n<td>core</td>\n</tr>\n<tr>\n<td><code>payment-settings</code></td>\n<td>Per-tenant payment gateway config</td>\n<td>core</td>\n</tr>\n<tr>\n<td><code>settings</code></td>\n<td>Tenant identity (read-only code), branding, WhatsApp, AI, device discovery</td>\n<td>core</td>\n</tr>\n</tbody></table>\n<h3 id=\"admin-pages-platform-super-admin-only\"><code>/admin/*</code> pages (platform-super-admin only)</h3>\n<p><code>admin</code> (overview) · <code>tenants</code> (list/create/edit/suspend; rows link by <strong>slug</strong>, e.g.\n<code>/admin/tenants/airin-demo</code>) · <code>tenants/[id]</code> (detail, add branches, toggle modules, <strong>impersonate</strong>;\nthe <code>[id]</code> segment accepts a slug or UUID, resolved server-side) · <code>monitoring</code> · <code>ai-usage</code> ·\n<code>agent-flows</code> · <code>health</code> (DB/WAHA + Docker container list &amp; logs) · <code>plans</code> (subscription plans) ·\n<code>billing</code> · <code>config</code> · <code>support</code>. Tenant owners run their business from <code>/dashboard/*</code> instead\n(branch management is <code>/dashboard/branches</code>).</p>\n<hr>\n<h2 id=\"4-key-ui-flows\">4. Key UI flows</h2>\n<h3 id=\"pos-new-order-posoutletagentidnew-order\">POS new order (<code>/pos/[outletAgentId]/new-order</code>)</h3>\n<ol>\n<li><strong>Auth + shift gate</strong> — loads branch context and the current shift. The operating branch is\nfixed by the operator&#39;s open shift; no open shift ⇒ an amber banner and Place Order disabled.</li>\n<li><strong>Catalog</strong> — services (branch-priced) + payment methods; an AIRE/LEAD business-unit switch\nfilters the grid (both share one cart); brand→type datalists.</li>\n<li><strong>Order from queue</strong> — a picker (or <code>?queueId=…</code> deep link from the Queue tab) prefills\nplate/brand/model/name/phone and carries the <code>queueEntryId</code>.</li>\n<li><strong>Member detect</strong> — a present plate auto-calls <code>/members/lookup?plate=</code>; &quot;Find member&quot; accepts\na 12-char number, phone, or plate. Member pricing (<code>membershipId</code>) attaches <strong>only for a truly\nactive membership</strong>; a soft-pop alert covers expiring-soon / grace / revoked / suspended with a\n&quot;Renew now&quot; CTA that starts the renewal in place.</li>\n<li><strong>Vouchers</strong> — validated against cart + subtotal; valid codes added as removable chips.</li>\n<li><strong>Place order</strong> → <code>POST /orders</code> (returns computed totals).</li>\n<li><strong>Payment</strong> — method buttons; cash shows change; <strong>dynamic QRIS</strong> renders a QR and polls\n<code>GET /orders/:id</code> every 3 s until <code>paid</code>; success shows a receipt; state resets for the next\norder.</li>\n</ol>\n<h3 id=\"packs-on-the-new-order-screen-the-retired-sell-pack-route\">Packs on the New Order screen (the retired <code>/sell-pack</code> route)</h3>\n<p>There is no separate Sell Pack page: <code>PackCatalog</code> is a second tab of the New Order catalog, and a\nselected pack is sent as <code>membershipPlanId</code> / <code>voucherPackTemplateId</code> on <code>POST /orders</code>, so the\nwash and the plan settle as <strong>one order and one payment</strong> (migration 089 made a pack an ordinary\n<code>order_items</code> row). Selling a plan alongside a wash zeroes the <code>car_wash</code> lines server-side — the\ncounter upsell — while the plan line keeps the sale visible in the product mix.</p>\n<p>After payment, <code>runPostPaymentSteps</code> finishes whatever the pack still needs:\n<strong>new membership</strong> → <code>PlateRegistrationModal</code> → <code>POST /memberships/:id/activate</code> (first plate\npre-filled from the order); <strong>voucher pack</strong> → <code>POST /voucher-packs/issue</code> → <code>VoucherCodesModal</code>\n(codes shown once, WhatsApp delivered); <strong>renewal</strong> → <code>POST /memberships/apply-renewal</code>.\nRenewal and member management (plates / cancel) are reached from <strong>Find member</strong> in the order\npanel.</p>\n<h3 id=\"reports-dashboardreports\">Reports (<code>/dashboard/reports</code>)</h3>\n<p>Four tabs sharing one filter bar (date range, business unit, branch): <strong>Reports</strong>\n(summary KPIs + shifts), <strong>Daily operations</strong>, <strong>Sales per agent</strong>, and the\n<strong>Report Designer</strong>. The two operational tabs rebuild the spreadsheets the\noutlet keeps by hand — <code>GET /reports/daily-operations</code> (revenue per payment rail\n× business unit, then volume / member split / items by category / memberships\nnew vs renewed by plan length / voucher packs) and <code>GET /reports/agent-performance</code>\n(item × salesperson matrix). Both pivot whatever keys the API returns rather than\nassuming fixed columns, and both export CSV client-side.</p>\n<h3 id=\"theme\">Theme</h3>\n<p><code>ThemeProvider</code> (contexts/ThemeContext.tsx) resolves: tenant <code>forced_theme</code> when\ndark mode is disabled, else the visitor&#39;s stored choice, else the tenant&#39;s\n<code>default_theme</code>. Only an explicit toggle writes <code>aire-theme</code> — reconciling on\nmount does NOT, so changing a tenant&#39;s default actually reaches existing\nvisitors. The tenant default is mirrored to <code>aire-theme-default</code> for the root\nlayout&#39;s pre-paint script, so a dark-default tenant paints dark on first frame.\n<code>components/shared/ThemeToggle.tsx</code> is the single toggle used by the login page,\nhub, admin shell, dashboard sidebar/header and POS nav.</p>\n<h3 id=\"kiosk-self-order-kiosktenantidorder\">Kiosk self-order (<code>/kiosk/[tenantId]/order</code>)</h3>\n<p>Device-authorized (<code>?kioskToken=</code> → <code>x-kiosk-token</code>). Steps <strong>identify → products → details →\npay → done</strong>: optional identify (plate/phone/number or QR scan) prefills + attaches active\nmembership pricing + can show the member&#39;s card; product grid over the public menu with\nout-of-stock items disabled; <strong>Pay now (QRIS)</strong> (poll status) or <strong>Pay at cashier</strong> (drops the car\non the queue unpaid).</p>\n<h3 id=\"customer-portal-portaltenantid\">Customer portal (<code>/portal/[tenantId]</code>)</h3>\n<p>WhatsApp-OTP login (token per tenant in localStorage). Tabs: <strong>Home</strong> (membership summary, grace/\nrevoked renew prompt), <strong>Card</strong> (rendered membership card), <strong>Vouchers</strong>, <strong>Vehicles</strong>, <strong>Menu</strong>,\n<strong>History</strong>, <strong>Queue</strong> (live, polled, highlights &quot;You&quot;), <strong>Renew</strong> (QRIS, polls until applied),\n<strong>Book</strong> (request appointment → branch confirms via WhatsApp before it joins the queue).</p>\n<h3 id=\"dashboard-login--hub--nav\">Dashboard login → hub → nav</h3>\n<p>Login → session stored → cashier to POS, others to <code>/hub</code> → entering <code>/dashboard</code> mounts\n<code>BrandingProvider → ThemeGate → DashboardShell</code>, re-checks auth, loads modules, and renders the\ngrouped sidebar with module-disabled items filtered out.</p>\n<hr>\n<h2 id=\"5-role--module-gating-summary\">5. Role × module gating (summary)</h2>\n<ul>\n<li><strong>Module flags</strong> gate the <strong>dashboard sidebar only</strong> (default-on).</li>\n<li><strong>Role gating</strong> (client-side; server RLS/guards are the real enforcement):<ul>\n<li><strong>Admin panel</strong> — <code>platform_super_admin</code> only (tenant owners are redirected to the Hub).</li>\n<li><strong>Hub</strong> — Platform-Admin tile only for super-admin.</li>\n<li><strong>Memberships → Members</strong> — membership renew/suspend/reactivate buttons require outlet_admin+\n(client-side check; backend guards are the real enforcement). CRM is now customers-only.</li>\n<li><strong>POS</strong> — guarded by auth only (no role check); the real gate on ringing up orders is an open\nshift, not a role.</content></li>\n</ul>\n</li>\n</ul>\n"},{"slug":"tech-database","title":"04 · Database — Stack, Model & Flow","category":"tech","audience":"Technical","blurb":"Postgres schema, migrations, tenancy model, enums.","order":7,"words":1713,"minutes":9,"toc":[{"id":"1-stack","text":"1. Stack","level":2},{"id":"2-migration-system","text":"2. Migration system","level":2},{"id":"seeding-dev","text":"Seeding (dev)","level":3},{"id":"3-tenancy--row-level-security","text":"3. Tenancy & Row-Level Security","level":2},{"id":"4-data-model-by-domain","text":"4. Data model by domain","level":2},{"id":"foundation--saas","text":"Foundation / SaaS","level":3},{"id":"catalog--commerce","text":"Catalog / Commerce","level":3},{"id":"membership","text":"Membership","level":3},{"id":"queue--kiosk--bookings","text":"Queue / Kiosk / Bookings","level":3},{"id":"inventory--cogs--procurement","text":"Inventory / COGS / Procurement","level":3},{"id":"shifts--hr--payroll","text":"Shifts / HR / Payroll","level":3},{"id":"ai--agents","text":"AI / Agents","level":3},{"id":"portal","text":"Portal","level":3},{"id":"5-notable-data-flow-facts","text":"5. Notable data-flow facts","level":2},{"id":"6-aireshared-shared-domain-package","text":"6. @aire/shared (shared domain package)","level":2}],"html":"<h1 id=\"04--database--stack-model--flow\">04 · Database — Stack, Model &amp; Flow</h1>\n<h2 id=\"1-stack\">1. Stack</h2>\n<ul>\n<li><strong>PostgreSQL 16</strong> (<code>postgres:16-alpine</code>), extension <code>pgcrypto</code> (for <code>gen_random_uuid()</code>).</li>\n<li>Accessed from the backend as a raw <code>pg</code> <code>Pool</code> (<code>DATABASE_POOL</code>); no ORM. Every query is\nhand-written SQL with explicit <code>tenant_id</code> predicates.</li>\n<li>Money is stored as <code>NUMERIC</code>/<code>DECIMAL</code>; timestamps are <code>TIMESTAMPTZ</code> (app TZ <code>Asia/Jakarta</code>).</li>\n</ul>\n<h2 id=\"2-migration-system\">2. Migration system</h2>\n<ul>\n<li>Plain-SQL files in <code>database/migrations/</code>, <code>001_…</code> … <code>040_…</code>, applied in <strong>lexicographic\nfilename order</strong> by <code>database/migrate.ts</code>.</li>\n<li>Applied versions are tracked in a <code>schema_migrations (version, filename, applied_at)</code> table.\n<code>version</code> = filename minus <code>.sql</code>.</li>\n<li>Each file manages its own <code>BEGIN/COMMIT</code>; later migrations lean on idempotent\n<code>IF NOT EXISTS</code> / <code>ADD COLUMN IF NOT EXISTS</code>.</li>\n<li><strong>No down-migrations</strong> (<code>--rollback</code> is not implemented). Rollback in production = git reset +\nrebuild; ad-hoc migrations are sometimes applied via <code>psql</code> with a manual <code>schema_migrations</code>\ninsert.</li>\n<li><code>migrate.ts --status</code> lists applied/pending.</li>\n</ul>\n<h3 id=\"seeding-dev\">Seeding (dev)</h3>\n<ul>\n<li><code>database/seed.ts</code> — idempotent demo seed: demo tenant <code>1111…1111</code> (&quot;Demo Car Wash&quot;), 2 outlets,\n4 users, 7 services, 3 customers, 2 membership plans, 3 voucher templates, 3 bays. Passwords are\nreal bcrypt hashes generated at runtime (login <code>password123</code>, admin PIN <code>1234</code>).</li>\n<li><code>database/seed-users.mjs</code> — standalone upsert of owner / superadmin / cashier for the demo\ntenant.</li>\n<li>Seeded logins: <code>owner@demo.com</code> (tenant_owner), <code>admin@sudirman.demo.com</code> (outlet_admin),\n<code>cashier1@sudirman.demo.com</code> / <code>cashier1@demo.com</code> (cashier), <code>superadmin@aire.com</code>\n(platform_super_admin, NULL tenant).</li>\n</ul>\n<h2 id=\"3-tenancy--row-level-security\">3. Tenancy &amp; Row-Level Security</h2>\n<ul>\n<li>Every domain table carries <code>tenant_id</code> (child tables inherit it via their parent).</li>\n<li><strong>RLS policies</strong> (<code>003_rls_policies.sql</code>) exist: a NOLOGIN role <code>app_user</code> with per-table\npolicies keyed on session GUCs <code>app.tenant_id</code> / <code>app.role</code> / <code>app.outlet_id</code>. Tenant-isolation\npolicies filter by <code>app.tenant_id</code>; outlet-scoping policies restrict lower roles to their\n<code>app.outlet_id</code>; the <code>users</code> policy lets a super-admin see NULL-tenant rows.</li>\n<li><strong>In practice</strong> the app enforces isolation mostly through explicit query predicates; the\n<code>RlsContextGuard</code> (which sets those GUCs per request) is applied by the <code>settings</code> and\n<code>discovery</code> modules. <code>004_updated_at_trigger.sql</code> adds <code>set_updated_at</code> triggers.</li>\n</ul>\n<h2 id=\"4-data-model-by-domain\">4. Data model by domain</h2>\n<blockquote>\n<p>FK notation: <code>col</code>→<code>table</code> with delete rule where notable. Status enums are <code>CHECK</code> constraints.</p>\n</blockquote>\n<h3 id=\"foundation--saas\">Foundation / SaaS</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>tenants</code> (001)</td>\n<td>SaaS tenant</td>\n<td><code>slug</code> UNIQUE; <code>plan</code>; <code>status</code>(active/suspended/cancelled); <code>settings JSONB</code> (holds <code>featureFlags</code>, <code>branding</code>, <code>payment</code>, automation, <code>receipt_template</code>); <code>tenant_code CHAR(6)</code> (034)</td>\n</tr>\n<tr>\n<td><code>outlets</code> (001)</td>\n<td>Branch</td>\n<td><code>tenant_id</code>→tenants (RESTRICT); <code>agent_id</code> UNIQUE; <code>settings JSONB</code> (<code>service_charge_pct</code>,<code>tax_pct</code>); <code>legal_entity</code>,<code>code</code> (012); <code>phone</code>,<code>maps_url</code> (017); <code>branch_code CHAR(2)</code> (034)</td>\n</tr>\n<tr>\n<td><code>users</code> (001)</td>\n<td>Login account</td>\n<td><code>tenant_id</code>(CASCADE, NULL=super); <code>outlet_id</code>(SET NULL); <code>email</code> UNIQUE; <code>password_hash</code>; <code>role</code>(4 roles); <code>admin_pin_hash</code>; <code>custom_role_id</code>→roles (012)</td>\n</tr>\n<tr>\n<td><code>user_outlets</code> (012)</td>\n<td>Multi-branch staff placement</td>\n<td><code>(user_id, outlet_id)</code></td>\n</tr>\n<tr>\n<td><code>roles</code> (012)</td>\n<td>Custom tenant RBAC roles</td>\n<td><code>tenant_id</code>; <code>base_role</code>; permission set</td>\n</tr>\n<tr>\n<td><code>payment_methods</code> (012)</td>\n<td>Per-branch POS payment buttons</td>\n<td><code>outlet_id</code>; <code>kind</code>(cash/qris/edc/cc/transfer); <code>business_unit</code>(AIRE/LEAD/NULL); logo/colour</td>\n</tr>\n<tr>\n<td><code>brands</code>, <code>product_categories</code> (012)</td>\n<td>Catalog taxonomy</td>\n<td><code>tenant_id</code></td>\n</tr>\n<tr>\n<td><code>platform_config</code> (019)</td>\n<td>Singleton platform config</td>\n<td>default plans + feature flags; legacy pricing tiers seeded 026 (fallback for MRR)</td>\n</tr>\n<tr>\n<td><code>platform_plans</code> (041)</td>\n<td>SaaS subscription plans charged to tenants</td>\n<td><code>code</code>(=<code>tenants.plan</code>),<code>name</code>,<code>price</code>,<code>billing_cycle</code>(monthly/annual),<code>features JSONB</code>,<code>limits JSONB</code>,<code>is_active</code>,<code>sort_order</code>; drives Billing MRR. Distinct from <code>membership_plans</code>.</td>\n</tr>\n<tr>\n<td><code>audit_logs</code> (001)</td>\n<td>Audit trail</td>\n<td><code>tenant_id</code>,<code>outlet_id</code>,<code>user_id</code>; <code>operation</code>,<code>entity_type</code>,<code>entity_id</code>; before/after/metadata JSONB; <code>ip_address INET</code>. Surfaced platform-wide via <code>GET /admin/audit</code>.</td>\n</tr>\n<tr>\n<td><code>platform_invoices</code> (049)</td>\n<td>Real platform billing ledger</td>\n<td><code>tenant_id</code>,<code>period</code>(YYYY-MM, unique per tenant),<code>plan_code</code>,<code>amount</code>,<code>status</code>(draft/sent/paid/overdue/void),<code>issued_at</code>/<code>due_date</code>/<code>paid_at</code>. Background job auto-generates drafts + marks overdue.</td>\n</tr>\n<tr>\n<td><code>platform_announcements</code> (050)</td>\n<td>Broadcast messages to tenants</td>\n<td><code>title</code>,<code>body</code>,<code>severity</code>(info/warning/critical),<code>audience</code>(all/plan/tenant)+<code>target</code>,<code>published</code>,<code>starts_at</code>/<code>ends_at</code>. Read by tenants via <code>GET /announcements/feed</code>.</td>\n</tr>\n<tr>\n<td><code>platform_support_notes</code> (050)</td>\n<td>Internal per-tenant support log</td>\n<td><code>tenant_id</code>,<code>body</code>,<code>pinned</code>,<code>author_id</code>. Never shown to the tenant.</td>\n</tr>\n</tbody></table>\n<h3 id=\"catalog--commerce\">Catalog / Commerce</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>services</code> (001)</td>\n<td>Service + product catalog (products = services)</td>\n<td><code>outlet_id</code> (NULL=all); <code>category</code>(car_wash/product/add_on); <code>price</code>; <code>is_main_service</code>; <code>business_unit</code> (011); <code>category_id</code>,<code>brand_id</code>,<code>outlet_ids UUID[]</code> (012)</td>\n</tr>\n<tr>\n<td><code>orders</code> (001)</td>\n<td>POS transaction</td>\n<td><code>outlet_id</code>(RESTRICT); <code>operator_id</code>→users; <code>customer_id</code>; <code>order_number</code>; <code>status</code>(ordered/paid/confirmed/completed/cancelled); money fields; <code>payment_method/reference/amount_received/change_amount</code>; <code>membership_id</code>; void fields; <code>shift_id</code>(009); <code>business_unit</code>,<code>payment_channel</code>,<code>salesperson_name</code>(011); <code>channel</code>(pos/kiosk/customer)(033)</td>\n</tr>\n<tr>\n<td><code>order_items</code> (001)</td>\n<td>Line items</td>\n<td><code>order_id</code>(CASCADE); <code>service_id</code>(RESTRICT); <code>unit_price</code>,<code>discount</code>,<code>subtotal</code>; member-pricing fields; <code>cost_snapshot</code>(032, frozen COGS)</td>\n</tr>\n<tr>\n<td><code>order_tags</code> (001)</td>\n<td>Labels</td>\n<td><code>tag</code>(regular/member/voucher/new_member/renewal/buy_voucher_pack)</td>\n</tr>\n<tr>\n<td><code>order_status_logs</code> (005)</td>\n<td>Status history</td>\n<td><code>from_status</code>,<code>to_status</code>,<code>operator_id</code></td>\n</tr>\n<tr>\n<td><code>voucher_templates</code> (001)</td>\n<td>Voucher/pack definitions</td>\n<td><code>type</code>(fixed/percentage/service_pack); <code>value</code>,<code>max_uses</code>; scopes; <code>sale_price</code>,<code>validity_days</code>(006)</td>\n</tr>\n<tr>\n<td><code>voucher_packs</code> (001)</td>\n<td>Sold pack (hashed parent code)</td>\n<td><code>template_id</code>; <code>parent_code_hash</code>; <code>status</code>(active/fully_redeemed/expired/cancelled); <code>expiry_date</code>(006)</td>\n</tr>\n<tr>\n<td><code>voucher_codes</code> (001)</td>\n<td>Redeemable child codes</td>\n<td><code>pack_id</code>(CASCADE); <code>code_hash</code> UNIQUE; <code>status</code>(active/redeemed/expired/cancelled)</td>\n</tr>\n<tr>\n<td><code>voucher_books</code> (013)</td>\n<td>Shareable digital voucher book</td>\n<td><code>benefit_type</code>(service/fixed/percentage); format <code>BRANCH-MMYYYY-NNNNNN</code></td>\n</tr>\n<tr>\n<td><code>voucher_tickets</code> (013)</td>\n<td>Individual plaintext tickets</td>\n<td><code>book_id</code>(CASCADE); <code>status</code>(active/redeemed/expired/void)</td>\n</tr>\n<tr>\n<td><code>voucher_counters</code> (013)</td>\n<td>Per branch+MMYYYY sequence</td>\n<td><code>(outlet_id, period)</code></td>\n</tr>\n<tr>\n<td><code>promotions</code> (013)</td>\n<td>Promotion engine</td>\n<td><code>reward_type</code>(discount_fixed/percentage/free_product/free_voucher/future_discount); <code>max_quota</code></td>\n</tr>\n<tr>\n<td><code>promotion_grants</code> (013)</td>\n<td>Redemptions</td>\n<td><code>promotion_id</code>(CASCADE); <code>order_id</code></td>\n</tr>\n<tr>\n<td><code>campaigns</code> / <code>campaign_grants</code> (001)</td>\n<td>Plan+bonus campaigns</td>\n<td><code>plan_id</code>,<code>bonus_template_id</code>; per-customer grants</td>\n</tr>\n<tr>\n<td><code>expenses</code> (008)</td>\n<td>Finance expenses</td>\n<td><code>tenant_id</code>,<code>outlet_id</code></td>\n</tr>\n<tr>\n<td><code>sales_targets</code> (008)</td>\n<td>Monthly targets</td>\n<td><code>period</code> YYYY-MM</td>\n</tr>\n<tr>\n<td><code>sales_leads</code> (008)</td>\n<td>Sales pipeline</td>\n<td><code>status</code>(new/contacted/won/lost)</td>\n</tr>\n<tr>\n<td><code>settlement_entries</code> (013)</td>\n<td>Inter-branch ledger</td>\n<td><code>owing_outlet_id</code>/<code>serving_outlet_id</code>; <code>amount</code>; <code>status</code>(pending/paid/void)</td>\n</tr>\n<tr>\n<td><code>settlement_payouts</code> (013)</td>\n<td>Payout batch</td>\n<td>pair + <code>amount</code>,<code>entry_count</code></td>\n</tr>\n</tbody></table>\n<h3 id=\"membership\">Membership</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>membership_plans</code> (001)</td>\n<td>Plan</td>\n<td><code>duration_months</code>,<code>max_uses</code>,<code>daily_limit</code>,<code>max_plates</code>,<code>price</code>; <code>outlet_ids[]</code>,<code>free_service_ids[]</code>,<code>discounted_services JSONB</code>; <code>whatsapp_welcome_enabled</code>; <code>settlement_amount</code>(013)</td>\n</tr>\n<tr>\n<td><code>memberships</code> (001)</td>\n<td>Subscription</td>\n<td><code>customer_id</code>,<code>plan_id</code>(RESTRICT); <code>status</code>; <code>start_date</code>,<code>end_date</code>; <code>uses_count</code>,<code>max_uses</code>,<code>daily_limit</code>; <code>order_id</code>; <code>home_outlet_id</code>(013); <code>suspended_at/reason</code>(027); <code>grace_until</code>,<code>revoked_at</code>(031). <strong>Status evolves:</strong> 001 active/expired/pending/cancelled → 027 +suspended → 031 +grace/+revoked</td>\n</tr>\n<tr>\n<td><code>membership_plates</code> (001)</td>\n<td>Registered plates</td>\n<td><code>membership_id</code>(CASCADE); <code>plate_normalized</code>,<code>brand</code>,<code>model</code></td>\n</tr>\n<tr>\n<td><code>membership_usages</code> (001)</td>\n<td>Per-wash quota tracking</td>\n<td><code>plate_normalized</code>,<code>order_id</code>,<code>reversed</code>; <code>outlet_id</code>(013, settlement)</td>\n</tr>\n<tr>\n<td><code>membership_events</code> (031)</td>\n<td>Lifecycle history</td>\n<td><code>event_type</code>,<code>payload JSONB</code>,<code>actor</code></td>\n</tr>\n<tr>\n<td><code>membership_renewals</code> (037)</td>\n<td>Pending renewal vs fee order</td>\n<td><code>order_id</code>(CASCADE, UNIQUE); <code>membership_id</code>,<code>plan_id</code>; <code>applied</code>,<code>applied_at</code></td>\n</tr>\n<tr>\n<td><code>customers</code> (001)</td>\n<td>Customer directory</td>\n<td><code>phone</code>,<code>phone_normalized</code> UNIQUE per tenant; <code>email</code>(039); identity <code>customer_code CHAR(4)</code>,<code>registered_outlet_id</code>,<code>membership_number CHAR(12)</code>(034)</td>\n</tr>\n</tbody></table>\n<p><strong>Membership identity (034):</strong> 12-char base-36 number = <code>tenant_code(6) + branch_code(2) + customer_code(4)</code>, via nullable columns + partial-unique indexes so legacy rows don&#39;t collide.</p>\n<h3 id=\"queue--kiosk--bookings\">Queue / Kiosk / Bookings</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>bays</code> (001)</td>\n<td>Physical wash bay (IoT)</td>\n<td><code>status</code>(available/occupied/maintenance); <code>controller_id</code>,<code>current_order_id</code>,<code>sensor_data JSONB</code>,<code>last_heartbeat</code></td>\n</tr>\n<tr>\n<td><code>queue_entries</code> (001)</td>\n<td>Order-linked queue (kiosk <code>join-queue</code>)</td>\n<td><code>order_id</code>(CASCADE); <code>position</code>,<code>priority</code>,<code>bay_id</code>; <code>status</code>(waiting/in_progress/completed)</td>\n</tr>\n<tr>\n<td><code>vehicle_queue</code> (014)</td>\n<td>Arrival board (decoupled from orders)</td>\n<td>plate/brand/type; <code>business_unit</code>; <code>status</code>(waiting/serving/done/cancelled); <code>order_id</code>(SET NULL, linked later)</td>\n</tr>\n<tr>\n<td><code>kiosk_devices</code> (030)</td>\n<td>Self-service kiosk auth</td>\n<td><code>token VARCHAR(64)</code> UNIQUE; <code>is_active</code>,<code>last_seen_at</code></td>\n</tr>\n<tr>\n<td><code>bookings</code> (021)</td>\n<td>Appointments</td>\n<td><code>service_id</code>,<code>scheduled_at</code>; <code>status</code>(booked/confirmed/done/cancelled); <code>customer_id</code>,<code>confirmation_token</code>,<code>queue_entry_id</code>,<code>source</code>(040)</td>\n</tr>\n<tr>\n<td><code>vehicle_brands</code> / <code>vehicle_types</code> (035, seeded 036)</td>\n<td>POS/queue dropdowns</td>\n<td>brand→type; 036 seeds ~35 ID-market brands/models</td>\n</tr>\n<tr>\n<td><del><code>alpr_detections</code></del> (029)</td>\n<td><strong>Dropped</strong> — ALPR removed (manual plate entry unaffected)</td>\n<td>—</td>\n</tr>\n</tbody></table>\n<h3 id=\"inventory--cogs--procurement\">Inventory / COGS / Procurement</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>inventory_items</code> (008)</td>\n<td>Stock master</td>\n<td><code>outlet_id</code>; <code>unit_cost</code>,<code>unit</code>,<code>quantity</code>,<code>reorder_level</code></td>\n</tr>\n<tr>\n<td><code>inventory_movements</code> (008)</td>\n<td>Stock ledger</td>\n<td><code>type</code>: 001 in/out/adjustment → <strong>032 +sale/+sale_return</strong>; <code>reference</code></td>\n</tr>\n<tr>\n<td><code>suppliers</code> / <code>purchase_orders</code> / <code>purchase_order_items</code> (008)</td>\n<td>Procurement</td>\n<td>PO <code>status</code>(draft/ordered/received/cancelled)</td>\n</tr>\n<tr>\n<td><code>service_recipe_components</code> (032)</td>\n<td>Recipe / BOM per unit</td>\n<td><code>service_id</code>(CASCADE)+<code>inventory_item_id</code>(RESTRICT); <code>quantity</code>,<code>unit</code></td>\n</tr>\n<tr>\n<td><code>cost_component_types</code> (032)</td>\n<td>Reusable non-physical cost types</td>\n<td><code>kind</code>(fixed/percentage)</td>\n</tr>\n<tr>\n<td><code>service_cost_components</code> (032)</td>\n<td>Per-product cost values</td>\n<td><code>component_type_id</code>(RESTRICT); <code>value</code></td>\n</tr>\n<tr>\n<td><code>uom_conversions</code> (032)</td>\n<td>Per-item unit conversions</td>\n<td><code>from_unit</code>,<code>to_unit</code>,<code>factor</code></td>\n</tr>\n<tr>\n<td><code>stock_opname</code> / <code>stock_opname_items</code> (032)</td>\n<td>Physical count + variance</td>\n<td>header <code>status</code>(draft/counting/closed); item <code>expected/counted/variance/variance_value</code></td>\n</tr>\n</tbody></table>\n<h3 id=\"shifts--hr--payroll\">Shifts / HR / Payroll</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>pos_shifts</code> (009)</td>\n<td>Register open/close + cash reconciliation</td>\n<td><code>operator_id</code>,<code>outlet_id</code>; <code>status</code>(open/closed); floats/counted</td>\n</tr>\n<tr>\n<td><code>petty_cash_movements</code> (009)</td>\n<td>Petty cash per shift</td>\n<td><code>type</code>(in/out)</td>\n</tr>\n<tr>\n<td><code>shift_issues</code> (009)</td>\n<td>Incident log</td>\n<td><code>severity</code>(low/medium/high)</td>\n</tr>\n<tr>\n<td><code>employee_shifts</code> (001)</td>\n<td>Early clock model</td>\n<td><code>user_id</code></td>\n</tr>\n<tr>\n<td><code>employees</code> (008)</td>\n<td>HR records</td>\n<td><code>outlet_id</code>; <code>status</code>(active/inactive); <code>user_id</code>(028, 1:1 login link)</td>\n</tr>\n<tr>\n<td><code>attendance_records</code> (008)</td>\n<td>Attendance</td>\n<td><code>status</code>(present/absent/leave/late); <code>hours_worked</code>(010)</td>\n</tr>\n<tr>\n<td><code>leave_requests</code> (008)</td>\n<td>Leave</td>\n<td><code>status</code>(pending/approved/rejected); <code>paid</code>(010)</td>\n</tr>\n<tr>\n<td><code>employee_schedules</code> (010)</td>\n<td>Roster (one/employee/day)</td>\n<td><code>work_date</code>,<code>start/end_time</code></td>\n</tr>\n<tr>\n<td><code>holidays</code> (010)</td>\n<td>Holidays</td>\n<td><code>is_paid</code></td>\n</tr>\n<tr>\n<td><code>payroll_adjustments</code> (010)</td>\n<td>Bonus/deduction/advance</td>\n<td><code>type</code>; <code>effective_period</code>; <code>status</code>(pending/applied)</td>\n</tr>\n<tr>\n<td><code>employee_loans</code> / <code>loan_repayments</code> (010)</td>\n<td>Loans</td>\n<td>loan <code>status</code>(active/paid/cancelled)</td>\n</tr>\n<tr>\n<td><code>payroll_runs</code> / <code>payslips</code> (010)</td>\n<td>Payroll</td>\n<td>run <code>status</code>(draft/finalized)</td>\n</tr>\n</tbody></table>\n<h3 id=\"ai--agents\">AI / Agents</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>agent_configs</code> (015)</td>\n<td>Per-tenant WhatsApp/AI config (PK=tenant_id)</td>\n<td><code>wa_provider</code>(waha/kapso); <code>routing_mode</code>(builtin/n8n),<code>n8n_flow_id</code>,<code>bridge_token</code>(038)</td>\n</tr>\n<tr>\n<td><code>agents</code> (022)</td>\n<td>Named agent personas registry</td>\n<td><code>role</code>(personal_assistant/customer_service/sales/supervisor),<code>prompt</code>,<code>position</code></td>\n</tr>\n<tr>\n<td><code>agent_flows</code> (038)</td>\n<td>Platform catalog of published n8n flows</td>\n<td><code>kind</code>(whatsapp/automation),<code>webhook_url</code>,<code>enabled</code></td>\n</tr>\n<tr>\n<td><code>action_proposals</code> (007)</td>\n<td>AI approval queue</td>\n<td><code>status</code>(pending/approved/rejected/expired)</td>\n</tr>\n<tr>\n<td><code>scheduled_analysis_runs</code> (007)</td>\n<td>Scheduled AI analysis</td>\n<td><code>status</code>(running/completed/failed)</td>\n</tr>\n<tr>\n<td><code>domain_events</code> (007)</td>\n<td>Domain event store</td>\n<td><code>tenant_id</code>-scoped</td>\n</tr>\n<tr>\n<td><code>agent_invocations</code> (007)</td>\n<td>Every tool/llm/chat/analysis call (telemetry)</td>\n<td><code>kind</code>,<code>status</code>,<code>duration</code>,<code>tokens</code>; <code>outlet_id</code>(025)</td>\n</tr>\n<tr>\n<td><code>agent_chat_sessions</code> / <code>agent_chat_messages</code> (007)</td>\n<td>In-app co-pilot chat</td>\n<td>message <code>role</code>(user/assistant/tool/system)</td>\n</tr>\n<tr>\n<td><code>wa_conversations</code> / <code>wa_messages</code> (016)</td>\n<td>WhatsApp threads</td>\n<td>conv <code>status</code>(open/escalated/closed); msg <code>direction</code>(inbound/outbound)</td>\n</tr>\n</tbody></table>\n<h3 id=\"portal\">Portal</h3>\n<table>\n<thead>\n<tr>\n<th>Table (mig)</th>\n<th>Purpose</th>\n<th>Key columns</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>customer_otps</code> (039)</td>\n<td>WhatsApp-OTP login store</td>\n<td><code>phone_normalized</code>,<code>code_hash</code>,<code>expires_at</code>,<code>attempts</code>,<code>last_sent_at</code>; UNIQUE(tenant,phone)</td>\n</tr>\n</tbody></table>\n<h2 id=\"5-notable-data-flow-facts\">5. Notable data-flow facts</h2>\n<ul>\n<li><strong>Order = the source of truth for payment.</strong> The queue&#39;s paid/unpaid badge is derived from the\nlinked order, never duplicated.</li>\n<li><strong>COGS is frozen at sale</strong> in <code>order_items.cost_snapshot</code>; margin reports read the snapshot, not\nthe live recipe.</li>\n<li><strong>Membership status has two writers of truth</strong> that agree: the read-time\n<code>MembershipLifecycleService.derive()</code> and the 6-hourly transition job — plus the hard\nbenefit guard <code>status=&#39;active&#39; AND end_date &gt;= CURRENT_DATE</code>.</li>\n<li><strong>Renewal is two-phase</strong>: a pending <code>membership_renewals</code> row is written with the fee order and\nonly applied once that order is paid (idempotent).</li>\n<li><strong>Cross-branch membership washes</strong> write <code>settlement_entries</code>; <code>settlement_payouts</code> net them.</li>\n<li><strong>Naming quirks:</strong> <code>023_rename_agents</code> only updates data values (not a table rename); <code>actor</code>\n(membership_events) and <code>created_by</code> (stock_opname) are FK-less UUIDs; the only <code>DROP TABLE</code> is\n<code>alpr_detections</code> (029).</li>\n</ul>\n<h2 id=\"6-aireshared-shared-domain-package\">6. <code>@aire/shared</code> (shared domain package)</h2>\n<p>Re-exported from <code>packages/shared/src/index.ts</code>:</p>\n<ul>\n<li><strong>Enums</strong> — <code>Role</code>, <code>OrderStatus</code>, <code>PaymentMethod</code>, <code>BusinessUnit</code>, <code>VoucherType</code>, <code>BayStatus</code>,\n<code>MembershipStatus</code>, <code>ServiceCategory</code>, <code>MachineStatus</code>; <code>MEMBERSHIP_GRACE_DAYS = 14</code>.</li>\n<li><strong>Constants</strong> — validation limits, token expiries (access 900 s / refresh 604800 s),\n<code>ROLE_HIERARCHY</code>, <code>OUTLET_SCOPED_ROLES</code>, <code>ORDER_STATUS_TRANSITIONS</code>, pagination defaults.</li>\n<li><strong><code>modules.ts</code></strong> — the <code>TENANT_MODULES</code> feature-flag registry + <code>resolveTenantModules</code> /\n<code>isModuleEnabled</code>.</li>\n<li><strong><code>error-codes.ts</code></strong> — ~70 <code>ERR_*</code> codes.</li>\n<li><strong>Interfaces/DTOs</strong> — order, member, payment (incl. the <code>PaymentProvider</code> gateway interface),\nauth (<code>JWTPayload</code>), bay, service, voucher, report.</li>\n<li><strong>Pure domain logic</strong> (unit-tested, shared front+back) — cart calculator, customer tagging,\nvoucher evaluation + code gen, membership quota, void authorization, payment, campaign\neligibility, report aggregation, employee commission, queue priority/bay assignment.</content></li>\n</ul>\n"},{"slug":"tech-api-reference","title":"05 · API Reference","category":"tech","audience":"Technical","blurb":"Every HTTP endpoint by module, with role and purpose.","order":8,"words":1935,"minutes":10,"toc":[{"id":"auth--identity","text":"Auth & identity","level":2},{"id":"access--rbac-access","text":"Access / RBAC (access)","level":2},{"id":"tenants--outlets","text":"Tenants & outlets","level":2},{"id":"platform-admin-admin","text":"Platform admin (admin)","level":2},{"id":"services-catalog-payment-methods-vehicles","text":"Services, catalog, payment methods, vehicles","level":2},{"id":"orders--payments","text":"Orders & payments","level":2},{"id":"shifts--queue","text":"Shifts & queue","level":2},{"id":"inventory--cogs--procurement--finance","text":"Inventory / COGS / procurement / finance","level":2},{"id":"reports--sales","text":"Reports & sales","level":2},{"id":"hr--payroll","text":"HR & payroll","level":2},{"id":"membership--customers","text":"Membership & customers","level":2},{"id":"vouchers--promotions","text":"Vouchers & promotions","level":2},{"id":"bookings--settlement","text":"Bookings & settlement","level":2},{"id":"kiosk-device-token--public-menu","text":"Kiosk (device token) & public menu","level":2},{"id":"customer-portal","text":"Customer portal","level":2},{"id":"ai-whatsapp--bridge","text":"AI, WhatsApp & bridge","level":2},{"id":"config-invoices-bays-audit","text":"Config, invoices, bays, audit","level":2}],"html":"<h1 id=\"05--api-reference\">05 · API Reference</h1>\n<p>All routes are prefixed <strong><code>/api</code></strong>. The <strong>Role</strong> column is the <em>minimum</em> role (RolesGuard is\nhierarchical: <code>@Roles(OutletAdmin)</code> also admits owner and super-admin). &quot;Auth&quot; = any authenticated\nstaff user (JWT, no role gate). &quot;Public&quot; = no auth. &quot;Portal&quot; = customer JWT (<code>typ:customer</code>).\n&quot;Kiosk&quot; = device token. &quot;Bridge&quot; = per-tenant bridge token.</p>\n<blockquote>\n<p>This reference is generated from the code trace; paths and guards reflect the controllers as\nwritten. (The <code>customer</code> module&#39;s search/profile/analytics routes were hardened on 2026-07-11 —\nthey now carry a class-level <code>JwtAuthGuard + RolesGuard</code> and are tenant-scoped; see\n<a href=\"/docs/tech-backend#2-authentication-roles--multi-tenancy\">02 · Backend</a>.)</p>\n</blockquote>\n<h2 id=\"auth--identity\">Auth &amp; identity</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>POST <code>/auth/login</code></td>\n<td>Public</td>\n<td>Email+password → token pair + user</td>\n</tr>\n<tr>\n<td>POST <code>/auth/register</code></td>\n<td>Public</td>\n<td>Create tenant + owner, auto-login</td>\n</tr>\n<tr>\n<td>POST <code>/auth/forgot-password</code></td>\n<td>Public</td>\n<td>Issue reset token (Redis)</td>\n</tr>\n<tr>\n<td>POST <code>/auth/reset-password</code></td>\n<td>Public</td>\n<td>Reset password via token</td>\n</tr>\n<tr>\n<td>POST <code>/auth/refresh</code></td>\n<td>Public</td>\n<td>Rotate refresh token → new pair</td>\n</tr>\n</tbody></table>\n<h2 id=\"access--rbac-access\">Access / RBAC (<code>access</code>)</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/permissions</code></td>\n<td>OutletAdmin</td>\n<td>Permission catalog</td>\n</tr>\n<tr>\n<td>GET/POST <code>/roles</code> · PUT/DELETE <code>/roles/:id</code></td>\n<td>TenantOwner</td>\n<td>Custom role CRUD</td>\n</tr>\n<tr>\n<td>GET/POST <code>/users</code> · PUT <code>/users/:id</code> · PATCH <code>/users/:id/deactivate</code></td>\n<td>TenantOwner</td>\n<td>User CRUD + multi-branch placement</td>\n</tr>\n</tbody></table>\n<h2 id=\"tenants--outlets\">Tenants &amp; outlets</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>POST/GET <code>/tenants</code> · GET/PUT <code>/tenants/:id</code></td>\n<td>PlatformSuperAdmin</td>\n<td>Plain tenant CRUD</td>\n</tr>\n<tr>\n<td>POST/GET <code>/outlets</code> · GET/PUT <code>/outlets/:id</code></td>\n<td>TenantOwner</td>\n<td>Branch CRUD</td>\n</tr>\n<tr>\n<td>PATCH <code>/outlets/:id/activate</code> · <code>/deactivate</code></td>\n<td>TenantOwner</td>\n<td>Branch activation</td>\n</tr>\n</tbody></table>\n<h2 id=\"platform-admin-admin\">Platform admin (<code>admin</code>)</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/admin/overview</code> · <code>/tenants/enriched</code> · <code>/tenants/:id/detail</code> · <code>/tenants/:id/branches</code> · <code>/activity</code> · <code>/timeseries</code> · <code>/health</code> · <code>/ai-usage</code> · <code>/monitoring</code></td>\n<td>SuperAdmin</td>\n<td>Platform metrics (<code>:id</code> accepts slug or UUID)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/health/containers</code> · <code>/admin/health/containers/:id/logs</code></td>\n<td>SuperAdmin</td>\n<td>Docker container status + logs (via socket; empty when unmounted)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/tenants</code></td>\n<td>SuperAdmin</td>\n<td>List tenants</td>\n</tr>\n<tr>\n<td>POST <code>/admin/tenants</code> · PUT <code>/admin/tenants/:id</code></td>\n<td>SuperAdmin</td>\n<td>Create/edit tenant</td>\n</tr>\n<tr>\n<td>GET/PUT <code>/admin/tenants/:id/modules</code></td>\n<td>SuperAdmin</td>\n<td>Read/toggle per-tenant modules (audited)</td>\n</tr>\n<tr>\n<td>PATCH <code>/admin/tenants/:id/suspend</code> · <code>/reactivate</code></td>\n<td>SuperAdmin</td>\n<td>Tenant lifecycle</td>\n</tr>\n<tr>\n<td>POST <code>/admin/tenants/:id/impersonate</code></td>\n<td>SuperAdmin</td>\n<td>Mint impersonation token (audited)</td>\n</tr>\n<tr>\n<td>GET/PUT <code>/admin/config</code></td>\n<td>SuperAdmin write</td>\n<td>Platform config (default plans, feature flags)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/platform-plans</code> · POST · PUT/DELETE <code>/:id</code></td>\n<td>GET any admin / writes SuperAdmin</td>\n<td>SaaS subscription plans charged to tenants (drives MRR)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/audit</code> · <code>/admin/audit/filters</code></td>\n<td>SuperAdmin</td>\n<td>Cross-tenant audit log (filters: tenantId/operation/entityType/date, paginated) + distinct filter values</td>\n</tr>\n<tr>\n<td>GET <code>/admin/analytics?months=</code></td>\n<td>SuperAdmin</td>\n<td>Growth metrics: snapshot, churn≈, MRR/ARR, signup cohorts + retention (approximated — no status history)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/invoices</code> · <code>/invoices/summary</code> · POST <code>/invoices/generate</code> · PATCH <code>/invoices/:id/status</code> · PUT <code>/invoices/:id</code></td>\n<td>SuperAdmin</td>\n<td>Platform subscription invoices (real billing ledger). <code>generate</code> idempotent per <code>(tenant, period)</code>; a background job auto-generates the current month&#39;s drafts + flips past-due to overdue (disable via <code>PLATFORM_INVOICE_AUTOGEN=false</code>)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/platform-users</code> · POST · PATCH <code>/:id/active</code> · POST <code>/:id/password</code></td>\n<td>SuperAdmin</td>\n<td>Manage platform-super-admin accounts (create/enable/disable/reset-password; can&#39;t self-deactivate; audited)</td>\n</tr>\n<tr>\n<td>POST <code>/admin/tenants/:id/reset-owner-password</code></td>\n<td>SuperAdmin</td>\n<td>Privileged reset of a tenant owner&#39;s password (audited)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/announcements</code> · POST · PUT <code>/:id</code> · DELETE <code>/:id</code></td>\n<td>SuperAdmin</td>\n<td>Platform announcements (audience all/plan/tenant, severity, published, optional window)</td>\n</tr>\n<tr>\n<td>GET <code>/admin/tenants/:id/notes</code> · POST · DELETE <code>/admin/notes/:id</code></td>\n<td>SuperAdmin</td>\n<td>Internal per-tenant support notes (never shown to the tenant)</td>\n</tr>\n<tr>\n<td>GET <code>/announcements/feed</code></td>\n<td>Auth (any tenant user)</td>\n<td>Tenant-facing read of published announcements targeted to the caller&#39;s tenant/plan (drives the dashboard banner)</td>\n</tr>\n</tbody></table>\n<h2 id=\"services-catalog-payment-methods-vehicles\">Services, catalog, payment methods, vehicles</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>POST/GET <code>/services</code> · GET/PUT/DELETE <code>/services/:id</code> · PATCH <code>/services/reorder</code></td>\n<td>Auth</td>\n<td>Service/product catalog</td>\n</tr>\n<tr>\n<td>GET <code>/services/:id/recipe</code> · PUT <code>/services/:id/recipe</code></td>\n<td>OutletAdmin</td>\n<td>Product recipe/BOM + cost components</td>\n</tr>\n<tr>\n<td>GET/POST <code>/categories</code> · PUT/DELETE <code>/categories/:id</code></td>\n<td>Auth read / OutletAdmin write</td>\n<td>Service categories</td>\n</tr>\n<tr>\n<td>GET/POST <code>/brands</code> · PUT/DELETE <code>/brands/:id</code></td>\n<td>Auth read / OutletAdmin write</td>\n<td>Product brands</td>\n</tr>\n<tr>\n<td>GET/POST <code>/payment-methods</code> · PUT/DELETE <code>/payment-methods/:id</code></td>\n<td>Auth read / OutletAdmin write</td>\n<td>Per-branch payment buttons</td>\n</tr>\n<tr>\n<td>GET/POST <code>/vehicle-brands</code> · DELETE <code>/vehicle-brands/:id</code> · POST <code>/vehicle-types</code> · DELETE <code>/vehicle-types/:id</code></td>\n<td>Auth read / OutletAdmin write</td>\n<td>Vehicle brand→type catalog</td>\n</tr>\n</tbody></table>\n<h2 id=\"orders--payments\">Orders &amp; payments</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>POST <code>/orders</code></td>\n<td>Auth</td>\n<td>Create order from POS cart</td>\n</tr>\n<tr>\n<td>POST <code>/orders/:id/pay</code></td>\n<td>Auth</td>\n<td>Settle order (cash/QRIS-static/EDC/transfer)</td>\n</tr>\n<tr>\n<td>GET <code>/orders</code> · GET <code>/orders/:id</code></td>\n<td>Auth</td>\n<td>List / status poll</td>\n</tr>\n<tr>\n<td>PATCH <code>/orders/:id</code> · DELETE <code>/orders/:id</code></td>\n<td>OutletAdmin</td>\n<td>Edit / cancel (day-locked, restocks)</td>\n</tr>\n<tr>\n<td>POST <code>/payments/charge/:orderId</code></td>\n<td>Auth</td>\n<td>Create dynamic-QRIS charge</td>\n</tr>\n<tr>\n<td>POST <code>/payments/webhook/{xendit,midtrans,stripe}</code></td>\n<td>Public</td>\n<td>Gateway callbacks (signature-verified)</td>\n</tr>\n<tr>\n<td>GET/PUT <code>/payment-config</code></td>\n<td>OutletAdmin</td>\n<td>Per-tenant gateway config (secrets masked)</td>\n</tr>\n</tbody></table>\n<h2 id=\"shifts--queue\">Shifts &amp; queue</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/shifts/current</code> · <code>/shifts</code> · <code>/shifts/:id</code></td>\n<td>Auth</td>\n<td>Shift reads</td>\n</tr>\n<tr>\n<td>POST <code>/shifts/open</code> · <code>/shifts/:id/close</code> · <code>/shifts/:id/petty-cash</code> · <code>/shifts/:id/issues</code></td>\n<td>Auth</td>\n<td>Shift lifecycle</td>\n</tr>\n<tr>\n<td>GET/POST <code>/vehicle-queue</code> · PATCH status</td>\n<td>Auth</td>\n<td>Arrival board (add car / set service status; <code>done</code> requires paid order)</td>\n</tr>\n</tbody></table>\n<h2 id=\"inventory--cogs--procurement--finance\">Inventory / COGS / procurement / finance</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/inventory/summary</code> · <code>/items</code> · <code>/items/:id</code> · POST <code>/items</code> · POST <code>/items/:id/adjust</code></td>\n<td>Auth</td>\n<td>Stock items + movements</td>\n</tr>\n<tr>\n<td>GET/POST <code>/inventory/:id/uom</code> · DELETE <code>/uom/:id</code></td>\n<td>OutletAdmin</td>\n<td>Unit conversions</td>\n</tr>\n<tr>\n<td>GET/POST <code>/cost-component-types</code> · DELETE <code>/cost-component-types/:id</code></td>\n<td>OutletAdmin</td>\n<td>Non-physical cost types</td>\n</tr>\n<tr>\n<td>GET <code>/opname</code> · POST <code>/opname</code> · GET <code>/opname/:id</code> · PATCH <code>/opname/:id/items/:itemId</code> · POST <code>/opname/:id/close</code></td>\n<td>OutletAdmin</td>\n<td>Stock opname → reconcile</td>\n</tr>\n<tr>\n<td>GET <code>/cogs/pnl</code> · <code>/cogs/product-margin</code> · <code>/cogs/inventory-variance</code></td>\n<td>OutletAdmin</td>\n<td>COGS P&amp;L / margin / variance</td>\n</tr>\n<tr>\n<td>GET <code>/procurement/summary</code> · <code>/suppliers</code> · POST <code>/suppliers</code> · GET/POST <code>/purchase-orders</code> · POST <code>/purchase-orders/:id/receive</code></td>\n<td>Auth</td>\n<td>Procurement + auto-restock on receive</td>\n</tr>\n<tr>\n<td>GET <code>/finance/summary</code> · GET/POST <code>/finance/expenses</code></td>\n<td>Auth</td>\n<td>Revenue − expenses, expenses</td>\n</tr>\n</tbody></table>\n<h2 id=\"reports--sales\">Reports &amp; sales</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/reports/summary</code> · <code>/revenue-series</code> · <code>/customer-growth</code> · <code>/daily-sales</code> · <code>/shifts</code> · <code>/export</code></td>\n<td>Auth</td>\n<td>Reporting + CSV/PDF export</td>\n</tr>\n<tr>\n<td>GET <code>/sales/summary</code> · <code>/sales/leads</code> · POST <code>/sales/leads</code> · PATCH <code>/sales/leads/:id/status</code> · POST <code>/sales/targets</code></td>\n<td>Auth</td>\n<td>Sales attainment/forecast + leads + targets</td>\n</tr>\n</tbody></table>\n<h2 id=\"hr--payroll\">HR &amp; payroll</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/hr/summary</code> · <code>/hr/my/branch-context</code> · GET/POST <code>/hr/employees</code> · PATCH <code>/hr/employees/:id/link-user</code> · POST <code>/hr/employees/:id/{attendance,clock-in,clock-out}</code></td>\n<td>Auth</td>\n<td>Employees + attendance</td>\n</tr>\n<tr>\n<td>GET/POST <code>/hr/schedules</code> · <code>/hr/holidays</code> · <code>/hr/leave</code> · PATCH <code>/hr/leave/:id</code></td>\n<td>Auth</td>\n<td>Schedules, holidays, leave</td>\n</tr>\n<tr>\n<td>GET/POST <code>/payroll/adjustments</code> · <code>/payroll/loans</code> · POST <code>/payroll/loans/:id/repay</code></td>\n<td>Auth</td>\n<td>Adjustments + loans</td>\n</tr>\n<tr>\n<td>GET <code>/payroll/runs</code> · <code>/payroll/runs/:id</code> · POST <code>/payroll/generate</code> · <code>/payroll/runs/:id/finalize</code> · GET <code>/payroll/runs/:id/export</code></td>\n<td>Auth</td>\n<td>Payroll runs + CSV payslips</td>\n</tr>\n</tbody></table>\n<h2 id=\"membership--customers\">Membership &amp; customers</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>POST/GET <code>/membership-plans</code> · GET/PUT/DELETE <code>/membership-plans/:id</code></td>\n<td>Auth</td>\n<td>Membership plans</td>\n</tr>\n<tr>\n<td>POST <code>/memberships/sell</code> · POST <code>/memberships/:id/activate</code></td>\n<td>Auth</td>\n<td>Sell → activate (register plates)</td>\n</tr>\n<tr>\n<td>POST <code>/memberships/:id/renew</code> · POST <code>/memberships/apply-renewal</code></td>\n<td>Auth</td>\n<td>Renewal (fee order → apply after paid)</td>\n</tr>\n<tr>\n<td>POST <code>/memberships/backfill-numbers</code></td>\n<td>OutletAdmin</td>\n<td>Backfill membership numbers</td>\n</tr>\n<tr>\n<td>GET <code>/memberships/manage</code> · GET <code>/memberships/:id/events</code></td>\n<td>Auth</td>\n<td>CRM list + event history</td>\n</tr>\n<tr>\n<td>PATCH <code>/memberships/:id/suspend</code> · <code>/reactivate</code></td>\n<td>OutletAdmin</td>\n<td>Manual suspend/reactivate</td>\n</tr>\n<tr>\n<td>GET <code>/members/lookup?number|phone|plate</code></td>\n<td>Auth</td>\n<td>Resolve member (POS/kiosk)</td>\n</tr>\n<tr>\n<td>GET/PUT <code>/membership-card</code> · PUT/DELETE <code>/membership-card/background</code></td>\n<td>Auth read / OutletAdmin write</td>\n<td>Card designer</td>\n</tr>\n<tr>\n<td>GET <code>/public/card-template</code> · <code>/public/card-template/background</code></td>\n<td>Public</td>\n<td>Card template + bg stream</td>\n</tr>\n<tr>\n<td>GET <code>/customers/list</code> · PUT <code>/customers/:id</code></td>\n<td>OutletAdmin</td>\n<td>CRM list / edit</td>\n</tr>\n<tr>\n<td>DELETE <code>/customers/:id</code></td>\n<td>TenantOwner</td>\n<td>Delete customer</td>\n</tr>\n<tr>\n<td>GET <code>/customers</code> · <code>/customers/:id/profile</code> · <code>/customers/:id/analytics</code></td>\n<td>OutletAdmin</td>\n<td>Search / profile / analytics (tenant-scoped)</td>\n</tr>\n</tbody></table>\n<h2 id=\"vouchers--promotions\">Vouchers &amp; promotions</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/voucher-packs/catalog</code> · POST <code>/voucher-packs/sell</code> · POST <code>/voucher-packs/issue</code></td>\n<td>Auth</td>\n<td>Sell + issue packs</td>\n</tr>\n<tr>\n<td>GET/POST <code>/voucher-templates</code> · PUT/DELETE <code>/voucher-templates/:id</code></td>\n<td>Auth</td>\n<td>Pack templates</td>\n</tr>\n<tr>\n<td>POST <code>/vouchers/validate</code></td>\n<td>Auth</td>\n<td>Validate a child code against cart</td>\n</tr>\n<tr>\n<td>POST <code>/voucher-tickets/sell</code> · GET <code>/validate</code> · POST <code>/redeem</code> · GET <code>/books</code> · <code>/books/:id/tickets</code></td>\n<td>Auth</td>\n<td>Shareable digital vouchers</td>\n</tr>\n<tr>\n<td>GET/POST <code>/promotions</code> · PUT/DELETE <code>/promotions/:id</code></td>\n<td>Auth read / OutletAdmin write</td>\n<td>Promotions</td>\n</tr>\n</tbody></table>\n<h2 id=\"bookings--settlement\">Bookings &amp; settlement</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET/POST <code>/bookings</code> · PUT/DELETE <code>/bookings/:id</code></td>\n<td>Auth</td>\n<td>Staff bookings</td>\n</tr>\n<tr>\n<td>GET <code>/settlement/summary</code> · <code>/entries</code> · <code>/payouts</code> · POST <code>/settlement/payout</code></td>\n<td>TenantOwner</td>\n<td>Inter-branch settlement</td>\n</tr>\n</tbody></table>\n<h2 id=\"kiosk-device-token--public-menu\">Kiosk (device token) &amp; public menu</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Auth</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/kiosk/menu</code> · <code>/kiosk/queue-status</code> · POST <code>/kiosk/join-queue</code></td>\n<td>Public</td>\n<td>eMenu, queue lookup, join queue</td>\n</tr>\n<tr>\n<td>GET <code>/kiosk/vehicle-brands</code> · <code>/kiosk/identify</code> · POST <code>/kiosk/orders</code> · <code>/kiosk/orders/:id/charge</code> · GET <code>/kiosk/orders/:id/status</code></td>\n<td>Kiosk token</td>\n<td>Self-order + pay</td>\n</tr>\n<tr>\n<td>GET/POST <code>/kiosk-devices</code> · PATCH <code>/kiosk-devices/:id/active</code></td>\n<td>OutletAdmin</td>\n<td>Provision kiosks</td>\n</tr>\n</tbody></table>\n<h2 id=\"customer-portal\">Customer portal</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Auth</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>POST <code>/portal/otp/request</code> · <code>/portal/otp/verify</code></td>\n<td>Public</td>\n<td>WhatsApp-OTP login</td>\n</tr>\n<tr>\n<td>GET <code>/portal/me</code> · <code>/portal/orders</code> · <code>/portal/branches</code> · <code>/portal/queue</code> · <code>/portal/plans</code></td>\n<td>Portal</td>\n<td>Account, history, branches, live queue, plans</td>\n</tr>\n<tr>\n<td>POST <code>/portal/renew</code> · GET <code>/portal/renew/status</code></td>\n<td>Portal</td>\n<td>Online QRIS renewal</td>\n</tr>\n<tr>\n<td>POST/GET <code>/portal/bookings</code></td>\n<td>Portal</td>\n<td>Request/list bookings</td>\n</tr>\n<tr>\n<td>GET <code>/public/bookings/:token</code> · POST <code>/public/bookings/:token/{confirm,reject}</code></td>\n<td>Public (token)</td>\n<td>Cashier confirm/reject link</td>\n</tr>\n</tbody></table>\n<h2 id=\"ai-whatsapp--bridge\">AI, WhatsApp &amp; bridge</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET <code>/agent/tools</code></td>\n<td>Public</td>\n<td>Tool catalog</td>\n</tr>\n<tr>\n<td>POST <code>/agent/chat</code> · GET <code>/agent/chat/sessions[/:id]</code> · POST <code>/agent/validate-connection</code> · GET <code>/agent/monitoring/{summary,recent,events}</code></td>\n<td>Auth</td>\n<td>Co-pilot chat + monitoring</td>\n</tr>\n<tr>\n<td>GET <code>/agent/:tenantId/proposals</code> · POST <code>…/proposals/:id/{approve,reject}</code></td>\n<td>TenantOwner</td>\n<td>AI action proposals</td>\n</tr>\n<tr>\n<td>GET/PUT <code>/agent-config</code></td>\n<td>TenantOwner</td>\n<td>WhatsApp/AI agent config</td>\n</tr>\n<tr>\n<td>GET/POST <code>/agents</code> · PUT/DELETE <code>/agents/:id</code></td>\n<td>TenantOwner</td>\n<td>Agent personas</td>\n</tr>\n<tr>\n<td>GET/PUT <code>/branding</code> · PUT/DELETE <code>/branding/logo</code> · GET <code>/branding/me</code></td>\n<td>Auth read / TenantOwner write</td>\n<td>Branding</td>\n</tr>\n<tr>\n<td>GET <code>/public/branding</code> · <code>/public/branding/logo</code></td>\n<td>Public</td>\n<td>Public branding (default on unknown tenant)</td>\n</tr>\n<tr>\n<td>POST <code>/whatsapp/webhook</code></td>\n<td>Public</td>\n<td>WAHA/Kapso inbound webhook</td>\n</tr>\n<tr>\n<td>GET <code>/whatsapp/status</code> · POST <code>/whatsapp/connect</code> · GET <code>/whatsapp/qr</code> · conversations endpoints · POST <code>/whatsapp/simulate-inbound</code></td>\n<td>TenantOwner</td>\n<td>WhatsApp connect + conversation log</td>\n</tr>\n<tr>\n<td>GET/POST/PUT/PATCH/DELETE <code>/agent-flows[/:id]</code></td>\n<td>SuperAdmin</td>\n<td>n8n flow catalog</td>\n</tr>\n<tr>\n<td>GET/PUT <code>/agent-flow-selection</code> · GET <code>/agent-flow-selection/available</code> · POST <code>/agent-flow-selection/token</code></td>\n<td>TenantOwner</td>\n<td>Tenant flow selection + bridge token</td>\n</tr>\n<tr>\n<td>POST <code>/bridge/{context,llm,tool,whatsapp/send}</code></td>\n<td>Bridge token</td>\n<td>n8n callback surface</td>\n</tr>\n</tbody></table>\n<h2 id=\"config-invoices-bays-audit\">Config, invoices, bays, audit</h2>\n<table>\n<thead>\n<tr>\n<th>Method · Path</th>\n<th>Role</th>\n<th>Purpose</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>GET/PATCH <code>/settings/:tenantId</code></td>\n<td>TenantOwner</td>\n<td>Automation settings (secrets encrypted)</td>\n</tr>\n<tr>\n<td>GET <code>/modules/me</code></td>\n<td>Auth</td>\n<td>Enabled-module map</td>\n</tr>\n<tr>\n<td>POST/GET <code>/invoices</code> · GET/PUT/DELETE <code>/invoices/:id</code> · GET <code>/invoices/:id/pdf</code> · GET/PUT <code>/receipt-templates</code></td>\n<td>Auth</td>\n<td>Invoices + receipt template</td>\n</tr>\n<tr>\n<td>GET <code>/bays</code> · <code>/bays/:id</code> · POST <code>/bays/:id/{assign,gate-open}</code> · PATCH <code>/bays/:id/status</code></td>\n<td>Auth</td>\n<td>Wash-bay control</td>\n</tr>\n<tr>\n<td>GET <code>/audit-logs</code></td>\n<td>Auth</td>\n<td>Tenant-scoped audit trail</td>\n</tr>\n<tr>\n<td>GET <code>/discovery/:tenantId/*</code> · GET <code>/cctv/*</code></td>\n<td>TenantOwner / Auth</td>\n<td>Device discovery / CCTV (partly stubbed)</td>\n</tr>\n<tr>\n<td></content></td>\n<td></td>\n<td></td>\n</tr>\n</tbody></table>\n"},{"slug":"tech-membership-lifecycle","title":"06 · Membership — End-to-End Flow & Cycle","category":"tech","audience":"Technical","blurb":"Membership sale → activation → grace → renewal, end to end.","order":9,"words":1466,"minutes":7,"toc":[{"id":"1-the-status-cycle","text":"1. The status cycle","level":2},{"id":"two-mechanisms-keep-status-correct-and-they-agree","text":"Two mechanisms keep status correct (and they agree)","level":3},{"id":"the-hard-benefit-guard","text":"The hard benefit guard","level":3},{"id":"event-history","text":"Event history","level":3},{"id":"2-selling-a-membership","text":"2. Selling a membership","level":2},{"id":"3-everyday-use--how-benefits-apply-on-an-order","text":"3. Everyday use — how benefits apply on an order","level":2},{"id":"4-expiry--grace--revoked-and-renewal","text":"4. Expiry → grace → revoked, and renewal","level":2},{"id":"the-window","text":"The window","level":3},{"id":"renewal-is-two-phase-payment-safe","text":"Renewal is two-phase (payment-safe)","level":3},{"id":"where-renewal-is-initiated","text":"Where renewal is initiated","level":3},{"id":"5-membership-identity-the-12-char-number","text":"5. Membership identity (the 12-char number)","level":2},{"id":"6-the-full-lifecycle-at-a-glance-customer-journey","text":"6. The full lifecycle at a glance (customer journey)","level":2}],"html":"<h1 id=\"06--membership--end-to-end-flow--cycle\">06 · Membership — End-to-End Flow &amp; Cycle</h1>\n<p>This is the definitive description of how a membership is born, used, expires, and is renewed —\nfrom the sales counter through daily life to the customer&#39;s own portal. It ties together the\n<code>membership</code>, <code>membership-card</code>, <code>order</code>, <code>payment</code>, <code>settlement</code>, <code>portal</code>, and <code>kiosk</code> modules.</p>\n<hr>\n<h2 id=\"1-the-status-cycle\">1. The status cycle</h2>\n<p>A membership moves through a small, strict set of statuses. Two of them (<code>suspended</code>,\n<code>cancelled</code>) are <strong>manual</strong> and date-independent; the rest are <strong>date-driven</strong>.</p>\n<pre><code>                 sell                 activate (+plates, +payment)\n   (none) ─────────────► pending ──────────────────────────────► active\n                                                                    │\n                              end_date passes                       │\n                                                                    ▼\n                                                      grace  (H+1 … H+14, renewable,\n                                                              NO benefits)\n                                                                    │\n                              H+15 (past grace window)              │\n                                                                    ▼\n                                                      revoked (terminal — must buy new)\n\n   active ──(admin block)──► suspended ──(admin)──► active\n   active/pending ──(admin)──► cancelled  (terminal)\n</code></pre>\n<table>\n<thead>\n<tr>\n<th>Status</th>\n<th>Meaning</th>\n<th>Benefits?</th>\n<th>Renewable?</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>pending</code></td>\n<td>Sold but not yet activated/paid</td>\n<td>No</td>\n<td>—</td>\n</tr>\n<tr>\n<td><code>active</code></td>\n<td>Within the paid period (<code>today ≤ end_date</code>), not suspended</td>\n<td><strong>Yes</strong></td>\n<td>Yes (extend)</td>\n</tr>\n<tr>\n<td><code>grace</code></td>\n<td>Paid period ended, within <strong>H+1 … H+14</strong></td>\n<td><strong>No</strong></td>\n<td>Yes (extend)</td>\n</tr>\n<tr>\n<td><code>revoked</code></td>\n<td>Past <strong>H+14</strong> (i.e. H+15+) — terminal</td>\n<td>No</td>\n<td>No — new membership required</td>\n</tr>\n<tr>\n<td><code>suspended</code></td>\n<td>Manual block by outlet-admin+ (rule breach), still within paid duration</td>\n<td>No</td>\n<td>On reactivate</td>\n</tr>\n<tr>\n<td><code>cancelled</code></td>\n<td>Manual/terminal</td>\n<td>No</td>\n<td>No</td>\n</tr>\n<tr>\n<td><code>expired</code></td>\n<td>Legacy label; the live engine emits grace/revoked, never &quot;expired&quot;</td>\n<td>No</td>\n<td>—</td>\n</tr>\n</tbody></table>\n<p><code>MEMBERSHIP_GRACE_DAYS = 14</code> (in <code>@aire/shared</code>). &quot;H&quot; = the day after <code>end_date</code>.</p>\n<h3 id=\"two-mechanisms-keep-status-correct-and-they-agree\">Two mechanisms keep status correct (and they agree)</h3>\n<ol>\n<li><strong>Read-time truth</strong> — <code>MembershipLifecycleService.derive(storedStatus, endDate, now)</code> is called\non every read path (member lookup, CRM list, kiosk identify, portal <code>me</code>). Manual statuses\n(<code>pending</code>/<code>cancelled</code>/<code>suspended</code>) pass through unchanged; otherwise it computes\n<code>active</code>/<code>grace</code>/<code>revoked</code> purely from dates. So a row still stored <code>active</code> past its end date\nnever <em>displays</em> as active.</li>\n<li><strong>Write-time job</strong> — <code>runTransitions()</code> runs at boot and every <strong>6 hours</strong> (a plain\n<code>setInterval</code>, no <code>@nestjs/schedule</code>, <code>.unref()</code>-ed, guarded against overlap). It writes\n<code>active → grace</code> and <code>active/grace → revoked</code> for date-crossed rows, sets <code>grace_until</code> /\n<code>revoked_at</code>, and appends <code>membership_events</code> (<code>entered_grace</code>, <code>revoked</code>).</li>\n</ol>\n<h3 id=\"the-hard-benefit-guard\">The hard benefit guard</h3>\n<p>Regardless of the stored status label, benefits are granted <strong>only</strong> when\n<code>status = &#39;active&#39; AND end_date &gt;= CURRENT_DATE</code> (<code>OrderService.getMembershipBenefits</code>). This is\nthe single gate that makes a stale/grace/revoked/suspended membership grant nothing at POS — even\nin the gap between transition-job runs.</p>\n<h3 id=\"event-history\">Event history</h3>\n<p>Every meaningful transition appends a <code>membership_events</code> row (<code>activated</code>, <code>renewed</code>,\n<code>entered_grace</code>, <code>revoked</code>, <code>suspended</code>, <code>reactivated</code>, <code>cancelled</code>, <code>payment</code>, <code>usage</code>) with an\n<code>actor</code> and a JSON payload. The CRM &quot;History&quot; modal and the portal both read from it.</p>\n<hr>\n<h2 id=\"2-selling-a-membership\">2. Selling a membership</h2>\n<p>Since 2026-07-30 the POS sells a plan from the <strong>New Order → Membership &amp; Vouchers</strong> tab, on the\nsame order as the wash. <code>POST /api/orders</code> takes <code>membershipPlanId</code> and, in one transaction, adds\na <code>membership_plan</code> line (migration 089), creates the <strong><code>status=&#39;pending&#39;</code></strong> membership snapshotting\nthe plan&#39;s <code>max_uses</code> / <code>daily_limit</code> against that <code>order_id</code>, and points the order at it. Only\n<strong>one membership plan per order</strong> is allowed.</p>\n<p><strong>Counter upsell:</strong> when the same order also has <code>car_wash</code> lines, those lines are zeroed and\nflagged as member pricing, so the customer&#39;s wash that day is free and payment consumes one usage.\nThe order is tagged <code>new_member</code> (plus <code>member</code>), which is what makes the upsell legible in reports.</p>\n<p><code>POST /api/memberships/sell</code> still exists for callers that mint their own fee order (CRM, portal):</p>\n<ol>\n<li><strong><code>POST /api/memberships/sell</code></strong> — in one transaction: upsert the customer, create a <strong>pending\nfee order</strong> for the plan price (tagged <code>Membership: &lt;plan&gt;</code>), and insert a\n<strong><code>status=&#39;pending&#39;</code></strong> membership snapshotting the plan&#39;s <code>max_uses</code> / <code>daily_limit</code>, tied to\nthat <code>order_id</code>. Returns <code>{ order, membershipId, maxPlates, planName }</code>.</li>\n<li><strong>Pay</strong> the fee order through the normal POS payment flow (cash / QRIS / EDC / transfer).</li>\n<li><strong><code>POST /api/memberships/:id/activate</code></strong> — requires <strong>at least one vehicle plate</strong> (up to the\nplan&#39;s <code>max_plates</code>, default 3). It sets <code>start_date = today</code>,\n<code>end_date = today + duration_months</code>, <code>status = &#39;active&#39;</code>, registers the plates (normalized),\n<strong>issues the membership number</strong> (see §5), schedules expiry reminders, and emits\n<code>MembershipActivated</code>.</li>\n</ol>\n<blockquote>\n<p>Plans have durations restricted to 1, 3, 6, or 12 months and carry <code>free_service_ids</code> (e.g. a daily\nfree wash), <code>discounted_services</code>, <code>max_plates</code>, <code>daily_limit</code>, <code>settlement_amount</code>, and an\noptional WhatsApp welcome.</p>\n</blockquote>\n<hr>\n<h2 id=\"3-everyday-use--how-benefits-apply-on-an-order\">3. Everyday use — how benefits apply on an order</h2>\n<p>When an order carries a <code>membershipId</code> (attached by POS &quot;Find member&quot;, kiosk identify, or queue\nprefill — <strong>only if the membership is genuinely active</strong>):</p>\n<ol>\n<li><code>getMembershipBenefits(membershipId)</code> runs the hard guard (<code>active</code> + <code>end_date &gt;= today</code>).\nGrace/revoked/suspended/expired → no benefits, no <code>membershipId</code> attached.</li>\n<li>If active, the plan&#39;s <code>free_service_ids</code> and <code>discounted_services</code> rewrite the cart line\ndiscounts (<code>applyMembershipPricing</code>), and the order captures the membership&#39;s <code>home_outlet_id</code>\nand the plan&#39;s <code>settlement_amount</code>.</li>\n<li>On order commit: a <code>membership_usages</code> row is written and <code>uses_count</code> is incremented (subject\nto <code>max_uses</code> / <code>daily_limit</code>).</li>\n<li><strong>Cross-branch settlement:</strong> if the wash was redeemed at a branch other than the member&#39;s\n<code>home_outlet_id</code> and <code>settlement_amount &gt; 0</code>, a <code>settlement_entries</code> row is written (home\nbranch owes serving branch). The <code>settlement</code> module later nets and pays these out\n(<code>settlement_payouts</code>).</li>\n</ol>\n<p>The <strong>member card</strong> (designed in <code>/dashboard/membership-card</code>) renders the member&#39;s number as\nplain text, a barcode, or a QR (<code>idType</code>), over a background stored in MinIO. It&#39;s shown in the\nkiosk &quot;welcome back&quot;, the CRM history modal, and the customer portal. Hardware keyboard-wedge\nscanners work by typing the 12-char number into POS &quot;Find member&quot;.</p>\n<hr>\n<h2 id=\"4-expiry--grace--revoked-and-renewal\">4. Expiry → grace → revoked, and renewal</h2>\n<h3 id=\"the-window\">The window</h3>\n<ul>\n<li>On <code>end_date</code>, the membership is still active through end-of-day.</li>\n<li><strong>H+1 … H+14</strong> it is <code>grace</code>: still visible, <strong>no benefits</strong>, but <strong>renewable by extension</strong>.</li>\n<li><strong>H+15+</strong> it is <code>revoked</code>: terminal; the customer must buy a <strong>new</strong> membership.</li>\n</ul>\n<h3 id=\"renewal-is-two-phase-payment-safe\">Renewal is two-phase (payment-safe)</h3>\n<ol>\n<li><strong>Start</strong> — <code>POST /api/memberships/:id/renew</code> (or the portal&#39;s online path) creates a <strong>renewal\nfee order</strong> and a <strong>pending <code>membership_renewals</code></strong> row <code>(order_id UNIQUE, membership_id, plan_id, applied=false)</code>. <strong>The membership is NOT extended yet.</strong></li>\n<li><strong>Pay</strong> the fee order.</li>\n<li><strong>Apply</strong> — <code>POST /api/memberships/apply-renewal { orderId }</code> verifies the order is paid, then:<ul>\n<li><strong>Extend</strong> if a membership with the <strong>same plan</strong> is <code>active</code> or <code>grace</code>:\n<code>new end_date = existing end_date + duration_months</code> (extends from current expiry, not today),\nstatus back to <code>active</code>, clears <code>grace_until</code>/<code>revoked_at</code>. → <strong>grace memberships extend.</strong></li>\n<li><strong>New parallel</strong> otherwise — different plan, or a <strong>revoked/absent</strong> membership (revoked is\npast the renewable window): a brand-new <code>active</code> membership from today.</li>\n<li>Marks the renewal <code>applied=true</code>. Idempotent (re-applying is a no-op). Records a <code>renewed</code>\nevent.</li>\n</ul>\n</li>\n</ol>\n<p>This two-phase design means an unpaid renewal never silently extends a membership; the extension\nonly happens once money is confirmed.</p>\n<h3 id=\"where-renewal-is-initiated\">Where renewal is initiated</h3>\n<ul>\n<li><strong>POS New Order → Find member → Renew &amp; pay</strong> — look up by plate/phone/number → pick the plan →\nrenew → pay → apply.</li>\n<li><strong>CRM → Renew</strong> modal — same, with in-modal payment collection.</li>\n<li><strong>Customer portal → Renew</strong> — online: <code>POST /portal/renew</code> creates the fee order + a <strong>QRIS</strong>\ncharge; the app polls <code>/portal/renew/status</code> and applies the renewal once the charge is paid.\n(It reuses the staff renewal machinery via a synthesized per-tenant system operator so the fee\norder has a valid creator/branch.)</li>\n</ul>\n<hr>\n<h2 id=\"5-membership-identity-the-12-char-number\">5. Membership identity (the 12-char number)</h2>\n<p>Every member gets a stable <strong>12-character base-36</strong> number:</p>\n<pre><code>  TTTTTT      BB       CCCC\n  tenant   branch   customer\n (global) (per-    (per-branch)\n          tenant)\n</code></pre>\n<ul>\n<li><code>tenant_code</code> (6) is globally unique, assigned at tenant creation (<code>MAX+1</code>, retry-on-race).</li>\n<li><code>branch_code</code> (2) is unique per tenant.</li>\n<li><code>customer_code</code> (4) is unique per <code>(tenant, registered branch)</code>.</li>\n</ul>\n<p>Allocation is <strong>lazy</strong> (at first activation) and <strong>reused</strong> across renewals — a customer keeps\ntheir number for life. Fixed-width zero-padding makes lexical order equal numeric order, so\n&quot;next code&quot; is just <code>MAX(code)+1</code>. <code>backfill-numbers</code> assigns numbers to pre-identity members.\nLookup by number powers POS &quot;Find member&quot;, kiosk identify, and scanners.</p>\n<hr>\n<h2 id=\"6-the-full-lifecycle-at-a-glance-customer-journey\">6. The full lifecycle at a glance (customer journey)</h2>\n<ol>\n<li><strong>Buy</strong> — customer buys a plan at the counter (or a cashier sells it). Fee order paid, plates\nregistered, membership <strong>active</strong>, number issued, welcome sent.</li>\n<li><strong>Use</strong> — each visit: staff or kiosk identifies the member (plate / phone / number / card\nscan); active benefits apply (free/discounted services); usage + quota tracked; cross-branch\nwashes accrue settlement.</li>\n<li><strong>Self-serve</strong> — the customer logs into the <strong>portal</strong> with a WhatsApp OTP to see their card,\nstatus, vehicles, vouchers, visit history, live branch queue, and to <strong>book</strong> or <strong>renew</strong>.</li>\n<li><strong>Lapse</strong> — at <code>end_date</code> the membership enters <strong>grace</strong> (renewable, no benefits) for 14 days,\nthen <strong>revoked</strong>. The transition job + read-time derive keep the status honest; the benefit\nguard ensures no free washes leak during grace/after revoke.</li>\n<li><strong>Renew</strong> — during active/grace the customer (portal) or staff (POS/CRM) renews by extension\n(pay → apply). After revoke, they buy a new membership. Either way the number and history carry\nforward.</content></li>\n</ol>\n"},{"slug":"tech-branch-bridge-protocol","title":"Branch Bridge Protocol (IoT / CCTV on-prem agent)","category":"tech","audience":"Technical","blurb":"On-premise branch bridge: discovery and CCTV.","order":10,"words":814,"minutes":4,"toc":[{"id":"pairing--auth","text":"Pairing & auth","level":2},{"id":"socket-events","text":"Socket events","level":2},{"id":"cloud--agent","text":"Cloud → Agent","level":3},{"id":"agent--cloud","text":"Agent → Cloud","level":3},{"id":"live-cctv-serving-browser","text":"Live CCTV serving (browser)","level":2},{"id":"recording-history","text":"Recording history","level":2},{"id":"scan-wizard-flow-frontend","text":"Scan wizard flow (frontend)","level":2},{"id":"conventions","text":"Conventions","level":2}],"html":"<h1 id=\"branch-bridge-protocol-iot--cctv-on-prem-agent\">Branch Bridge Protocol (IoT / CCTV on-prem agent)</h1>\n<p>The <strong>Branch Bridge Agent</strong> (<code>apps/branch-bridge</code>) runs on the tenant&#39;s LAN at a\nbranch (POS PC, Raspberry Pi, or mini-PC). It is the only thing that can see the\nbranch&#39;s cameras and IoT controllers — the cloud VPS cannot reach a private LAN.\nThe agent holds ONE <strong>outbound</strong> Socket.IO connection to the cloud backend, so no\ninbound port-forwarding is ever required.</p>\n<p>Cloud never scans or streams directly. It <strong>dispatches</strong> work to the bridge and\nthe bridge streams results/video back up the same socket.</p>\n<pre><code>Branch LAN                                   Cloud (backend :4000)\n┌──────────────────────────┐  outbound WS   ┌───────────────────────────┐\n│ branch-bridge agent       │◀──────────────▶│ BridgeGateway  ns=/bridge │\n│  ONVIF / mDNS / SSDP scan │                │ DiscoveryService dispatch │\n│  ffmpeg RTSP→HLS relay    │──segments─────▶│ CctvService live+history  │\n│  local MQTT ⇄ bay sensors │                │ RealtimeGateway (bay evt) │\n└──────────────────────────┘                └───────────────────────────┘\n</code></pre>\n<h2 id=\"pairing--auth\">Pairing &amp; auth</h2>\n<ul>\n<li>A Tenant_Owner creates a bridge for a branch in the UI. Backend inserts a\n<code>branch_bridges</code> row with a random opaque <code>pairing_token</code> (VARCHAR 64, unique)\nand returns it once, plus an install command.</li>\n<li>The agent is started with <code>AIRE_CLOUD_URL</code> + <code>AIRE_BRIDGE_TOKEN</code>.</li>\n<li>The agent connects: <code>io(</code>${cloudUrl}/bridge<code>, { auth: { token } })</code>.</li>\n<li><code>BridgeGateway.handleConnection</code> looks up the token → resolves\n<code>{ bridgeId, tenantId, outletId }</code>. Invalid token → <code>client.disconnect(true)</code>.</li>\n<li>On connect the gateway marks the bridge <code>online</code> + updates <code>last_seen_at</code>, and\ntracks <code>bridgeId → socketId</code>. On disconnect → <code>offline</code>.</li>\n<li>All downstream data is scoped to the resolved tenant+outlet server-side; the\nagent can never widen scope (same guarantee as the n8n <code>bridge_token</code>).</li>\n</ul>\n<h2 id=\"socket-events\">Socket events</h2>\n<h3 id=\"cloud--agent\">Cloud → Agent</h3>\n<table>\n<thead>\n<tr>\n<th>event</th>\n<th>payload</th>\n<th>agent action</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>scan</code></td>\n<td><code>{ scanId: string, protocols?: string[] }</code></td>\n<td>Run LAN scan; stream each device via <code>device</code>; finish with <code>scan:done</code>.</td>\n</tr>\n<tr>\n<td><code>configure</code></td>\n<td><code>{ deviceId, device_type, connection_params }</code></td>\n<td>Camera → validate RTSP + start HLS relay. iot_controller → subscribe local MQTT topic. Reply <code>configure:result</code>.</td>\n</tr>\n<tr>\n<td><code>stream:start</code></td>\n<td><code>{ cameraId, rtspUrl }</code></td>\n<td>Start ffmpeg RTSP→HLS; emit <code>hls:playlist</code> + <code>hls:segment</code>.</td>\n</tr>\n<tr>\n<td><code>stream:stop</code></td>\n<td><code>{ cameraId }</code></td>\n<td>Kill ffmpeg for that camera.</td>\n</tr>\n<tr>\n<td><code>command</code></td>\n<td><code>{ bayId, action }</code> action ∈ gate_open|gate_close|start_wash|stop_wash|emergency_stop</td>\n<td>Publish to local MQTT command topic.</td>\n</tr>\n</tbody></table>\n<h3 id=\"agent--cloud\">Agent → Cloud</h3>\n<table>\n<thead>\n<tr>\n<th>event</th>\n<th>payload</th>\n<th>cloud action</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>device</code></td>\n<td><code>{ scanId, device: DiscoveredDeviceInput }</code></td>\n<td>Upsert into scan buffer for the scanId.</td>\n</tr>\n<tr>\n<td><code>scan:done</code></td>\n<td><code>{ scanId, count, errors: {protocol,message}[] }</code></td>\n<td>Resolve the pending scan; persist devices to tenant settings scoped to this bridge&#39;s outlet.</td>\n</tr>\n<tr>\n<td><code>configure:result</code></td>\n<td><code>{ deviceId, ok: boolean, error?: string, connection_params?: object }</code></td>\n<td>Resolve pending confirm; persist connection_params.</td>\n</tr>\n<tr>\n<td><code>hls:playlist</code></td>\n<td><code>{ cameraId, m3u8: string }</code></td>\n<td>Store latest live playlist for camera.</td>\n</tr>\n<tr>\n<td><code>hls:segment</code></td>\n<td><code>{ cameraId, name: string, dataB64: string, durationSec: number, seq: number }</code></td>\n<td>Push into per-camera ring buffer; if recording, also persist to MinIO.</td>\n</tr>\n<tr>\n<td><code>sensor</code></td>\n<td><code>{ bayId, vehiclePresent, waterFlow, foamLevel, machineStatus, timestamp }</code></td>\n<td>Update <code>bays.sensor_data</code> + <code>RealtimeGateway.emitBayStatusChanged</code>.</td>\n</tr>\n<tr>\n<td><code>heartbeat</code></td>\n<td><code>{ ts, cameras: string[], devices: string[] }</code></td>\n<td>Update <code>last_seen_at</code>, online device set.</td>\n</tr>\n</tbody></table>\n<p><code>DiscoveredDeviceInput</code> = <code>{ ip_address, device_type: &#39;camera&#39;|&#39;iot_controller&#39;|&#39;router&#39;, manufacturer: string|null, model: string|null, connection_params?: object }</code>.\nThe cloud assigns <code>device_id</code> (uuid), <code>suggested_label</code>, <code>status</code>, timestamps.</p>\n<h2 id=\"live-cctv-serving-browser\">Live CCTV serving (browser)</h2>\n<p>HLS is pull-based, so &quot;live&quot; needs no browser socket:</p>\n<ul>\n<li>Agent relays segments up; backend keeps the last N (~6) segments per camera in\nmemory + the rolling <code>live.m3u8</code>.</li>\n<li>Backend serves (JWT-guarded, tenant-scoped):<ul>\n<li><code>GET /api/cctv/cameras/:id/live.m3u8</code> → current live playlist</li>\n<li><code>GET /api/cctv/cameras/:id/seg/:name</code> → a segment (mpegts)</li>\n</ul>\n</li>\n<li>Frontend plays with hls.js (<code>&lt;video&gt;</code>), Safari uses native HLS.</li>\n</ul>\n<h2 id=\"recording-history\">Recording history</h2>\n<ul>\n<li><code>POST /api/cctv/cameras/:id/record { orderId? }</code> → create <code>camera_recordings</code>\nrow (status=recording); backend starts persisting that camera&#39;s incoming\nsegments to MinIO under <code>recordings/{cameraId}/{recordingId}/</code>.</li>\n<li><code>DELETE /api/cctv/recordings/:id</code> → stop; write a VOD <code>index.m3u8</code> listing the\nstored segments; set status=completed, duration, storage_path.</li>\n<li><code>GET /api/cctv/recordings?outletId=&amp;cameraId=</code> → history list.</li>\n<li><code>GET /api/cctv/recordings/:id/index.m3u8</code> + <code>/seg/:name</code> → VOD playback (hls.js).</li>\n</ul>\n<h2 id=\"scan-wizard-flow-frontend\">Scan wizard flow (frontend)</h2>\n<ol>\n<li><strong>Branch &amp; bridge</strong> — pick outlet; show its bridge status (online/offline). If\nno bridge, offer &quot;Add bridge&quot; (token + install command). Block scan if offline.</li>\n<li><strong>Scanning</strong> — <code>POST /api/discovery/:tenantId/scan { outletId }</code> returns\n<code>{ scanId }</code>; poll <code>GET /api/discovery/:tenantId/scan/:scanId</code> for\n<code>{ status, devices }</code> until <code>done</code>; show devices as they arrive.</li>\n<li><strong>Review</strong> — list found devices (type, ip, label).</li>\n<li><strong>Configure</strong> — per device: assign outlet (default = scanned outlet) + bay\n(cameras optional); <code>POST .../devices/:deviceId/confirm</code> triggers bridge\nauto-config; show ✓/✗ per device.</li>\n<li><strong>Done</strong> — summary; cameras link to the live CCTV page.</li>\n</ol>\n<h2 id=\"conventions\">Conventions</h2>\n<ul>\n<li>Standalone agent app mirrors <code>apps/iot-gateway</code> packaging (own package.json +\npackage-lock, outside the pnpm workspace, own Dockerfile, tsc build).</li>\n<li>Keep DTOs local to modules / duplicated in <code>frontend/src/lib</code>; do NOT modify\n<code>@aire/shared</code> (avoids the shared-dist rebuild gotcha).</li>\n<li>MQTT topics reuse the existing scheme:\n<code>aire/{tenantId}/{outletId}/bay/{bayId}/{sensor|command}</code>.</li>\n</ul>\n"},{"slug":"tech-device-registry-topology","title":"Device Registry + Global Topology","category":"tech","audience":"Technical","blurb":"Device registry and per-branch network topology.","order":11,"words":1013,"minutes":5,"toc":[{"id":"data-model--migration-054_branch_devicessql","text":"Data model — migration 054_branch_devices.sql","level":2},{"id":"registration-sources-who-writes-branch_devices","text":"Registration sources (who writes branch_devices)","level":3},{"id":"backend--modulesdevice-registry","text":"Backend — modules/device-registry","level":2},{"id":"topology-json-the-contract-the-frontend-renders","text":"Topology JSON (the contract the frontend renders)","level":3},{"id":"frontend","text":"Frontend","level":2},{"id":"topology-page-dashboardtopology-the-centerpiece","text":"Topology page /dashboard/topology (the centerpiece)","level":3},{"id":"devices-registry-page-dashboarddevices","text":"Devices registry page /dashboard/devices","level":3},{"id":"shared-devicedetailmodal","text":"Shared DeviceDetailModal","level":3},{"id":"cctv-page-dashboardcctv-enhance","text":"CCTV page /dashboard/cctv (enhance)","level":3},{"id":"branch-install-flow-phase-1--bridgeinstallwizard","text":"Branch install flow (Phase 1) — BridgeInstallWizard","level":3},{"id":"phasing","text":"Phasing","level":2},{"id":"conventions","text":"Conventions","level":2}],"html":"<h1 id=\"device-registry--global-topology\">Device Registry + Global Topology</h1>\n<p>Turns the branch-bridge into a <strong>branch edge controller</strong>: every LAN device\n(camera, bay controller, printer, kiosk, POS terminal, router) is registered\nonce and then permanently managed + monitored from the cloud — globally and\nper-branch. Builds on <a href=\"/docs/tech-branch-bridge-protocol\">07-branch-bridge-protocol.md</a>.</p>\n<h2 id=\"data-model--migration-054_branch_devicessql\">Data model — migration <code>054_branch_devices.sql</code></h2>\n<p><code>branch_devices</code> = the unified registry (single source of truth for the registry\nUI + topology). Specialized tables (<code>cameras</code>, <code>pos_devices</code>, <code>kiosk_devices</code>)\nkeep their type-specific columns and are linked via <code>ref_id</code>.</p>\n<pre><code>branch_devices(\n  id uuid pk,\n  tenant_id uuid not null -&gt; tenants,\n  outlet_id uuid not null -&gt; outlets,\n  bridge_id uuid -&gt; branch_bridges (null ok; some devices are cloud-direct),\n  category varchar(24) not null,   -- camera|controller|printer|kiosk|pos_terminal|router|other\n  name     varchar(160) not null,\n  vendor   varchar(120), model varchar(120),\n  ip_address varchar(64), mac_address varchar(64),\n  ref_id   uuid,                   -- link to cameras.id / pos_devices.id / kiosk_devices.id\n  connection_params jsonb default &#39;{}&#39;,\n  status   varchar(16) not null default &#39;unconfigured&#39;,  -- online|offline|unconfigured\n  metadata jsonb default &#39;{}&#39;,\n  last_seen_at timestamptz,\n  created_at timestamptz default now(), updated_at timestamptz default now()\n);\n-- indexes: (outlet_id, category), (tenant_id, created_at desc),\n--          unique partial (bridge_id, ip_address) where ip_address is not null\n</code></pre>\n<h3 id=\"registration-sources-who-writes-branch_devices\">Registration sources (who writes branch_devices)</h3>\n<ul>\n<li><strong>Discovery confirm</strong> (<code>DiscoveryService.confirmDevice</code>): upsert a row —\n<code>iot_controller→controller</code>, <code>camera→camera</code> (ref_id = the <code>cameras.id</code> it\ncreated), <code>router→router</code>.</li>\n<li><strong>Heartbeat / bridge:offline</strong>: the bridge gateway marks a branch&#39;s devices\n<code>online</code> on heartbeat and <code>offline</code> on <code>bridge:offline</code> (reuse the existing\nevent). Cameras also flip via their stream state.</li>\n<li><strong>POS terminals / kiosks</strong>: the topology + registry read these from the\nexisting <code>pos_devices</code> / <code>kiosk_devices</code> tables (UNION into the tree) so they\nappear without a data migration; a later pass can mirror them into\nbranch_devices for uniform status.</li>\n</ul>\n<h2 id=\"backend--modulesdevice-registry\">Backend — <code>modules/device-registry</code></h2>\n<ul>\n<li><code>DeviceRegistryService</code>: <code>upsert(device)</code>, <code>listByOutlet(tenantId,{outletId?,category?})</code>,\n<code>get(tenantId,id)</code>, <code>setStatusForBridge(bridgeId,status)</code>, <code>remove(tenantId,id)</code>,\n<code>upsertFromDiscovery(tenantId, device, {bridgeId, refId?})</code>.</li>\n<li><code>TopologyService.build(tenantId, outletId?)</code> → nested tree (below).</li>\n<li><code>DeviceController</code> (JWT + tenant-scoped from JWT):<ul>\n<li><code>GET /api/topology</code>            → whole tenant tree</li>\n<li><code>GET /api/topology?outletId=</code>  → one branch subtree</li>\n<li><code>GET /api/devices?outletId=&amp;category=</code> → flat registry list</li>\n<li><code>GET /api/devices/:id</code>         → one device (+ camera stream refs when category=camera)</li>\n</ul>\n</li>\n<li>Installer download (Phase 1): <code>GET /api/bridges/:id/installer</code> streams the\nprebuilt package zip from <code>process.env.BRANCH_BRIDGE_PACKAGE</code> (a mounted path).\nIf unset → 503 with <code>{ needsPackage: true }</code> so the UI falls back to showing\nthe copy-paste command. (Token is shown in the modal regardless.)</li>\n</ul>\n<h3 id=\"topology-json-the-contract-the-frontend-renders\">Topology JSON (the contract the frontend renders)</h3>\n<pre><code class=\"language-jsonc\">{\n  &quot;tenant&quot;: { &quot;id&quot;: &quot;...&quot;, &quot;name&quot;: &quot;Airin Demo&quot; },\n  &quot;generatedAt&quot;: &quot;2026-07-12T...Z&quot;,\n  &quot;branches&quot;: [\n    {\n      &quot;outlet&quot;: { &quot;id&quot;: &quot;...&quot;, &quot;name&quot;: &quot;AIRE Bintaro&quot;, &quot;code&quot;: &quot;BTR&quot; },\n      &quot;bridge&quot;: { &quot;id&quot;: &quot;...&quot;, &quot;status&quot;: &quot;online&quot;, &quot;live&quot;: true, &quot;lastSeenAt&quot;: &quot;...&quot; } | null,\n      &quot;counts&quot;: { &quot;online&quot;: 3, &quot;offline&quot;: 1, &quot;total&quot;: 4 },\n      &quot;categories&quot;: [\n        { &quot;category&quot;: &quot;camera&quot;,\n          &quot;devices&quot;: [ { &quot;id&quot;,&quot;name&quot;,&quot;category&quot;,&quot;status&quot;,&quot;ipAddress&quot;,&quot;refId&quot;,&quot;vendor&quot;,&quot;model&quot;,&quot;lastSeenAt&quot; } ] },\n        { &quot;category&quot;: &quot;controller&quot;, &quot;devices&quot;: [ ... ] }\n        // printer | kiosk | pos_terminal | router | other\n      ]\n    }\n  ]\n}\n</code></pre>\n<p>Global view = all branches; branch view = one branch (still an array of length 1).</p>\n<h2 id=\"frontend\">Frontend</h2>\n<h3 id=\"topology-page-dashboardtopology-the-centerpiece\">Topology page <code>/dashboard/topology</code> (the centerpiece)</h3>\n<ul>\n<li><strong>Branch dropdown</strong> (top-right, same pattern as other pages): &quot;All branches&quot; →\nglobal tree; select one → that branch&#39;s subtree. Persist selection.</li>\n<li><strong>Animated tree</strong>, left→right hierarchy:\n<code>Tenant → Branch(es) → Bridge → Category groups → Device leaves</code>.\nGlobal view collapses each branch to its bridge + category counts (expandable);\nbranch view expands fully to individual devices.</li>\n<li><strong>Rendering</strong>: custom <strong>SVG</strong> (no heavy graph dep). Compute node positions with\na simple tiered layout; draw connectors as SVG paths (cubic béziers between\ntiers). <strong>Animated flow</strong>: connector lines use an animated <code>stroke-dashoffset</code>\n(CSS <code>@keyframes</code>) so a dash &quot;flows&quot; from parent→child on <em>online</em> links; static\ndim line for offline. Respect <code>prefers-reduced-motion</code>.</li>\n<li><strong>Status colors</strong> (use existing design tokens, not hardcoded hex): online =\nsuccess/green, offline = muted/gray, unconfigured = warning/amber. Node cards\nshow an icon per category (lucide: Cctv, Cpu, Printer, Monitor, Smartphone,\nRouter), name, ip, status dot.</li>\n<li><strong>Interaction</strong>: click a device node → the shared <strong>DeviceDetailModal</strong>. Pan\n(drag) + zoom (wheel/buttons) for large trees. Legend. Responsive (horizontal\nscroll container; never break page layout). Theme-aware (light/dark).</li>\n<li>Nav: add <strong>Topology</strong> under Operations (lucide <code>Waypoints</code> or <code>Network</code>).</li>\n</ul>\n<h3 id=\"devices-registry-page-dashboarddevices\">Devices registry page <code>/dashboard/devices</code></h3>\n<ul>\n<li>Branch dropdown + a category segmented control / grouped sections: Cameras,\nControllers, Printers, Kiosks, Terminals, Routers, Other.</li>\n<li>Device cards (name, category icon, ip, status, branch). Click → DeviceDetailModal.</li>\n<li>Empty states per category with a hint (&quot;Run Search devices to add …&quot;).</li>\n</ul>\n<h3 id=\"shared-devicedetailmodal\">Shared <code>DeviceDetailModal</code></h3>\n<ul>\n<li>Generic detail (category, ip/mac, vendor/model, status, last seen, connection\nparams, branch/bridge).</li>\n<li><strong>When category = camera</strong>: embed the <strong>live HlsPlayer</strong> + a <strong>recordings\n(history) list</strong> for that camera (reuse existing <code>/api/cctv/...</code>). This is the\n&quot;see one + history&quot; requirement.</li>\n</ul>\n<h3 id=\"cctv-page-dashboardcctv-enhance\">CCTV page <code>/dashboard/cctv</code> (enhance)</h3>\n<ul>\n<li>Keep the <strong>Live grid</strong> (&quot;see all&quot;) + <strong>History</strong> tab. Add <strong>&quot;see one&quot;</strong>:\nclicking a camera tile opens a focused large single-camera view (bigger player<ul>\n<li>that camera&#39;s recordings), or routes into DeviceDetailModal. Record toggle stays.</li>\n</ul>\n</li>\n</ul>\n<h3 id=\"branch-install-flow-phase-1--bridgeinstallwizard\">Branch install flow (Phase 1) — <code>BridgeInstallWizard</code></h3>\n<ul>\n<li>Entry: an <strong>&quot;Install branch agent&quot;</strong> button in the branch context (Branch\nBridges section and/or the topology branch view) shown when the branch has no\nonline bridge.</li>\n<li>Wizard/steps modal:<ol>\n<li>Ensure a bridge exists for the branch (create if needed → token).</li>\n<li><strong>Download installer</strong> button → <code>GET /api/bridges/:id/installer</code> (falls back\nto showing the copy-paste <code>installCommand</code> if the package isn&#39;t hosted).</li>\n<li>Instructions: extract → run as Administrator (Windows) / sudo (Linux) →\napprove the OS prompt.</li>\n<li><strong>Auto-detect</strong>: poll <code>GET /api/bridges</code> every ~3s; when this bridge flips\nto <code>live/online</code>, advance to &quot;Connected ✓&quot; and offer &quot;Scan devices now&quot;.</li>\n</ol>\n</li>\n<li>After connect, the branch view exposes a <strong>permanent &quot;Scan devices&quot;</strong> action\n(device registration stays open forever — rescan/add anytime).</li>\n</ul>\n<h2 id=\"phasing\">Phasing</h2>\n<ol>\n<li>Install-from-branch button + steps modal + auto-detect (Phase 1).</li>\n<li><code>branch_devices</code> registry + wiring + <code>/api/devices</code> + registry page (Phase 2).</li>\n<li><code>/api/topology</code> + the animated topology page + DeviceDetailModal + CCTV\nsingle-view (Phase 3 — the visualization).</li>\n</ol>\n<h2 id=\"conventions\">Conventions</h2>\n<ul>\n<li>camelCase DTOs; keep types in <code>frontend/src/lib</code> (do NOT touch <code>@aire/shared</code>).</li>\n<li>Tenant scope always from the JWT, never the request body.</li>\n<li>New nav items via the existing <code>t(&#39;nav.*&#39;, &#39;Fallback&#39;)</code> pattern + <code>id.ts</code> keys.</li>\n</ul>\n"},{"slug":"tech-n8n-agent-builder","title":"n8n Agent Builder — architecture & deployment","category":"tech","audience":"Technical","blurb":"The hosted n8n visual agent-builder integration.","order":12,"words":628,"minutes":3,"toc":[{"id":"how-it-fits-together","text":"How it fits together","level":2},{"id":"backend-pieces","text":"Backend pieces","level":2},{"id":"api-surface","text":"API surface","level":2},{"id":"deploy-steps-vps","text":"Deploy steps (VPS)","level":2},{"id":"tenant-setup","text":"Tenant setup","level":2},{"id":"safety-notes","text":"Safety notes","level":2}],"html":"<h1 id=\"n8n-agent-builder--architecture--deployment\">n8n Agent Builder — architecture &amp; deployment</h1>\n<p>Drag-and-drop agent flows, n8n-style. n8n is hosted on the VPS and is where the\n<strong>platform admin</strong> builds flows; tenants only <strong>select</strong> a flow, name their\nagents, and use their own LLM key. This keeps a single free n8n instance and\nrespects its Sustainable Use License (tenants never get n8n logins).</p>\n<h2 id=\"how-it-fits-together\">How it fits together</h2>\n<pre><code>Admin (flows.useairin.id, super-admin only) ── builds ──► n8n template flows\nTenant dashboard (choose + name + own key)  ── selects ─► agent_configs pointer\nInbound WA ─► WhatsappService.handleInbound\n              routing_mode=&#39;n8n&#39;? POST message + persona + bridge token ─► n8n flow\n                 n8n calls back ─► /api/bridge/{context,llm,tool,whatsapp/send}\n              else ─► built-in AgentRuntimeService  (also the fallback on failure)\n</code></pre>\n<p>The n8n flow is a <strong>template</strong> with <code>{{ … }}</code> placeholders; AIRE injects each\ntenant&#39;s persona/prompt/knowledge + their bridge token per message, so ONE flow\nserves every tenant. All guardrails (customer scoping, tool toggle/approval\ngating, tenant LLM keys + monitoring) stay server-side in the bridge — the flow\nonly orchestrates.</p>\n<h2 id=\"backend-pieces\">Backend pieces</h2>\n<ul>\n<li><strong>Migration <code>038_n8n_agent_flows.sql</code></strong> — <code>agent_flows</code> catalog + routing\ncolumns on <code>agent_configs</code> (<code>routing_mode</code>, <code>n8n_flow_id</code>,\n<code>n8n_automation_flow_id</code>, <code>bridge_token</code>).</li>\n<li><strong><code>modules/agent-bridge</code></strong> — <code>BridgeTokenGuard</code> (per-tenant token auth) + the\nfour bridge endpoints; <code>AgentFlowService</code> (catalog CRUD + tenant selection +\ntoken mint + persona snapshot); admin &amp; tenant controllers.</li>\n<li><strong><code>WhatsappService</code></strong> — <code>dispatchToN8n()</code> seam in <code>handleInbound</code> +\n<code>agentSend()</code> (used by the bridge to send + log replies).</li>\n</ul>\n<h2 id=\"api-surface\">API surface</h2>\n<table>\n<thead>\n<tr>\n<th>Endpoint</th>\n<th>Auth</th>\n<th>Who</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><code>POST /api/bridge/context|llm|tool|whatsapp/send|escalate</code></td>\n<td>bridge token</td>\n<td>n8n</td>\n</tr>\n<tr>\n<td><code>GET/POST/PUT/PATCH/DELETE /api/agent-flows</code></td>\n<td>JWT, super-admin</td>\n<td>admin catalog</td>\n</tr>\n<tr>\n<td><code>GET /api/agent-flow-selection[/available]</code>, <code>PUT</code>, <code>POST /token</code></td>\n<td>JWT, tenant owner</td>\n<td>tenant</td>\n</tr>\n</tbody></table>\n<p><code>POST /api/bridge/escalate</code> (<code>{ fromPhone, reason? }</code>) lets a flow hand a chat to a\nhuman exactly like the built-in runtime does: it marks the conversation escalated,\nacknowledges the customer, and notifies the tenant&#39;s escalation number. The\n<code>whatsapp/send</code> body also accepts an optional <code>persona</code> so replies are attributed\nto the right agent in the Conversation Log.</p>\n<p>The reference flow (<code>aire-whatsapp-assistant.json</code>) now demonstrates a <strong>Run Tool</strong>\nnode (live queue snapshot via the gated tool API) and an <strong>escalation branch</strong>: the\nprompt instructs the model to emit <code>[[ESCALATE]]</code> when it can&#39;t help, an IF node\nroutes that to the <strong>Escalate</strong> operation, everything else to <strong>Send WhatsApp</strong>.</p>\n<h2 id=\"deploy-steps-vps\">Deploy steps (VPS)</h2>\n<ol>\n<li><strong>.env</strong> — add <code>N8N_ENCRYPTION_KEY</code> (random 32+ chars), <code>N8N_PUBLIC_URL=https://flows.useairin.id</code>.\n<code>BRIDGE_CALLBACK_BASE</code> defaults to <code>http://backend:4000</code> (fine on the compose network).</li>\n<li><strong>Apply migration 038</strong> the usual way (psql + <code>schema_migrations</code> row — see\nthe deploy recipe; migrate.ts is not used on this box).</li>\n<li><strong>Build the node package</strong>: <code>cd integrations/n8n-nodes-aire &amp;&amp; npm i &amp;&amp; npm run build</code>.</li>\n<li><strong>DNS</strong>: point <code>flows.useairin.id</code> → the VPS IP.</li>\n<li><strong>TLS</strong>: <code>certbot certonly … -d flows.useairin.id</code>, then drop\n<code>infrastructure/nginx/conf.d/n8n.conf.example</code> → <code>n8n.conf</code> and reload nginx.</li>\n<li><strong>Bring up</strong>: <code>docker compose -f docker-compose.yml -f docker-compose.prod.yml up -d n8n</code>\nthen rebuild <code>backend</code> + <code>frontend</code>.</li>\n<li><strong>First run</strong>: open <code>flows.useairin.id</code>, create the n8n owner account\nimmediately (lock it down), import <code>integrations/n8n-nodes-aire/workflows/aire-whatsapp-assistant.json</code>.</li>\n<li><strong>Register</strong> the flow&#39;s Production Webhook URL in <strong>Admin → Agent Flows</strong>.</li>\n</ol>\n<h2 id=\"tenant-setup\">Tenant setup</h2>\n<p>Dashboard → <strong>Agent Workflow</strong>: switch engine to <strong>n8n flow</strong>, pick the flow,\nclick <strong>Generate</strong> to mint a bridge token, paste it into the AIRE node fields in\nn8n (or leave the node defaults, which read it from the injected payload). Name\nthe personas — those names/prompts are what the flow injects.</p>\n<h2 id=\"safety-notes\">Safety notes</h2>\n<ul>\n<li><strong>Injection, not access</strong>: n8n only ever gets data via the scoped bridge\nendpoints; it holds no DB access and no provider keys.</li>\n<li><strong>Fallback</strong>: any n8n failure (unreachable, disabled flow, non-2xx) falls\nthrough to the built-in assistant, so WhatsApp never goes dark.</li>\n<li><strong>License</strong>: stays free only while tenants don&#39;t get n8n editor logins. The\nadmin-builds / tenant-selects model is what keeps it within internal use.</li>\n</ul>\n"}];
